__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Gardien du Secret, puis-je demander quand je pourrai visiter le cimetière de l'académie ? Les grandes âmes qui y sont enterrées m'apporteront sûrement une inspiration extraordinaire ! Ne vous inquiétez pas, je promets de ne plus déterrer ces corps pour les observer de près..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Bavardage : À propos du modèle"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Attendez ! J'ai pensé à une nouvelle manière d'exprimer, qui va sûrement secouer le monde de la peinture !"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Je suis la lumière et l'ombre, je suis la couleur, je... suis la peinture elle-même !"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Sss... une couleur que je n'ai jamais vue, brille dans ton monde spirituel... qu'est-ce que c'est..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_100338_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Quelle peinture noire incroyable ! J'ai déjà collecté beaucoup de liquide corrosif pour peindre, mais finalement, toutes ces œuvres ont disparu. Des couleurs venant de l'univers primitif, toutes les toiles englouties, oubliées par quiconque... N'est-ce pas encore mieux ?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Laisse-moi m'approcher un peu... Laisse-moi voir un peu plus ! Ces lumières et ombres, ces couleurs, ces poses... Comparés à elles, tout ce que j'ai dessiné auparavant n'est qu'un tas de papier brouillon..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_100340_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Dursain me parle sans cesse de l'aspect artistique de sa cuisine, me demandant de voir que manger n'a rien à voir avec l'art ! Non seulement il faut gaspiller un temps précieux de création à s'occuper de ces complexes travaux de préparation des cadavres, mais une fois qu'il a enfin créé un plat à la fois beau et bon, il faut encore le mâcher et l'avaler ! C'est tout simplement un crime contre l'art !"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Mauvais modèle..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "Non, non, encore une œuvre terrible... Où aller chercher de l'inspiration ? Un cimetière ? Ou un lieu d'exécution..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Bien que je trouve que la sculpture est une forme d'art un peu trop rigide et conventionnelle, cette sculptrice nommée Shan, dont le ciseau possède une expressivité qui dépasse ce que cet art peut offrir... c'est vraiment un talent rare !"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Bavardages : À propos de Shan"
  },
  Voice_100345_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Sanga\""
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "As-tu vu cette peinture, Gardien du Secret ? C'est un portrait que j'ai fait de vous. Regardez comme vous dévorez les cadavres, c'est si fascinant ! Je sais que tout le monde ne peut pas comprendre mes œuvres, mais la beauté folle que cette peinture transmet, vous l'avez forcément touchée, n'est-ce pas ?! Pour moi, c'est déjà suffisant, totalement suffisant..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_100346_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Vous venez de dire que vous vouliez acheter cette peinture... Est-ce vrai ?! Merci, merci, Gardien du Secret ! Très peu d'humains peuvent apprécier cela..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_100347_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Gardien du Secret, as-tu encore du temps récemment pour être mon modèle ? Comparé à la scène que j'ai vue sur toi la dernière fois, les autres modèles ne font que me faire perdre mon temps..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "Dans cette œuvre, témoignez de la renaissance !"
  },
  Voice_100349_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_100350_AwakerVoiceContent = {
    Text = "Regarde ces lignes vivantes !"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "J'ai un pressentiment que ce que ce pinceau va créer, émerveillera tout le monde !"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah ! Une peinture nouvelle et surprenante... Je vais l'appliquer au bon endroit !"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "C'est vraiment un endroit inspirant ici ! J'ai de nouvelles créations, Gardien du Secret, avez-vous du temps récemment pour visiter mon atelier ? Allez, allez !"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_100353_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Exactement, exactement ! Une victoire arrosée de sang ! Quelle composition merveilleuse !"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100355_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah ! Asseyez-vous, Gardien du Secret. Être mon modèle est un travail difficile. Ne vous inquiétez pas, je vais vous créer une œuvre incroyable."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_100356_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Un artiste ne devrait voir que son œuvre et ne pas se soucier du regard des autres, mais je ne peux pas... Depuis le jour où j'ai pris le pinceau pour la première fois, j'ai espéré pouvoir apporter la véritable beauté à tout le monde."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_100357_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Cela me rappelle les temps passés à l'académie de peinture. Bien que la plupart des professeurs et des camarades soient des gens totalement ignorants de l'art, il y a toujours une ou deux personnes éclairées qui peuvent entrevoir la beauté que je perçois dans mes œuvres."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Quel genre d'art fou cette performance barbare va-t-elle encore engendrer ?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "Ma palette !"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "La douleur est aussi un art..."
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah ! Je l'ai vu... cet Œil Aveugle caché sous l'Abîme, cette vision ultime de l'univers... Attends encore un peu, Gardien du Secret, nous allons bientôt y arriver !"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_100362_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Mon pinceau, fait avec mes os du tibia. Ma palette de couleurs, ces teintes que j'ai collectées dans les cimetières de vingt villes... Et ma précieuse toile en cuir ! Gardien du Secret, prenez cela et peignez-moi un portrait ! Non, non, non, il n'est pas nécessaire que vous ayez des compétences en peinture... Je suis sûr que lorsque cette résonance spirituelle se manifestera sur la toile, ce sera une œuvre d'une beauté que je n'ai jamais imaginée... !"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_100363_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Je suis lumière et ombre, je suis couleur, je... suis la peinture elle-même !"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "Essaye cette couleur !"
  },
  Voice_100365_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_100366_AwakerVoiceContent = {
    Text = "L'essence de l'art est la folie... !"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "Vous voulez dire que je peux essayer de faire un gros plan sur cette partie dans ma prochaine œuvre ? Hmm... Je n'y avais même pas pensé ! C'est vraiment une idée géniale !"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_100368_AwakerVoiceContent = {
    Text = "Attention !"
  },
  Voice_100368_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "L'essence de l'art est la folie... !"
  },
  Voice_100369_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_100370_AwakerVoiceContent = {
    Text = "Ma palette !"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "Oh ! Cette mâchoire fluide, ces yeux brillants, cette silhouette parfaite, et, et ce monde spirituel aussi vaste qu'un ciel étoilé... Je suis le peintre Pickman, puis-je avoir l'honneur de vous inviter à être mon modèle ?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_100372_AwakerVoiceContent = {
    Text = "La philosophie artistique à laquelle je crois est folle et agitée, alors que la musique de Hameln est complètement différente, aussi rigoureuse que les pierres tombales moroses des cimetières. Mais je ne sais pas pourquoi, je parviens toujours à voir dans ces notes bien ordonnées le chaos le plus intense des profondeurs de l'univers..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Bavardage : à propos de Hameln"
  },
  Voice_100372_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Hameln\""
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Regarde, Gardien du Secret ! Cette vision éternelle et folle sur la toile, combien elle est envoûtante, combien elle est désespérante ! C'est dans cette folie ultime et cette souffrance que s'épanouit l'art..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_100373_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah ! Désolé, Gardien du Secret... J'ai vu en toi des visions sans précédent... plus terrifiantes que l'Abîme, plus fascinantes que l'Abîme..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_100374_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Je ne comprends vraiment pas, si les humains en avaient l'occasion, pourquoi ne pas devenir une goule ? Cette beauté sauvage et sanguinolente, n'est-elle pas bien plus intéressante que d'être un humain sans passion dans un grand manoir ?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha !"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "Châtiment du péché !"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Châtiment du mal !"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Je reconnais qu'elle a un certain talent pour voler, mais une dame n'a pas besoin de telles ruses mesquines. Ce que je veux, c'est que tout le monde me le donne « de bon gré », non ?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_117791_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Ah ah ah, mes, mes, toutes les bonbons de Mizag sont à moi maintenant ! Qu'attendez-vous, suivez cette sorcière, préparons-nous à conquérir toutes les pâtisseries de Londinium !"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_117792_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Pas de don ? Alors cette sorcière va vraiment s'y mettre !"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Tu dis que la garniture de ces bonbons est commentée, on ne trouve vraiment aucune fente ou trou d'aiguille, j'aimerais vraiment que la personne qui a inventé ces bonbons aille travailler dans un restaurant à Mizag, chaque jour, elle pourrait inventer un nouveau dessert pour moi !"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Tu as mis en colère la sorcière !"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Avant, je pensais que les bonbons étaient trop simples et pas assez élégants par rapport aux gâteaux. Maintenant, il semble que j'ai sous-estimé ces petites choses colorées dans leur emballage en plastique. Surtout, comparé aux gâteaux, la durée de conservation de ces bonbons est bien plus longue. Je pourrais en stocker autant que je veux sans craindre qu'ils se gâtent. J'aimerais vraiment remplir toute la maison avec !"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Tu as trouvé une nouvelle friandise ? Montre-moi... Quoi ? Cette bague en bonbon est vraiment trop drôle, qui a une bague en diamant aussi grosse qu'un œuf ? Attends, que veux-tu dire en m'offrant une bague ? Explique-moi clairement !"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_117797_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "J'ai entendu dire qu'une sorcière est généralement suivie d'un mystérieux chat noir ; choisir ce chat errant du campus est vraiment trop dégradant pour une dame. J'ai donc décidé que tu porterais des oreilles de chat et agirais comme mon petit chat noir."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_117798_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Résister est inutile."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "Blablabla !"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "Y a-t-il vraiment des sorcières dans le monde ? Elles vivent seules dans des forêts où il n'y a même pas d'ombre humaine. Qui leur prépare à manger, fait leur lessive et prépare des desserts ? Si elles ne peuvent même pas prendre le thé de l'après-midi, à quoi bon vivre ainsi ? Rien que d'y penser, je n'en peux plus."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_117801_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "La sorcière est arrivée !"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "Tu as encore du chocolat dans les mains ? Très bien, donne-le-moi tout. Qu'est-ce qu'il y a ? Tes affaires sont mes affaires, n'est-ce pas normal ?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_117803_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Tu me demandes quel bonbon je préfère ? Laisse-moi réfléchir, le nougat aux noisettes a une saveur délicieuse, le chocolat au caramel est également très bon, les bonbons mous fourrés à la fraise et au raisin ont une texture intéressante, et il y a aussi une sorte de sucre d'orge qui peut être tiré très long, de couleur aussi belle que le miel... Non, je ne peux pas choisir, chaque bonbon a ses propres caractéristiques, de toute façon, il y a plein de bonbons dans le panier de citrouille, je les veux tous !"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_117804_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Mon objectif de vie actuel est de manger tous les bonbons du monde. Rien que de penser à combien de sortes de bonbons sont en attente pour moi, cela me remplit de motivation pour me lever chaque jour. Tu parles de gâteau ? Le gâteau est mon autre objectif de vie."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_117805_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Ne te fie pas à son apparence de gamin, en réalité il est assez vieux pour être déjà enterré. Ne parle même pas de bonbons, il n'est intéressé par rien que n'importe quel être vivant pourrait aimer. Donc, au lieu de lui offrir ces bonbons, je préfère que tu me les donnes tous, car je suis celui qui saura vraiment les apprécier."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Chit-Chat · À propos de Tulu"
  },
  Voice_117806_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Si j'étais une sorcière, je serais certainement une sorcière vivant dans un palais luxueux, avec une ambiance animée, et je ferais appel à dix des meilleurs chefs pour me préparer chaque jour des gâteaux et des bonbons différents... Tu dis que ça s'appelle une princesse ? Qu'est-ce que ça peut faire, je peux très bien être une sorcière princesse !"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_117807_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Hé, dépêche-toi de me préparer plusieurs sortes de dentifrice, non, je n'ai pas mangé beaucoup de sucre, je n'ai pas de caries, c'est juste un petit peu douloureux quand je dors la nuit..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des bonbons"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Bien que les règles du restaurant Mizag soient souvent agaçantes, leur compétence en pâtisserie, eh bien... c'est à peu près acceptable."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "Ce monde a vraiment tant d'endroits sombres et dégoûtants ; au lieu de s'inquiéter de la destruction du monde, pourquoi ne pas manger quelques bonbons de plus avant que cela n'arrive ."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Bien qu'il n'y ait plus de tapis en peau de mouton, de colliers en perles noires de mer ou de pyjamas en soie orientale, pouvoir se réveiller chaque jour dans une pièce remplie de bonbons, avec un panier de citrouilles débordant à portée de main, c'est peut-être cela, le vrai bonheur... Hé, ne souris pas si fièrement, tu dois continuer à servir cette demoiselle, tu as encore du chemin à parcourir !"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_117812_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Satané Mizag, tu oses m'empêcher de prendre des bonbons, eh bien, je les ai quand même mangés, n'est-ce pas ?"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "Que fais-tu ? Tu veux manger mes bonbons ? Hmph, ce n'est pas que je ne peux pas faire preuve de générosité et te les offrir, alors, appelle la grande sorcière pour que j'entende !"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Comment cela peut-il être appelé un voleur ? Je n'exerce que le pouvoir noble d'une dame."
  },
  Voice_117815_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_117816_AwakerVoiceContent = {
    Text = "La sorcière des bonbons de la justice est arrivée, tous les bonbons perdus doivent retourner à leur place légitime !"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Merde, espèce de rat, la sorcière se souviendra de toi..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Pourquoi cette petite souris peut-elle se permettre de fouiller les bonbons sans gêne, alors que je ne le peux pas ? C'est une discrimination envers les dames ! Un manque de respect !"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Pas de cadeau ? Alors la sorcière va vraiment s'y mettre !"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Je t'invite à des bonbons !"
  },
  Voice_117820_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_117821_AwakerVoiceContent = {
    Text = "Comparé aux serveurs des restaurants, tu es de loin le plus compréhensif, tu sais même préparer spécialement une portion de sucre pour moi, continue comme ça, mon serviteur exclusif."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_117821_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "Blablabla !"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_117823_AwakerVoiceContent = {Text = "Trop !"},
  Voice_117823_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_117824_AwakerVoiceContent = {
    Text = "Pourquoi tu m'arrêtes ? En tant que fidèle serviteur de Mademoiselle, tu ne devrais pas venir m'aider à prendre tous les bonbons... et les apporter, n'est-ce pas ?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Arrêtez-vous, braquage ! Je vous conseille de faire preuve de bon sens et de remettre tous vos bonbons, sinon, hum hum..."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Doux, dur, croustillant, feuilleté, lacté, fruité, aux noix, chocolaté… Ah, comment se fait-il qu'il y ait tant de types de bonbons que je n'ai jamais mangés dans ce monde ? C'est décidé alors, je vais proposer à Mizag que nous célébrions le Festival des Saints une fois par semaine !"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_117827_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_117827_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "La grande sorcière triomphera ! Le dieu des bonbons me protège, et moi, je protège tous les bonbons ! Ahahahaha !"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Résister est inutile."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Tous les bonbons m'appartiendront !"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "Cet enfant est un peu effrayant dans son obéissance, dès que tu lui demandes des bonbons, elle te les donne, même sans en garder un pour elle, ce qui est un peu gênant... Hum hum, je veux dire, puisque elle est si compréhensive, la gentille sorcière lui laissera bien quelques-uns en récompense."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Lily\""
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Tu as mis en colère la sorcière !"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Je suis en colère !"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "Tous les bonbons m'appartiendront un jour !"
  },
  Voice_117834_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_117835_AwakerVoiceContent = {
    Text = "Que dis-tu, cette barbe à papa peut aussi être rôtie ? Hein, quelque chose de chaud et collant peut-il être bon ? Laisse-moi essayer ? D'accord, je vais prendre une bouchée à contrecœur, mais si tu oses me tromper... Hmm ?! Cette texture croustillante et moelleuse, si délicieuse !"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_117835_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Illusion, inversion, c'est le destin !"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Illusion, inversion, c'est le destin !"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Parce que tu as fait face à une véritable terreur, tu n'auras pas peur de moi ? Hmph, c'est une réponse assez astucieuse, mais cela me rend aussi... de plus en plus curieux à ton sujet."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_123312_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "À quoi ressemble le monde à travers tes yeux ? Où sont ces extrêmes terrifiants ? Non, je ne veux pas t'entendre le décrire ; je veux l'expérimenter avec toi—la folie, la mort, l'horreur. J'ai pris ma décision ! Je ne te quitterai pas tant que ma curiosité ne sera pas satisfaite."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_123313_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Un fou incontrôlable ? Tu as raison. Ce n'est pas mon monde ; il n'y a pas de lois ou de règles ennuyeuses ici... Ici, je peux faire ce que je veux, alors Gardien, tu ferais mieux de faire attention—ne te fais pas mordre par un fou hors de contrôle."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_123314_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Pour ma santé mentale et physique, tu veux avoir une conversation profonde ? Très bien, commençons rapidement—cette chose ennuyeuse, plus vite nous commençons, plus vite ça se termine."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_123315_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Je faisais juste semblant d'être une personne normale pour répondre à ta question ? Ah, tu m'as découvert—es-tu prêt à voir ma vraie forme ?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_123316_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Découpe ta tête."
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "Tout le monde, jeunes et vieux, l'adore ! Tornade scintillante— !!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "Ce ne devrait pas être moi qui tombe..."
  },
  Voice_123772_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_123773_AwakerVoiceContent = {
    Text = "Impact de tempête !"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "Tu veux sauver ce monde tordu et terrifiant ? Quelle façon folle et intéressante de mourir—voyons jusqu'où tu peux aller."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Hé, les petits, voulez-vous essayer ma hache ? Ne vous inquiétez pas, ça arrive tout de suite..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Gardien, il semble que j'ai vu la lumière. Serait-il possible que cette fois-ci... Je me demande comment vont mes collègues de l'équipe d'enquête ? S'il te plaît, ne me laisse pas une tonne de travail ; je ne veux vraiment pas faire d'heures supplémentaires."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_123776_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Puis-je rentrer chez moi grâce à ce rituel ? Es-tu sûr ? Combien de fois cela a-t-il été... Eh bien, il n'y a pas de mal à essayer de toute façon."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_123777_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Haha, il s'avère que cette vie pleine d'adrénaline me convient beaucoup mieux que la routine quotidienne ennuyeuse !"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha !"},
  Voice_123779_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_123780_AwakerVoiceContent = {
    Text = "Ce ne devrait pas être moi qui tombe..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Supernova☆brillante—Rayonne !"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "Tout le monde, jeunes et vieux, l'adore ! Tornade scintillante— !!"
  },
  Voice_123782_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_123783_AwakerVoiceContent = {
    Text = "En ce moment, on dirait... que je fais un pas dans le brouillard. En parlant de brouillard, cela me rappelle ces petits gars dans la brume. C'est dommage que je ne puisse pas exprimer mes sentiments sur eux quand je suis de mauvaise humeur."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_123783_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Haïr ? Je ne dirais pas ça. J'espère simplement sincèrement que toutes ces réunions ennuyeuses, ces rassemblements sociaux et ces valeurs universelles disparaissent."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "C'est ça... Je sens que je me rapproche de mon « vrai moi »"
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah, un échec qui était à prévoir. La vie a ses hauts et ses bas, tu t'y habitueras... Mais quand même, merci d'avoir essayé cette fois-ci."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_123786_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Tout comme la catastrophe de brouillard, je ne sais rien de la dissolution. C'est ce qui la rend si fascinante, n'est-ce pas ?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Mouchette, l'équipe d'enquête... oh non, je ne suis plus l'avant-garde de l'équipe d'enquête. Alors, laissez-moi me représenter—je m'appelle Mouchette, juste une jolie fille~"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_123789_AwakerVoiceContent = {Text = "Va-t-en !"},
  Voice_123789_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "Ici, c'est trop près des établissements humains, avec des adultes ennuyeux partout... As-tu déjà pensé à déplacer l'école dans une forêt éloignée et inhabitée ?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_123791_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Je suis sur le point de tomber amoureux de ce sentiment de dérive dans un autre monde, les puissants Éveilleurs, l'effroyable érosion et les divinités inconnues ! Ah, tout est un soulagement loin de la société ordinaire !"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Il y a plus ? Je m'amuse comme un fou—dépêchez-vous, quelqu'un laissez-moi couper une autre hache."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_123794_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Un échec ne signifie rien... Je rigole. Vous feriez mieux de vous préparer et de m'attendre !"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Une tâche à accomplir ? Pas besoin de saluer la prochaine fois, nous sommes déjà assez familiers pour ne pas avoir à faire la « routine de salutations sociales »"
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Se sacrifier pour les autres est vraiment une idée folle et frustrante. Personne n'a le droit d'exiger cela des autres, pas même les dieux."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Salvador\""
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Pas mal du tout—"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Enfin, plus de faux-semblants... Maintenant, amusons-nous un peu."
  },
  Voice_123799_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_123800_AwakerVoiceContent = {
    Text = "Le rituel n'est pas encore terminé ? J'ai vraiment hâte de rentrer pour déguster un ragoût de Ravenloft et une tasse fumante de thé kava aux noisettes. Bien sûr, le thé noir de Ceylan et les pâtisseries andalouses ici sont également très agréables."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_123800_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Toujours en train d'améliorer mes capacités, n'as-tu pas peur qu'un jour je puisse perdre le contrôle...? Haha, je rigole."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "En fait, rester dans ce monde un moment n'est pas si mal. Je vais me souvenir de tout ce qui se passe ici et l'écrire, pour pouvoir le partager avec tout le monde chez moi quand je reviendrai. Hmm, appelons ça \"L'aventure de Mouchette dans un autre monde.\" Ça sonne bien, non ?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_123802_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "J'admets qu'elle est très mignonne... Oui, c'est vrai, la voir chasser et se battre avec ces chats errants qui traînent autour du campus est en effet assez adorable."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Bien que ce pouvoir ne me permette pas de retourner dans mon monde, devenir plus fort est toujours une bonne chose."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Femme de ménage, je l'ai fait aussi ; trouvons un moment pour qu'elle voit ma méthode de combat avec un aspirateur !"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Chat: À propos de Karen"
  },
  Voice_123805_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Karen »"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Haha, il s'avère que cette vie pleine d'adrénaline me convient beaucoup mieux que la routine quotidienne ennuyeuse !"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Un coup, un kill."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Alignez-vous un par un."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "Disparaissez !"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Ne pense pas et ne dérange pas, écoute et obéis aveuglément, car le monde profane n'est rien d'autre qu'un fardeau !"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Ne pense pas et ne dérange pas, écoute et obéis aveuglément, car le monde profane n'est rien d'autre qu'un fardeau !"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Tu leur demandes pourquoi leur tête est vide ? Eh bien, peut-être qu'ils sont nés comme ça."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Cesse ta colère et ton ressentiment, car toutes choses deviendront rien."
  },
  Voice_126949_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_126950_AwakerVoiceContent = {
    Text = "Une telle attention me rend incapable de résister à l'envie de te taquiner davantage."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_126951_AwakerVoiceContent = {Text = "Oups !"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "T'attends-tu à ce que je sois plus belle ou plus terrifiante ?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "La princesse née de la joie, sa robe brodée de fils d'or, sa peau ressemblant à de l'ivoire, avec le parfum de bois d'agar flottant autour d'elle, captive tous avec son regard enchanteur."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_126953_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Bientôt, elle se lassa de ce divertissement, car ses croyants se contentaient de répéter les mêmes routines, s'abandonnant à l'amour né du désir, ou au désir né de l'amour. La douleur de la perte et de la trahison les faisait souhaiter la mort, et leur stupidité l'ennuyait, tandis que leurs larmes l'épuisaient également."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_126954_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Vos regards mesquins me dégoûtent vraiment."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "La Dame en Rouge m'a envoyé plusieurs invitations à son salon. \n Le goût des pâtisseries exotiques est assez bon, mais... \n Elle aurait dû me dire plus tôt que dans sa résidence, les collations et les servantes ne signifient pas la même chose."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Chat: À propos de Sorel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Débloqué après avoir obtenu Éveillé«Sorel»"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "N'est-ce pas de l'amour ? Alors pourquoi la peur quand on est entouré ? N'est-ce pas du mépris ? Alors pourquoi les larmes quand c'est à jamais inaccessibile ?\nAh, as-tu maintenant peur de mon ombre ? Le parfum de la magnolia blanche s'est-il transformé en un musc écœurant et inexplicable pour toi ?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_126958_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_126959_AwakerVoiceContent = {
    Text = "...D'accord !"
  },
  Voice_126959_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "Hein ? Tu me demandes pourquoi ils ont ces motifs sous les aisselles ? Tu ne trouves pas ça vraiment amusant ?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Chat : L'Ordre de l'Enflure Gracieuse"
  },
  Voice_126961_AwakerVoiceContent = {Text = "Oups !"},
  Voice_126961_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_126963_AwakerVoiceContent = {
    Text = "Comparé aux offrandes des croyants, celles-ci me plaisent davantage."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "D'abord l'attitude, puis la silhouette, jusqu'à ce qu'elles possèdent aussi une paire... ou plutôt, ce qui restait à se souvenir était une paire d'yeux magnifiques et émouvants—tout comme les miens."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_126964_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Je m'ennuie vraiment aujourd'hui. N'as-tu pas de souhaits qui ont besoin d'être réalisés ?\nC'est tellement dommage que tant de gens soient prêts à brandir leurs faux et à m'offrir du sang et de la chair, tout cela pour des raisons ennuyeuses.\nMais si c'était toi..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_126965_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Pourquoi la Foule encombrante me suit–elle, et quelle est sa genèse ? Une question amusante. Avez–vous, vous aussi, connu la personne inaccessible, ou le regret d'un combat perdu ?\nHmm, il semble que non. Quel dommage. Ce regard de lutte désespérée — ce serait si amusant à contempler sur votre visage."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_126966_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...Si tu continues à être aussi présomptueux, ce que j'utiliserai pour te faire face ne sera peut-être pas cette attitude."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Son histoire, je l'ai presque complètement oubliée, mais c'est une histoire de joie, une histoire de cruauté, une histoire qui commence par l'abandon et la rétribution, et qui devient ensuite une histoire de sacrifice et d'obéissance."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_126968_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Fais-moi plaisir, et laisse la douleur et la peur vous pousser à vous tuer les uns les autres~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...Cela a en effet piqué un peu mon intérêt."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Tout le monde verra le visage de son bien-aimé sous mon éventail. Je prête ce pouvoir aux faibles, devenant une lame pour le divertissement. \n Mais peut-être, je ne fais que dire, peut-être. \n Si tu es prêt à être captivé par cela, je ressentirai une véritable extase suprême."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_126971_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "Ne t'inquiète pas, tu es différent de ces insignifiants. \n Chut, ne regarde pas derrière moi, ne fais pas attention aux touches invisibles—regarde juste dans mes yeux."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_126972_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*Rires. Osez-vous contempler ma véritable forme ?"
  },
  Voice_126973_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_126975_AwakerVoiceContent = {Text = "bruyant."},
  Voice_126975_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_126976_AwakerVoiceContent = {
    Text = "Quoi ? Tu es encore en train de fixer mon éventail, captivé ? \n Hehe, peu importe le visage que tu souhaites voir sous l'éventail, je te satisferai... Viens, approche-toi un peu— \n Oh, tu ne veux pas ? En disant de si froides paroles, pourtant ton expression est plutôt mignonne..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_126976_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Vous êtes venu au Pays sans Rêve, que cherchez-vous ?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Cesse ta colère et ton ressentiment, car toutes choses deviendront rien."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "Ne sois pas impoli."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_126980_AwakerVoiceContent = {
    Text = "...D'accord !"
  },
  Voice_126980_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "J'ai une fois eu une belle petite fille timide comme ça. \n Un bouton de fleur frappant, bien sûr, doit avoir quelques épines ajoutées ; il ne peut pas simplement être planté dans un vase."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Chat: À propos de Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Lily\""
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "L'académie a fermement rejeté ma candidature pour travailler dans la salle de conseil. C'est vraiment étrange, qu'est-ce qui pourrait bien être le problème ?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Tout finira par revenir à l'éphémère, alors pourquoi ne pas chercher un peu de plaisir avec moi ? \n Soyez assuré, si un jour vous ne pouvez pas résister, je ne le laisserai pas vous prendre en premier."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_126984_AwakerVoiceContent = {Text = "Ennuyeux."},
  Voice_126984_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "Tu es une personne vraiment remarquable, occupée par tant de choses extérieures dans un monde destiné à la destruction. \n Cela éveille même mon propre intérêt."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_126985_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Ne t'approche pas trop !"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "Je suis Xu, la Dame du Pays sans Rêves. S'il y a quelqu'un dans votre cœur que vous souhaitez voir mais que vous ne pouvez pas, je suis prête à attiser les flammes et à vous accorder un aperçu."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_127088_AwakerVoiceContent = {
    Text = "Tous les descendants des êtres vivants peuvent être assez problématiques. \n Petits, doux et bruyants, ils retournent involontairement tout ce qui les entoure. J'apprécie une ambiance animée, mais je n'aime vraiment pas ce genre de tumulte, alors s'il vous plaît, gardez-les à distance."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Ma petite fleur de jasmin, mon petit trésor, je me délecte de ce jeu de poupées~\nAh, quelques balivernes de bonne humeur, vous n'avez pas à vous en soucier."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "Dans les légendes de l'Empire Panlong, le paon est une bête belle et flamboyante. \n Beau mais malveillant, son cri est à couper le souffle ; s'il était laid mais gentil, il serait plutôt ennuyeux."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Miam miam ! Glouton !"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_129652_AwakerVoiceContent = {Text = "Glou glou~"},
  Voice_129652_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "petit charbon, moi, manger, ensemble ? Ensemble !"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_129653_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Mosk ! Très fort !"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Abîme ! Spirale ! Destruction ! Tout——deviens Vortex !"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "Ne me touche pas ! Touche-moi, et ça va casser !"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_129657_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Coquillage, brillant ! Brillant, beau, voilà !"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_129658_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Froid et effrayant, Mosk, cache-toi !"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Bavardage : sur la poupée"
  },
  Voice_129659_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Poupée »"
  },
  Voice_129660_AwakerVoiceContent = {Text = "Ahou !"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Chasse, maudit ! Détruisez ! Mosk, frappez-les, détruisez !"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "Tellement amusant ! La prochaine fois ! Je veux encore !"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_129662_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Caresse, bien ! Mosk, toi, caresse !"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "Non, non ! Petit charbon, Mosk, protégez !"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Encore ? Encore !"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Hihi, Mosk, on joue !"
  },
  Voice_129666_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_129667_AwakerVoiceContent = {
    Text = "La grande vague arrive !"
  },
  Voice_129667_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_129668_AwakerVoiceContent = {Text = "Lâche !"},
  Voice_129668_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_129669_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_129670_AwakerVoiceContent = {Text = "!"},
  Voice_129670_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_129671_AwakerVoiceContent = {
    Text = "Rituel ?! Emmène-moi avec toi !"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_129671_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "Vortex ! Force ! Bâton !"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_129672_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_129673_AwakerVoiceContent = {Text = "Boum !"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_129674_AwakerVoiceContent = {Text = "Super !"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_129675_AwakerVoiceContent = {Text = "Ouf ouf~"},
  Voice_129675_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_129676_AwakerVoiceContent = {Text = "Bagarre !"},
  Voice_129676_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Goliath"
  },
  Voice_129676_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Goliath\""
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "Trouvé beaucoup, brillant de mille feux !"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_129677_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "Abîme ! Spirale ! Destruction ! Tout—devient Vortex !"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_129679_AwakerVoiceContent = {Text = "Waouh !"},
  Voice_129679_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_129680_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "Mosk ! Très fort !"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "Miam miam ! Glouton !"
  },
  Voice_129682_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_129683_AwakerVoiceContent = {
    Text = "Le Nautilus, Nautila, petit charbon ! Brillant !"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Mosk, chargez les munitions !"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "Compétence·Deux·Rechargement·Un"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "Mosk, chargez !"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "Compétence·II·Chargement·Deux"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "Étreindre ! Mosk ! Comme !"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_129686_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "petit charbon, ami ! Mosk, pour toujours !"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "Dépêche-toi, dépêche-toi !"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_129688_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Mosk ! Petit charbon ! Ensemble, toujours ? Pour toujours !"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_129689_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Ouah ouah~ Laissez les grandes vagues se lever !"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_129690_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Ami ! Tant de choses ! J'aime ça !"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Mosk ! Impressionnant !"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, veux voir. Eh, Nautila, Mosk, Mosk !"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Nautila"
  },
  Voice_129693_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Nautila »"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Devenu plus fort !"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Moi ! Mosk ! Bonjour !"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_130511_AwakerVoiceContent = {Text = "Ouf—"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Compétence·Deux·Chargement·Trois"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "L'erreur doit être corrigée."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "La tragédie devant vous n'est qu'un regard parmi d'innombrables possibilités.\n\nAu–delà du rideau du Destin se trouve une scène engloutie par les ténèbres —\nlumières éteintes, acteurs disparus, tout retournant aux profondeurs.\n\nMais ce n'est pas là que cela s'achève.\nJe porte la résolution d'endurer ce labeur ingrat, jusqu'au jour où les lumières reviendront."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "Le Destin de chaque âme est porté par des fils... mais le vôtre est un script que je ne peux déchiffrer. J'ai hâte de voir quelle improvisation vous apporterez à ce monde."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "La scène a toujours été la vôtre. Avancez, chère marionnette."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_133724_AwakerVoiceContent = {Text = "Hmm?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Tout est un épilogue passé. Tout est un nouveau prologue. Le nouveau chapitre entre nous attend que vous l'écriviez, Gardien."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_133725_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Si la comédie est votre inclination, <Italic:Un rêve d'une nuit d'été> vous conviendrait parfaitement. J'affectionne particulièrement les divagations espiègles de Puck — cachée dans le rire d'un lutin, le Destin laisse toujours échapper quelque chose."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_133726_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Soumettez–vous."
  },
  Voice_133727_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_133728_AwakerVoiceContent = {
    Text = "Le fuseau du Destin se met à tourner."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Prisonnier du Destin, pitoyable comme toujours... ce qui est écrit ne peut être refusé."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Même celle qui observe toutes choses reste une actrice maladroite dans son propre script. Tenir la toile du Destin, tout en étant liée par ses fils — nous empruntons des chemins différents dans cette circonstance destinée, mais ni l'un ni l'autre n'a jamais véritablement abandonné ses labeurs ingrats. Insensé, peut–être. Illusoire, peut–être. Il en est ainsi pour moi, et il en est ainsi pour elle."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Tawil"
  },
  Voice_133730_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Tawil\""
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Un retournement inattendu ?"
  },
  Voice_133731_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_133732_AwakerVoiceContent = {
    Text = "Merci de m'avoir accompagné à travers tant de rideaux levés et baissés. Je ne vous décevrai pas — il reste encore bien des soirées à venir qui vous toucheront de manières que vous n'avez pas encore imaginées."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_133732_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Quelle chanteuse douée. Une voix offerte par la grâce, claire et brûlante à la fois, comme si elle s'élevait du Destin lui–même. Si elle devait se produire dans mon théâtre, j'imagine que même le public le plus exigeant serait pris au dépourvu."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Tinct"
  },
  Voice_133733_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Teinture »"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Les fils invisibles qui nous appartiennent, à vous et à moi, se sont depuis longtemps étroitement enroulés l'un autour de l'autre, tissant à la fois une cage et un chemin.\nJe ne peux voir où la cage finit, ni où le chemin mène.\nC'est précisément ce qui rend cette histoire si captivante."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_133734_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Les fils du Destin restent immobiles."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Elle visite souvent mon théâtre... mais je sais qu'elle ne vient pas pour les pièces. Elle semble utiliser cette scène pour conférer un certain raffinement à sa propre image. Un talent si remarquable, pourtant — le dépenser uniquement en spectatrice semble un gâchis. Cette dame n'est pas du genre à s'épanouir dans l'obscurité du public. Elle appartient à la lumière."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Chat: À propos de Sorel"
  },
  Voice_133736_UnlockDesc = {
    Text = "Débloqué après avoir obtenu Éveillé«Sorel»"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Je l'ai entendu jouer un jour. Cette musique faisait trembler l'âme... Peut–être devrais–je l'inviter à composer une symphonie du Destin pour ma prochaine production."
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Bavardage : à propos de Hameln"
  },
  Voice_133737_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Hameln\""
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Une autre histoire, magnifiquement achevée, touche à sa fin."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Je l'ai enfin vu dans son ensemble. L'infinie toile du Destin."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Si vous le permettez... je souhaite tisser une pièce qui n'appartienne qu'à vous et moi.\nPas de public, pas de répétition. Je souhaite simplement voir comment le fil que même moi ne peux lire commencera à s'agiter... quand vous entrerez dans la lumière."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_133740_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Quelle danseuse au Destin funeste. J'ai observé ses pas. La sienne est une beauté qui avance vers la ruine — chaque tour enflammant des flammes vertes, comme si elle tentait de brûler les fils du Destin, bien qu'en fin de compte ces fils ne feront que graver en elle quelque chose de déchirant et de vif. Si l'occasion se présente, j'aimerais écrire un ballet rien que pour elle."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Liz"
  },
  Voice_133741_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Liz\""
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Ici il est tissé. Ici il est pesé. Ici il est tranché."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Restez tranquille..."
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Un autre fil se révèle."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "Le rideau s'ouvre pour vous, et le script du Destin attend de commencer. Dites–moi : quel chemin destiné préféreriez–vous emprunter ? Une fin tragique, ou un joyeux commencement ?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_133745_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Je me suis pris d'affection pour ce tissage, jour après jour... Dans le geste silencieux et répété de chaque fil, je perçois les commencements et les fins de toutes les histoires. En regardant chaque rideau tomber, j'ai parfois l'impression de m'être élevé au–dessus du Destin lui–même. Et pourtant, nul n'échappe à la toile du Destin, et ne faire que regarder laisse, en fin de compte, un sentiment de vide.\nDans ces moments–là, je vais au théâtre. Pour jouer les peines et les joies que j'ai tissées de mes propres mains, mais que je n'ai jamais vécues."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Heh..."},
  Voice_133748_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "Ici il est tissé. Ici il est pesé. Ici il est tranché."
  },
  Voice_133749_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_133750_AwakerVoiceContent = {
    Text = "Le Destin s'éveille. Son murmure approche."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "Le théâtre a mis en scène une nouvelle comédie romantique, et je vous ai réservé une place parmi le public du Destin. À travers chaque longue nuit où les destinées s'entrelacent, j'attendrai en silence le moment où nos étoiles se rencontreront."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_133751_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Tirer si obstinément sur les fils du Destin...\n\nVous semblez plutôt impatient de lire votre propre histoire, non ?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Ce qui fut écrit approche."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Si vous souhaitez entrer dans le temple de la tragédie, permettez–moi de vous présenter <Italic:Antigone>. Prise entre la loi divine et le décret des mortels, chaque pas qu'elle fait retombe sur des fils que le Destin a déjà tissés, jusqu'à ce qu'elle pénètre enfin dans l'ombre profonde du tombeau de pierre. C'est précisément parce que ces chaînes ne peuvent être brisées que la volonté brûlant dans son frêle corps flamboie si vivement contre la longue nuit."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_133754_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Aucune fin n'est jamais véritablement certaine, et pourtant aucune n'échappe à la toile des causes et des conséquences..."
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "Sur les fils, je vois les couleurs passer par toutes les nuances de l'arc–en–ciel.\nIls s'étendent à travers une toile infinie, tissant des mondes sans limites et des possibilités infinies, jusqu'à former un motif plus beau que tout ce qui a jamais été vu.\n\nÀ la fin — dieu ou mortel, héros ou vilain — chacun est guidé par ces fils ténus, se précipitant tête baissée vers sa fin destinée sous le regard impassible du Destin."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Je pensais que plus rien en ce monde ne pouvait me surprendre... Vos goûts en matière de théâtre m'ont marqué."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_133757_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Les fils du Destin se connectent toujours dans l'ombre... Vous avez perturbé l'un de ces fils, et ainsi vous m'avez surpris."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_133758_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Je n'ai jamais aimé les représentations qui se contentent de se répéter. La raison même pour laquelle on entre dans un théâtre est d'assister à une scène vivante — une scène qui ne peut être recréée.\nSi elle ne fait que tourner comme une horloge, la scène devient une cage ornée, et regarder ne devient rien de plus qu'un pèlerinage fastidieux vers une fin que l'on connaît déjà.\nUne mascarade sans âme, aussi magnifique que soit la production. Qu'en pensez–vous ?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Ces fils coulaient autrefois en ordre parfait entre mes mains... jusqu'à ce que vous apparaissiez, envoyant à travers leur cours des ondulations que je n'avais jamais prévues."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_133760_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Prisonnier du Destin, pitoyable comme toujours... ce qui est écrit ne peut être refusé."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "De fils infinis, je tisse l'unique chemin."
  },
  Voice_133762_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_133763_AwakerVoiceContent = {
    Text = "Sur la grande scène du Destin, toutes les âmes attendent leur signal dans la toile des causes et des conséquences, leurs joies et leurs peines prenant forme en silence tandis que les engrenages tournent...\nLe rideau s'est levé, Gardien. C'est ici que votre histoire, et la mienne, commence."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_133764_AwakerVoiceContent = {
    Text = "Le conflit est là. Allez–vous jouer le héros qui brise la toile, ou le joueur qui ne se meut qu'au gré des fils ?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Résistance futile."
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "Merci pour ce cadeau. Je le garderai précieusement."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "J'ai beaucoup étudié la structure des Corps éveillés, alors je me considère comme une experte à présent. Mais la « spiritualité » à l'intérieur des Cœurs d'argent... je ne comprends pas encore tout à fait cette partie."
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_139866_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "C'est ici... que commence un nouveau monde."
  },
  Voice_139867_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_139868_AwakerVoiceContent = {
    Text = "Je suis capable de faire ce genre de choses, tu sais. Comme réarranger ou modifier le corps d'autres créatures..."
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_139868_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Chaque être vivant est différent, alors avant de commencer à modifier quoi que ce soit, il faut vraiment les étudier attentivement."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_139869_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Tu n'as pas peur de moi ? Oh... c'est pas drôle..."
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Je ne laisserai personne se mettre en travers de notre chemin."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Je suis prête, à tout moment."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Les êtres vivants sont vraiment pleins de diversité. Je veux en apprendre tellement plus !"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Tu veux jouer avec Saya ?"
  },
  Voice_139875_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_139876_AwakerVoiceContent = {Text = "Aïe !!"},
  Voice_139876_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_139877_AwakerVoiceContent = {
    Text = "C'est ici... que commence un nouveau monde."
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "Je suis rassasiée. Merci pour le repas !"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Dis, Gardien... as-tu déjà aimé quelqu'un ? As-tu déjà vraiment regretté quelqu'un de tout ton cœur ?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_139880_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Ih !"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "C'est ici ?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "Bon travail ! Tu as trouvé quelque chose de bien ?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Après tous mes tests, je comprends beaucoup mieux maintenant. La « spiritualité » que porte chaque Corps éveillé — elles sont toutes complètement différentes. Et il semblerait que la spiritualité de mon Cœur d'argent soit... « l'amour »."
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_139884_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "Alors ? Je t›ai eu, pas vrai ?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Ceci est mon dernier cadeau... pour toi."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "« <Italic:Sur l'une de ces étoiles, ma fleur est en train de fleurir...> »\nJ'ai l'impression que tu as déjà dit quelque chose comme ça."
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_139887_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Il semblerait que les « Cœurs d'argent » soient chacun connectés à une volonté venue de très loin. Comme c'est mystérieux..."
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_139888_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Ceci est mon dernier cadeau... pour toi."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Ah !"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "Le Petit Prince dit que sa rose est devenue spéciale parce qu'il en a pris soin... Tu le penses aussi ?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_139892_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Hier, j'ai trouvé un livre intitulé <Italic:Le Petit Prince> sur l'étagère de Lily. C'était vraiment bien ! Tu veux le lire ?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_139893_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Oui, j'ai étudié la structure des Cœurs d'argent, et je commence à comprendre comment fonctionnent les Corps éveillés."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_139895_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Ah !"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_139897_AwakerVoiceContent = {Text = "Salut !"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Bien à vous !"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "Bonjour ! ...C›est la bonne façon de le dire ?\nJe suis Saya, et... ravie de vous rencontrer !"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_139901_AwakerVoiceContent = {
    Text = "Tu connais les pissenlits, n'est-ce pas ? Ceux qui envoient leurs graines au gré du vent. Une petite graine est emportée loin, très loin de sa terre natale... et peut-être qu'elle atterrit dans un désert où rien ne pousse — pas le moindre brin d'herbe. Je me demande... ce que cette unique petite graine peut bien ressentir... ?"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_139901_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "C'est amusant peu importe combien de fois on le fait !"
  },
  Voice_139902_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_139903_AwakerVoiceContent = {Text = "Hé !"},
  Voice_139903_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_139906_AwakerVoiceContent = {
    Text = "Attention !"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "J›adore la bonne nourriture ! Et j›aime les gens qui sont gentils avec moi ! Quand quelqu›un est doux avec moi... ça me rend vraiment heureux."
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "C›est elle qui m›a réveillé ? Elle a l›air vraiment... éblouissante. Alors, tu l›as aidée à retrouver sa sœur ?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Tinct"
  },
  Voice_140534_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Teinture »"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Chaque fois que je suis à côté de toi, des gens bizarres débarquent et se rassemblent autour de nous. En fait, je préférais quand on était juste tous les deux dans le Domaine."
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Compris. Je m'en occupe !"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Gardien, Lien, Corps éveillé. C›est comme ça qu›on est connectés. Tu me l›as expliqué. Je peux sentir nos âmes liées ensemble... comme un fil d›argent ? Hmm, ça a l›air un peu trop compliqué..."
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Propager des graines à travers la chair et le sang ? Hmm... intéressant. En fait, je suis plutôt curieux à propos de ses moutons."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Thaisis"
  },
  Voice_140538_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Thais »"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Certaines menaces pourraient apporter des ténèbres assez grandes pour détruire ce monde, pas vrai ? Je sais. Le Professeur Doll m›a tout raconté."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Je n›aime pas les gens brusques. Ils me donnent un mauvais pressentiment..."
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Oh ? Alors son espèce se reproduit sur de nouvelles planètes en s›attaquant à d›autres espèces. Hein, je vois..."
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Discussion : À propos de Winkle"
  },
  Voice_140541_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Bigorneau »"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Bon enfant."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Hé !"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Trois"
  },
  Voice_141965_AwakerVoiceContent = {
    Text = "...D'accord !"
  },
  Voice_141965_AwakerVoiceTitle = {
    Text = "Touché · Cinq"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Quel dommage. Quand vous changerez d'avis, vous saurez où me trouver."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_143501_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_143502_AwakerVoiceContent = {Text = "Maudit..."},
  Voice_143502_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "La peau, les muscles, les nerfs, les os, tout sera reconstruit, retrouvant santé et intégrité, retrouvant vitalité."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_143503_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Face à l'océan, il n'existe aucun ennemi indestructible !"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "Festin, Chasse, Refuge ?\nPriez-moi, les eaux les plus anciennes vous révéleront mon nom.\nJe suis le maître des abysses, Pontos."
  },
  Voice_143505_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_143506_AwakerVoiceContent = {
    Text = "Hehe, vous regrettez les instants passés à Ebwynnos ?...\nIl est là, dans ce corps, et vous accueille à tout moment."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Bien que je ne l'aie pas fait, si un jour vous entendez dans vos oreilles le bruit de l'eau de mer et le battement d'ailes, ne vous inquiétez pas, c'est tout à fait normal."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Offrez vos sens, et réfléchissez éternellement dans les abysses !"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "J'aime les jeunes gens pleins de vitalité. Hélas, Mizag réglemente bien trop strictement les festivités — il n'y a même pas un terrain de chasse digne de ce nom.\nEt en plus, à l'Intérieur se trouve cette chose immonde qui ose se pavaner ouvertement, arborant même le titre de professeur."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_143510_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_143511_AwakerVoiceContent = {
    Text = "Après tout ce que j'ai fait, vous refusez même de m'appeler encore une fois oncle — vraiment, c'est exaspérant."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Ne vous pressez pas, les ténèbres des profondeurs de l'océan vous Dévoreront inévitablement."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "À genoux, devenez l'engrais d'Ebwynnos."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Trois"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Quant à l'être qui m'a choisie... je dirais qu'il est à la fois bienveillant et malveillant.\nL'endroit où l'on atterrit dépend entièrement de son humeur ; il vous sauvera inévitablement d'un danger, mais que cet endroit soit un autre danger, ce n'est pas quelque chose que ce «voyage» a besoin de considérer.\nQue c'est intéressant, que c'est imprévisible — j'envisage de perpétuer cette tradition."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_143515_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "J'entretiens un lien particulier avec Ebwynnos — disons plutôt que je suis Ebwynnos, qu'Ebwynnos subsiste en moi, existant à travers mon corps."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Bavardage : À propos d'Ebwynnos"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Levez la tête, exposez votre gorge."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Effacer les souvenirs, effacer l'existence. Quelque chose de familier... vous comprenez ce que je veux dire. Bien que les origines soient différentes, il semble qu'Elles naissent toujours des endroits sans lumière."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Vous n'auriez pas dû être assez stupides pour empiéter sur ma majesté."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Trop faible."
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "À Ebwynnos, la fête ne s'arrête jamais, et les ennemis d'Ebwynnos ne connaîtront jamais la paix."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_143521_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "Ah, je ressens votre frisson, mais c'est tout à fait inutile, mon jeune ami.\nAcceptez votre peur de la médiocrité et de l'effacement, regardez-moi, vous comprendrez que vous avez toujours un autre choix."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_143522_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "C'est vrai, je sais que cette catastrophe n'était pas de son fait direct, juste un accident survenu au cours de ses divertissements — mais cela ne fait qu'accroître mon envie de le tuer.\nCette masse de brume noire ferait mieux de ne pas se retrouver seule, et de ne pas tomber entre mes mains."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Ces Murlocs visqueux ne sont pas mes amis, mais mes ennemis. Surprenant ? L'océan ne leur a jamais appartenu."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_143524_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Pour l'éternité, demeurez ici !"
  },
  Voice_143525_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_143526_AwakerVoiceContent = {
    Text = "Êtes-vous prêts, proies !"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "La spiritualité engendre de nouveaux corps, les corps sont remplis d'une connaissance insignifiante, puis ces individus beaux et vifs se rassembleront pour toujours en un même lieu.\nVous souvenez-vous de ce que j'ai dit, les profondeurs de l'océan accueillent tout... et retiennent tout."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_143527_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Cauchemar, bloquez-les."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "J'espère que ces petites créatures ne vous ruineront pas, vous savez, nourrir toute une famille n'est vraiment pas chose aisée."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Il y a très, très longtemps, avant que les terres n'émergent de l'océan, cette planète avait déjà éveillé certaines spiritualités particulières. Puissantes, majestueuses, impossibles à sonder.\nElles ne peuvent être définies ni comme hostiles ni comme bienveillantes ; les humains, comme d'innombrables créatures avant eux, leur sont indifférents — ils seront effacés comme de la poussière, ou protégés avec leur territoire."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_143530_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Seul le vieillissement est l'aventure que vous devez affronter seul, votre meilleur ami et votre ennemi le plus tenace, les lumières d'Ebwynnos le chasseront jusqu'au dernier... Juste quelques souvenirs sans importance, vous n'avez pas besoin d'y être ancré."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_143531_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Abandonnez toute illusion d'Évasion."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Vous serez réduits en une poussière grisâtre."
  },
  Voice_143533_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_143534_AwakerVoiceContent = {Text = "Hmph !"},
  Voice_143534_AwakerVoiceTitle = {Text = "Attaque"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Quelle astuce, petit, les Croyants des monstres venus d'ailleurs sont toujours assez stupides pour jeter des cadavres à la mer, mais ça ne compte pas vraiment comme un Cadeau, n'est-ce pas ?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Vous êtes déjà dans le collimateur."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Même si je répugne à l'admettre, en de très rares occasions, je me dis que le vieillissement n'est peut-être pas la seule chose que le temps apporte, mais Seulement un symbole.\nAlors, je lui permets d'exister en moi. Bien sûr — uniquement en apparence."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "La Prière est efficace. Imaginez : même si des insectes formaient des caractères léo devant vous, vous envisageriez quand même de répondre à leurs requêtes."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_143539_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Ha ha ha ha, allons, ne faites pas cette expression, mon petit ami.\nCe ne sont que des traditions que certains soi-disant «anciens dieux» doivent suivre. Quant à vous, sans aucun prix ni condition, je serai toujours de votre côté."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_143540_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Hmph, un petit monstre de mèche avec des monstres venus d'ailleurs.\nIl y a des imbéciles assez stupides pour nous mettre sur le même piédestal, lui et moi — c'est une insulte !"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Tulu"
  },
  Voice_143554_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "L'ennemi de mon ennemi est mon ami. Si l'occasion se présente, je ne serais pas contre conclure un bon marché : voler le jouet préféré de mon ennemi juré."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Ryker"
  },
  Voice_143555_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Ryker »"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "Oh ? Vous voulez vous battre contre moi, ici ? Cela me convient."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Encore — donne-moi plus de force !"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Je n'aime pas ceux qui ont le cœur divisé, car une telle division signifie généralement Faiblesse. Mais vous êtes une exception. J'ai cru autrefois que ceux qui portent trop ne pourraient jamais aller loin. Mais le chemin que vous avez choisi me surprend… Peut-être qu'un adversaire qui emprunte une voie différente est plus digne d'être aiguisé et défié. N'êtes-vous pas d'accord, « adversaire » ?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Cétus de la Mer Astrale — dévore-les tous !"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Sois honoré de te dresser contre moi !"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Que les étoiles témoignent de l'anéantissement !"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "Pas assez. Loin d'être assez…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Heh."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Hmph."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Je me soucie peu de la disparition de ce monde — mais je ne le laisserai pas entraver ma quête de la Force."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Douter de la valeur de l'existence simplement parce que l'oubli attend... Cela ne m'intéresse pas, ces débats puérils. La Destruction ne signifie rien, pas plus que la mémoire. La Force elle-même est le sens."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Doll : Dissoute"
  },
  Voice_146168_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Ruinée Poupée »"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Je vois une volonté étrangère dans tes yeux. Impure, mais suffisamment tenace. Allez, montre-moi quelle force ou quel désir t'a conduit jusqu'à moi."
  },
  Voice_146169_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_146170_AwakerVoiceContent = {Text = "Ha !"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "Sois honoré de te dresser contre moi !"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "L'odeur du chaos — comme c'est nostalgique… Depuis l'instant où je suis né de ce vide, ma quête n'a jamais changé."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_146172_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Vous souhaitez me défier ? J'admire votre courage, et je vous accorderai l'honneur d'être vaincu. Considérez cela comme mon respect envers le « Gardien de Mizag »."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_146173_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Une fausse utopie, peuplée de faibles, de lâches et de sots qui se font des illusions. Peu importe. Cet endroit m'apporte les adversaires les plus exaltants — et c'est suffisant."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Gaspiller une Force immense, emprisonner son talent dans un long rêve par peur, culpabilité et fatigue. Quel dommage."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Tulu"
  },
  Voice_146175_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "À peine digne de mon attention."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "Le sceau se desserre un peu… La force des profondeurs de l'univers remonte en moi. Je n'avais plus ressenti cela depuis une éternité…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_146177_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Cétus de la Mer Astrale — dévore-les tous !"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Exaltant."
  },
  Voice_146179_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_146180_AwakerVoiceContent = {
    Text = "J'ai erré dans le vaste cosmos pendant des éons ; j'ai précipité tous ces « puissants » dans l'abîme. Vous êtes unique, mais pour vous tenir à mes côtés, apprenez d'abord à garder la tête haute. Je n'ai que faire des lâches."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_146180_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Brave ou lâche, fort ou fragile… Heh — non, peu m'importe quel genre de personne est mon adversaire. Tout adversaire digne de ce nom me procure un véritable frisson."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "La Faiblesse. De toutes les choses viles en ce monde, la Faiblesse est le péché le plus abject. Chacun naît l'épée en main ; nul n'a le droit de céder avant la fin, ni de s'engager sur le champ de bataille du destin déjà résigné à la défaite. Cela insulte à la fois votre adversaire et vous-même."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Carcasse de Cétus corrompue — éveille-toi !"
  },
  Voice_146183_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_146184_AwakerVoiceContent = {
    Text = "Heh… Voilà qui était exaltant. La prochaine fois, je ne me retiendrai pas."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Mes os frémissent de joie… J'ai été témoin de tes efforts. Et cela prouve que tu es digne de te tenir à mes côtés, Gardien."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_146185_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Heh… Tu vois clairement, Gardien. Les entraves de la force sont faites pour être brisées !"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_146186_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Hmm?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_146188_AwakerVoiceContent = {Text = "Hmm?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Juste devant… le zénith de la Force que j'ai poursuivie toute ma vie… Vous avez marché à mes côtés et m'avez guidé jusqu'à ce seuil. J'ai hâte de témoigner de ce jour ultime avec vous !"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_146189_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Peut-être vous ai-je jugé trop hâtivement... Votre croissance et votre Force cachée m'ont surpris. J'ai vu d'innombrables vies s'effacer avec le temps, mais vous... êtes véritablement différent. Je suis fort curieux de connaître la véritable origine de votre Force."
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_146190_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Gueule de l'Enfer, ouvre-toi grand pour moi !"
  },
  Voice_146192_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_146193_AwakerVoiceContent = {
    Text = "Ah, je vois… la Force n'a jamais de fin. Le véritable défi ne fait que commencer ! C'est vous qui m'avez amené ici et m'avez montré la réalité. Bientôt, je vous présenterai un guerrier plus parfait. Assurez-vous de revenir encore plus fort, mon « adversaire »."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_146193_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Petits tours de passe-passe."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "La force bouillonne dans ma moelle !"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Dévorer — tout !"
  },
  Voice_146196_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_146197_AwakerVoiceContent = {
    Text = "Pitié, Faiblesse, confusion… vos yeux sont voilés d'impuretés. Celui qui vacille ne pourra jamais comprendre ce qu'est la Force."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_146197_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "La véritable Force n'a jamais eu de rapport avec la vengeance ou la protection. La Force est Juste la Force — l'autre moi n'a jamais «vraiment» compris cette vérité. C'est là la source de sa faiblesse."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Lotan"
  },
  Voice_146198_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Lotan »"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "Écoutez bien, je ne le dirai qu'une fois :\nMoi, Lotan, vous considère comme un adversaire digne de ma patience.\nJusqu'à ce que vous atteigniez votre apogée, je serai votre lame la plus fiable. Cette promesse n'a rien à voir avec les sentiments ou la loyauté. Vous êtes mon rival le plus exaltant, et je ne vous laisserai jamais tomber en chemin."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_146199_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Allez — tue-moi, ou sois tué."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Gueule de l'Enfer, ouvre-toi grand pour moi !"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "Là où pointe la lame d'os, tout s'effondre !"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "La force… n'a pas de fin !"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_147493_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(Une chanson rauque et douce)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Des spectateurs, il faut plus de spectateurs"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Sable... Désert blanc... C'est dangereux ici, partons vite ensemble"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_147496_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Je me rappelle des cartes de notre nouveau foyer, elles étaient en couleurs et magnifiques. C'est là que nous devrions aller. Nous pourrions chanter et être heureux"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_147498_AwakerVoiceContent = {Text = "Ah !"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_147499_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_147500_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_147501_AwakerVoiceContent = {
    Text = "C'était... la voix du firmament"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Te revoilà. Comme avant, assieds-toi à côté de moi et attendons ensemble. Attendre quoi... ? Juste attendre"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Répétition parfaite, je suis prêt à monter sur scène"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_147503_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_147504_AwakerVoiceContent = {Text = "Tomber."},
  Voice_147504_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "Dédié à la désolation et à la mort."
  },
  Voice_147505_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_147506_AwakerVoiceContent = {
    Text = "Je ne suis ni fou ni triste. Ne croyez pas aux rumeurs absurdes"
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Étrange, ils semblent craindre ma chanson"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_147508_AwakerVoiceContent = {Text = "Chut..."},
  Voice_147508_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Beau costume de scène, scintillant"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_147509_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Ô couleurs des étoiles qui subsistent jusqu'à aujourd'hui"
  },
  Voice_147511_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_147512_AwakerVoiceContent = {Text = "Chante."},
  Voice_147512_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_147513_AwakerVoiceContent = {
    Text = "Entraînement vocal correct... ? Mais j'aime ma voix actuelle"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_147513_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "La voix semble avoir changé"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_147515_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Alors, ma chanson est belle ?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_147517_AwakerVoiceContent = {Text = "Dors bien"},
  Voice_147517_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_147519_AwakerVoiceContent = {Text = "D'accord"},
  Voice_147519_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_147520_AwakerVoiceContent = {Text = "Ah !"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Merci... Dois-je vraiment dire merci ?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_147522_AwakerVoiceContent = {
    Text = "*soupir*..."
  },
  Voice_147522_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_147523_AwakerVoiceContent = {Text = ": Brille"},
  Voice_147523_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_147524_AwakerVoiceContent = {
    Text = "Ce sentiment oublié... enfin de retour sur scène. Merci, Gardien"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_147524_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Désolé de vous déranger... Pouvez-vous me descendre de cet arbre ? Je ne me souviens pas pourquoi je suis monté, peut-être à cause des nuages nostalgiques au-dessus"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Mon peuple ne m'a jamais quitté, ils sont juste partis très loin"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos des membres du clan"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "L'as-tu entendu?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_147528_AwakerVoiceContent = {Text = "Oh."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Tu sembles toujours rôder autour de moi... Je sais, tu dois être un de mes fans"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_147529_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "La la la~ Quoi ? Il y a un Clades qui menace la fin du monde ici ? Ah... Je dois me coiffer et retrouver ma sœur..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Chut... Ne parle pas, des méchants arrivent. Ils veulent nous capturer, ma sœur et moi, et nous empêcher de monter à bord"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Idle Talk · Sur la Sécurité"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_147532_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Quand je me suis réveillé, la planète était en train de se détruire. J'ai vu le ciel nocturne se déchirer, le monde devenant une toile soufflée par le vent, se déformant puis se déchirant et se fragmentant"
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_147533_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "C'est mon affiche signée, dessinée par M. Pikman. Je te la présente."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Discussion·À propos de l'Évanouissement"
  },
  Voice_147534_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Évanouissement »"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Hmm ? Curieux, sommes-nous ? Le coffre aux trésors d'une Marraine n'est pas fait pour les yeux des étrangers, vous savez. Si vous mourez d'envie de savoir ce qui est entassé là-dedans... pourquoi ne pas rejoindre l'Ordre Sacré dès maintenant... Hehe."
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Vous ne me croyez pas ? Snif snif... Je suppose qu'on ne peut vraiment pas tromper tout le monde... La vérité, c'est que je suis la fille illégitime de Bohémond VI de @1, vivant cachée parmi les mortels, et je n'ai prétendu être une fée que pour échapper à la traque de mes ennemis... Je vous ai confié mon secret le plus précieux. Vous ne pourriez pas... ne pas me croire... n'est-ce pas ?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_149668_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_149669_AwakerVoiceContent = {Text = "Aïe~"},
  Voice_149669_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_149670_AwakerVoiceContent = {
    Text = "Trop de bonbons ? Non non non, c'est le secret d'une Marraine pour garder son sourire, vous savez. Comme si je m'arrêtais pour une petite carie !"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Venez, tenez-vous ici aux côtés de votre Fée. Quoi ? Tout le monde partage les offrandes et mange ensemble ? ...Bien. Si c'est la coutume de Mizag... alors je... je n'y vois absolument aucun inconvénient. Allez, tout le monde, faisons la fête !"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_149671_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Oh là là, quel petit agneau pieux vous faites."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Encore un petit effort, et la Fée vous bénira, hmm ?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Vous êtes encore un peu novices~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "Cette cérémonie d'adoration sera plus grandiose que toutes les précédentes — et les offrandes devront être plus nombreuses aussi... Oh là là, on ne leur coupe pas les membres, bien sûr ! Je suis une fée au grand cœur ; je ne ferais jamais rien pour blesser qui que ce soit~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_149676_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Gardien du secret, êtes-vous prêt pour la confession la plus sincère de Caraboo, venue du fond de son cœur ?\nD'où je viens n'a aucune importance. Ce qui compte vraiment, c'est ceci : vous êtes un cadeau que le ciel m'a fait, et j'ai décidé de rester aux côtés de mon précieux bienfaiteur, pour toujours et à jamais. \nEst-ce encore un mensonge pour vous empêcher de fouiller davantage dans mon passé, demandez-vous ? Hehe, qu'en pensez-vous ?\nDe toute façon... je crois mériter une petite gâterie pour avoir partagé mes vrais sentiments avec vous. Un bonbon gélifié à la pomme ferait l'affaire, s'il vous plaît ?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_149677_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Hehe~"},
  Voice_149678_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "Ce n'est rien ! La prochaine fois, concentrez-vous sur la protection de votre Fée, et vous ne faillirez plus~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "N'essayez même pas de me tromper !"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "Waouh, autant de tributs...! Ahem. Hehe, bien joué, vous méritez une récompense ! Venez ici, je vous accorde le baiser d'une fée ! ...À quoi pensez-vous ? Sur le front, évidemment !"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_149683_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Merci à tous pour vos offrandes, fidèles ! Votre Marraine toujours compréhensive fera ériger une statue en or massif à votre effigie dans le temple. Oh là là — pour capturer cette silhouette froide et élégante qui est la vôtre, il me faudra simplement aller en collecter bien davantage~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_149684_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Vous ? ...Vous faites partie de notre troupeau, pas encore éveillé. Caraboo attendra, patiemment, le jour où vous verrez la vraie nature du monde. Et quand ce jour viendra — n'oubliez pas d'offrir votre corps, votre loyauté et vos biens terrestres à la Marraine de tous. Hehe."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Tout ce qui figure sur la liste... déjà rassemblé ? La fortune de Mizag est plus profonde que je ne peux l'imaginer... Si j'avais su, j'aurais... Hmm ? Vous demandez ce que je marmonne ? Je remercie simplement Seigneur Dexter pour sa générosité, hehe~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_149686_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "Ce que je déteste le plus ? Les sorciers qui ne respectent pas un contrat, évidemment. Voici un petit secret, rien qu'entre nous : chaque sorcier sans exception est un gros imposteur. Toutes leurs soi-disant prophéties et malédictions ? Rien que des tours pour vous escroquer jusqu'au dernier sou ! Et comment vous protéger...? Simple ! Laissez simplement tout votre argent recevoir la bénédiction de la Fée !"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Ravie de vous rencontrer ! Je suis une Fée Pâle venue de contrées lointaines. Envie d'en savoir plus ? La bénédiction d'une fée varie selon votre niveau d'adhésion, hehe~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_149689_AwakerVoiceContent = {
    Text = "Lors des cérémonies de vénération passées, en plus du rite septuple et du vœu triple, les fidèles me construisaient un tout nouveau temple et m'offraient de somptueux tributs. Voici la liste !"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_149689_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Allons... enfouissez tout ce que vous souhaitez abandonner au plus profond de la neige..."
  },
  Voice_149690_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_149691_AwakerVoiceContent = {
    Text = "Il paraît que vous cherchez à savoir d'où je viens. Hehe, c'est là le petit secret d'une Marraine. Maaais, si vous tenez absolument à creuser, l'Ordre Sacré conserve une biographie que j'ai rédigée moi-même. À vous pour la modique somme de cent mille Cœurs d'argent. Envie d'essayer ?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_149691_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Oh, c'est charmant ici — tant d'adorables enfants, et des aides sociales généreuses à en être indécentes. Avec tout ça, j'aurai bientôt économisé de quoi payer mon voyage vers l'Est..."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "N'oubliez pas de vénérer votre Marraine, hehe."
  },
  Voice_149693_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_149694_AwakerVoiceContent = {
    Text = "Toutes mes excuses, mais le domaine de la Fée est un lieu sacré — nous n'accueillons pas les loups-garous inconnus ici... Quelque chose dans l'air qui sent le mensonge ? Son nez doit juste être déréglé."
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Ryker"
  },
  Voice_149694_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Ryker »"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Hein ? Quelqu'un dit que je suis une fausse fée... Eh bien, je suis prise. Hehe. Mais je sais que ça ne vous dérange pas... n'est-ce pas ?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Discussion : À propos des rumeurs"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Mmm, délicieux~♪"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_149697_AwakerVoiceContent = {Text = "Là, là~"},
  Voice_149697_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "Petits agneaux égarés, votre Fée est là pour laver vos péchés, hehe~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Vous n'avez toujours pas abandonné ? Bien, bien — Caraboo vous le dira elle-même. Voyez-vous, Caraboo est la fille d'Umapati, déesse d'un certain sommet enneigé perçant les nuages à l'Est... Hmm ? Cette déesse avait deux fils et aucune fille ? Eh bien, les chroniques du divin sont toujours un peu... incomplètes, voyez-vous."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_149699_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Ta-daa~ la lumière de la Fée brille sur vous à présent. Allez, en avant !"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Bon, bon, arrêtez de creuser, voulez-vous ? Soyez un bon {Male=boy,Female=girl} et abandonnez cette petite enquête indiscrète, et je partagerai secrètement avec vous la moitié de mes bonbons les plus précieux. Vous savez, sur les champs de bataille des Croisades, les bonbons sucrés étaient un trésor rare."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_149701_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "La bénédiction de Caraboo peut guérir toutes les maladies du monde — y compris cette peste noire, bien sûr... Bien sûr que c'est vrai ! Il vous suffit d'être suffisamment dévot, de faire suffisamment confiance à Caraboo, hehe."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_149703_AwakerVoiceContent = {Text = "Aïe~"},
  Voice_149703_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "Contemplez la lumière de la Fée !"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "Le rite septuple, le vœu triple — offrez-les, et achetez-vous l'absolution de la Fée !"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "Ressentez-le !"
  },
  Voice_150079_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_150104_AwakerVoiceContent = {
    Text = "Hein, comment Ogier vous a-t-il laissé entrer ? Il avait promis d'empêcher tout le monde d'entrer. Vous êtes son suzerain...? Ugh, les petits enfants peu fiables, quel casse-tête. J'ai travaillé dur pour préparer ce rassemblement, vous savez. Disons... cinquante-cinquante sur les offrandes que nous recevons, et vous fermez les yeux pour moi ?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Discussion : À propos d'Ogier"
  },
  Voice_150104_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Ogier\""
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Dépêchez-vous de finir. Ne traînez pas dans les rues."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Il a rejoint le culte pendant que je dormais, donc je n'ai aucun lien avec lui.\nCependant, j'ai entendu qu'il est venu de son plein gré, voulant abandonner sa forme humaine pour devenir un \"Marin\" à part entière... Hmph, un autre imbécile aveuglé par le pouvoir."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Chat · À propos de Caecus"
  },
  Voice_36679_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Goliath n'a jamais été un chiot loyal. Je ne comprends pas pourquoi Miryam tient tant à lui... S'il n'était pas enchaîné, il serait le premier à s'enfuir."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Chat · À propos de Goliath"
  },
  Voice_36680_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Les marins ne naissent pas comme ça. Pour se fondre dans la masse, ils passent la première moitié de leur vie comme des humains...\nMieux vaut faire attention—le propriétaire de votre pâtisserie préférée pourrait être l'un d'eux !"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos du marin"
  },
  Voice_36681_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "La chanson de marin désaccordée de Céleste, le ragoût de poisson fumé signature du capitaine, les couvertures rendues poisseuses et rigides par la brise marine... Bien que ce fût dangereux et tendu, je n'oublierai jamais les mois que nous avons passés en exil en mer."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Bavardage · À propos de \"Navire Fantôme\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Bien que tout le monde à l'école semble très occupé...\nIci, il y a un sentiment de paix que je n'ai jamais éprouvé auparavant.\nLa sensation de se rassembler pour le même objectif et de lutter ensemble... Hmph, ce n'est pas mal."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag·II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "Le lit est trop dur, le temps est trop froid, et le thé de l'après-midi a toujours le goût de l'eau de rinçage de l'herbe... J'ai mille raisons de ne pas aimer cet endroit. \nCependant, juste parce que \"tu es ici\", je pourrais rester à contrecœur."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos du Gardien III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Merci... Hein ? Pourquoi je te remercie ? N'est-ce pas évident ! C'est pour tout ce que tu as fait pour moi en mer...\nAttends une minute, pourquoi est-ce que tu ris ? Tu veux juste me voir gêné, n'est-ce pas !"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Conversation Inactive · À propos du Gardien · II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "J'ai une fois pensé qu'il y avait un lien familial entre nous...\nMais après tout ce qui s'est passé, j'ai réalisé que ces moments éphémères de chaleur n'étaient rien d'autre que des pensées illusoires de ma part.\nCe que tu fais avec elle est ton affaire, ne la laisse juste pas s'approcher de moi."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Chat·À propos de Miryam·II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Comme c'est étrange... Ce sentiment est vraiment étrange.\nMon cœur a cessé de battre, mais mon corps est encore chaud... Hé, viens toucher ma main. Dis-moi que ce n'est pas une illusion."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Paroles décontractées · À propos de \"Réveillant\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 6 de \"Opération d'Investigation\""
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Je ne suis peut-être pas né dans le Royaume de Leo, mais la Grande Église est l'endroit où j'ai reçu ma seconde vie. Alors, pourquoi ne puis-je pas considérer cet endroit comme ma maison ?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Conversation Inactive · À propos du Foyer"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "Après des années de peste invisible, le Père Dieu a enfin entendu mes prières et m'a accordé la \"Bénédiction\" qui peut contrer la souffrance.\nElle accorde effectivement la vie, mais nécessite aussi un prix.\nEn tant qu'exécuteur, je dois naturellement porter le fardeau au nom des bénis."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Paroles décontractées · À propos de \"La Bénédiction\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Pour moi, l'état d'Éveilleur est un cadeau du Père à l'âme dans Son étreinte. C'est une seconde vie, une opportunité de réparer les regrets passés.\nJe continuerai l'œuvre du Père, remplirai mes devoirs en tant que Son substitut, et allégerai encore plus de souffrances."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Paroles décontractées · À propos de \"Réveillant\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Laissez-moi exprimer à nouveau ma gratitude, Gardien, pour avoir respecté mes souhaits et gardé mon secret vis-à-vis du Comité. S'ils intervenaient, je crains qu'ils ne me laissent pas continuer à servir l'Église."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Conversation Inactive · À propos du Gardien · II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Se débloque après avoir terminé l'Opération Spéciale « Bleu de Sang »"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Cet enfant est sincère, ferme et gentil, avec une Âme brillante rare. La dernière fois que j'ai rencontré quelqu'un comme ça, c'était au cours du premier chapitre de ma vie."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Discussion informelle · À propos d'Ogier"
  },
  Voice_45157_UnlockDesc = {
    Text = "Se débloque après avoir terminé l'Opération Spéciale « Bleu de Sang »"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Perdre ma vue ne signifie pas que je suis devenu aveugle. Bien que le Père m'ait apporté les ténèbres, Il m'a aussi permis de voir la faible lumière des âmes."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Chitchat·Sur la vision"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "\nÀ l'époque, bien que j'aie reçu \"La bénédiction\", j'étais juste une personne ordinaire. Il y avait trop de ceux qui souffraient, et trop de ceux qui avaient besoin de \"La bénédiction\". Je voulais les sauver tous, mais j'ai échoué.\nC'est mon plus grand regret et ma culpabilité éternelle."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Chitchat·À propos de la Première Vie"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Beaucoup dans l'Église pensent que la \"flamme blanche\" mentionnée dans les \"Saintes Écritures\" fait référence à la lumière de la lune : un pâle messager apparaîtra pour nous libérer de la souffrance.\nMais je sais que la véritable flamme est l'âme brûlant en vous et en moi"
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Paroles décontractées · À propos de \"La Flamme Pâle\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "En fait, l'Archevêque m'a dit de cacher ma véritable identité. Il n'a pas élaboré, mais m'a averti : même dans les lieux les plus purs, des ombres peuvent exister, et il faut rester prudent, même quand on fait le bien. Bien sûr, je vous fais entièrement confiance."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Petits Entretiens : Sur le Cacher d'Identité"
  },
  Voice_45161_UnlockDesc = {
    Text = "Se débloque après avoir terminé l'Opération Spéciale « Bleu de Sang »"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Mon chant vous a-t-il été d'une quelconque aide ?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Merde, il n'est qu'un enfant aussi ! Pourquoi vous le respectez tous tant ? Montrez-moi le même respect, compris !"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Chit-Chat · À propos de Tulu"
  },
  Voice_4909_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Hé, sais-tu ce que font généralement les autres Réveillés ? Ne te méprends pas, je ne veux pas d'amis, juste... ouais, juste vérifier !"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Discussion Idle : Sur la Vie Quotidienne"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Merde, merde, merde ! La prochaine fois, je jetterai leurs cadavres aux araignées pour qu'elles se nourrissent !"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "Lueur de fin"
  },
  Voice_4912_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_4913_AwakerVoiceContent = {Text = "Rythme."},
  Voice_4913_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Une Tentative Audacieuse"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "Pas besoin d’être si pressé... Y a-t-il quelque chose que je puisse faire pour vous ?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "Comment oses-tu !"
  },
  Voice_4916_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_4917_AwakerVoiceContent = {
    Text = "(Questionnement avec grand intérêt)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "La nature est la source de ma suprême honneur. Cela ne me ressemble-t-il pas ?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "Que veux-tu faire ?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "Pas mal, non ? Maintenant, la récompense. — Quoi ? Il n'y a pas de déjeuner gratuit !"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_4921_AwakerVoiceContent = {Text = "Va-t-en !"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_4922_AwakerVoiceContent = {
    Text = "Attention !"
  },
  Voice_4922_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "Quelle victoire glorieuse... Je vais graver ce moment dans l'éternité."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Ressenti la source d'impureté... Un pas plus près de la vraie forme... Ahhh, laisse-moi déchirer ce monde !"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_4924_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Nous sommes... prêts. Veuillez donner l'ordre, Gardien."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_4925_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "Sir, you are truly kind. Sadly, I have nothing with which to repay you, as I am just a worthless person... -> Monsieur, vous êtes vraiment gentil. Malheureusement, je n'ai rien avec quoi vous rembourser, car je ne suis qu'une personne sans valeur..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_4926_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......Encore un peu plus loin, et je serai complètement séparé de \"eux\" ?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_4927_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Hein, je suis encore en vie... Tu ne vas vraiment pas me voler mes organes ou m'utiliser pour des expériences ?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_4928_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "L'espèce native de Winkle peut entrer dans le cerveau biologique, rendant la volonté extérieure fusionnée avec moi qui la craint. Mais maintenant, elle n'est qu'une pauvre âme enfermée dans une coquille"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Discussion·À propos du Bigorneau"
  },
  Voice_4929_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Bigorneau »"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Tout, Aigis en profite. Que ce soit tout le monde rassemblé autour de la table pour un repas et une prière, ou l'anticipation lorsque le Gardien est en mission, attendant votre retour triomphant... L'air est toujours rempli de bonheur... Mérite-je vraiment une telle joie ?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_4931_AwakerVoiceContent = {
    Text = "Sink. -> Plongez."
  },
  Voice_4931_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_4932_AwakerVoiceContent = {Text = "Fleurir."},
  Voice_4932_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_4933_AwakerVoiceContent = {
    Text = "\"Confiance,\" \"Obéissance,\" \"Esclave,\" \"Affection,\" \"Respect\"... Reconstruction et apprentissage du module linguistique. S'il te plaît, Gardien, guide-moi."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_4933_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica est actuellement en mode veille. Le corps complétera le refroidissement dans 1 heure et 15 minutes. <Del:Pour commencer, échangez votre cœur> Démarrage d'urgence ? ... Vérification des permissions en cours... Autorité la plus élevée du Gardien vérifiée. Bonjour, Gardien."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_4934_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "L'indice de risque moyen des tâches d'investigation est de 7, avec une consommation moyenne de 8 bouteilles de suppléments d'alchimie et une moyenne de 10 heures nécessaires pour le traitement des corps.\nConclusion : Le travail des Gardien est extrêmement dangereux. Veuillez rester en sécurité pendant les opérations."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_4935_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Recherche dans les dossiers des enseignants : Erica Layfield, Chargée de cours en Mécatronique et Automatisation en Argent, Décédée - N'est-ce pas ce que vous cherchiez ? D'accord, nouvelle recherche sur le mot-clé \"Erica\"."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_4936_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Si tu as besoin de rechercher des informations, merci de fournir le nom complet du fichier. La fonction de recherche floue est actuellement indisponible."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_4937_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_4938_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_4939_AwakerVoiceContent = {Text = "Ah !"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_4941_AwakerVoiceContent = {Text = "Ah !"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Charge complète, prête à exploser."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Charge complète, prête à exploser."
  },
  Voice_4943_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_4944_AwakerVoiceContent = {
    Text = "Ne dérange pas le repos de la princesse avec des choses aussi triviales à l'avenir."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Je te protègerai tout comme je protège Tinct."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Je ne suis pas une personne importante, juste un humble suiveur parmi tant d'autres... Tant que je peux servir cet être grand et attirer son attention, je suis prêt à donner tout ce que j'ai."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos du Passé"
  },
  Voice_4946_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "Regarde-moi !"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "Regarde-moi !"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Ça va, tant qu'ils ne m'embêtent pas avec leur adoration fanatique. Partager une chambre avec eux n'est pas impensable."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos du marin"
  },
  Voice_4949_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'un des Éveillés \"Miryam\", \"Goliath\", \"Caecus\", \"Sanga\" ou \"Faros\"."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Je déteste ce sentiment sombre, comme si mon cœur avait été creusé. La sensation non satisfaite fait démanger tout mon corps..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "Ne le faites pas, ne le faites pas, ne le faites pas, ne le faites pas, ne le mentionnez pas..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha !"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_4954_AwakerVoiceContent = {
    Text = "...D'accord !"
  },
  Voice_4954_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "Les historiens proclamant bruyamment l'extinction du Royaume Divin sont agaçants... Mais peu importe; leurs paroles ne peuvent entraver le ravivement de la gloire du Royaume Divin."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "En fait... laissez-moi vous dire un secret. Je ne suis pas tout à fait satisfait de ma moto actuelle—ce n'est pas que je ne l'aime pas ! C'est juste que j'ai l'impression qu'il manque quelque chose..."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha !"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_4958_AwakerVoiceContent = {Text = "Coupez !"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Compétence·II·Manie"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Désolé... Je ne voulais pas que cela arrive..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Compétence·II·Dépression"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Chuchotement intrigué)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "En @1@2 année, M. Ward Phillips, Krelarkesh et Tawil ont fondé ensemble le Collège Mythag. Après un long développement, il a finalement donné naissance à <Del: cette maudite prison> l'Université Mythag."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Justice, loyauté, résilience, discipline. Ces valeurs sont depuis longtemps gravées dans mon cœur."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Je compléterai correctement la tâche que tu m'as assignée."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Quel genre de parents irresponsables donneraient à leur fille le nom de Bouclier de Banshee ? Tu dis que l'enfant n'a pas de parents ? Hmm... gardons cette conversation entre nous"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Chat · À propos d'Aigis"
  },
  Voice_4964_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Aigis »"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Si vous vous ennuyez, pourquoi ne pas \"me tenir compagnie\" dans le labyrinthe ? Après tout, votre vie désespérée n'est pas différente de ce labyrinthe sans fin !"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Chat · À propos du labyrinthe"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Lorsque la Poupée est présente, l'efficacité des enquêteurs augmente de 78,312 %, mais un plus grand nombre de personnes tombe également dans des déprimes émotionnelles. Comme elle l'a dit : \"Si certaines personnes pouvaient fermer leur bouche, le monde fonctionnerait plus harmonieusement.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Chat · À propos de la poupée"
  },
  Voice_4966_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Poupée »"
  },
  Voice_4967_AwakerVoiceContent = {Text = "Arrivée !"},
  Voice_4967_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_4968_AwakerVoiceContent = {Text = "Et alors ?"},
  Voice_4968_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Qui n'aime pas l'aventure ? Plonger dans des domaines mystérieux inexplorés, découvrir l'inconnu, et tisser votre propre histoire... Quelle excitation !"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Petits Entretiens · Sur les Aventures"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Salutations, je suis Nymphaea de Febvre. Vous m'avez donné ce corps qui respire librement... Que puis-je faire pour vous rendre la pareille ?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_4971_AwakerVoiceContent = {
    Text = "Je pense que je viens d'entendre ceux qui prétendent être mes maîtres se lamenter à nouveau — comme c'est charmant."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_4971_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Puis-je sauter les légumes ? Bien que Tinct ait dit de ne pas être difficile, je n'aime pas leurs couleurs..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Paroles du Dieu Relique : La souffrance n'est pas ma création. Supporte-la et dissous-la, mon représentant, et construis une terre sans souffrance. Pour cela, j'offre tout, même la vie."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_4973_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Face à la Malédiction de Fusion dévorante, d'autres souffrances pâlissent en comparaison. Même si je ne peux pas porter la malédiction pour les autres, je ferai tout mon possible pour alléger leur douleur."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_4974_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Suis-je maintenant capable d'apaiser leur douleur et de réconforter leurs âmes ?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_4975_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Ainsi, je porterai toute la souffrance, ouvrant le chemin pour tous les êtres vers une terre libre de douleur."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_4976_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Cette chaleur au fond de mon âme... Merci pour ce cadeau, le Feu Pâle. Avec ce Pouvoir, peut-être que je pourrai enfin remplir mon devoir en tant que Deputy et sauver plus de gens."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_4977_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Puis-je vraiment manger autant ?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_4978_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Hmm... Ce n'est pas la mort ; c'est simplement votre futur, mon futur, et le futur de ce monde."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Teinture... Entendre son chant mélancolique vous donne envie de danser..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Chit-chat·À propos de la Teinture"
  },
  Voice_4980_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Teinture »"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Un entraînement ordinaire peut-il aussi réveiller le potentiel de sa lignée ? Cela dépasse vraiment mes attentes."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "L'arme semble plus maniable."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Ne suppose pas que je te serai reconnaissant pour cela ; ma race ne le permet pas."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah, euh !"},
  Voice_4984_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_4985_AwakerVoiceContent = {
    Text = "Cet homme... Hé, attendez une minute, notre pari n'est pas encore terminé, n'est-ce pas ?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur les Autres"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "J'aime vraiment le dictaphone de l'académie. Si seulement je pouvais créer une version portable qui me rappelle en temps réel ce que j'ai oublié..."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Des miettes partout... Non, pas même des miettes, juste des vestiges, fournissant une nourriture pour son arrivée."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Les fournitures sont ici."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Les fournitures sont ici."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm... Plus fort, plus fort. Oui, comme ça..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Pas encore pleinement Réveillé, pourtant la victoire est venue sans effort."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Oh non, mon chapeau est de travers... Hmm, est-ce que c'est mieux ? Parfait !"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_4992_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"Avec une telle capacité, suis-je vraiment encore humain ?\" Depuis que j'ai commencé l'entraînement au combat, je me pose cette question chaque jour. J'aime ce monde, malgré son obscurité, sa saleté et sa monotonie, mais ta présence le fait briller comme des diamants au milieu de la poussière.\nJ'avais autrefois peur qu'à mesure que ma puissance grandisse, mon statut d'humain change... Maintenant, je suis reconnaissant de t'avoir à mes côtés. Notre lien me fixe fermement au monde humain. S'il te plaît, continue à veiller sur moi, Gardien."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_4993_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah... Il est tout à fait naturel que vous ayez des préoccupations. Je n'y ai pas réfléchi. En tant que votre partenaire, j'aurais dû expliquer cela dès le début. Comme vous pouvez le voir, je possède certaines caractéristiques inhabituelles, probablement liées à mon passé. Il est impossible de ne pas être curieux, n'est-ce pas ? Mais avoir un endroit comme l'académie est une bénédiction pour moi, donc je choisis de ne pas lever le voile du destin."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_4994_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "Tu as rencontré cette femme, n'est-ce pas ? L'Awakener dans un voile blanc—elle est l'une des fondatrices de l'université...\nMais franchement, je ne l'aime pas. Cette attitude distante, comme si elle ne se souciait absolument pas du monde, m'agace vraiment... Oh, tu penses qu'elle me ressemble ? Allons faire contrôler tes yeux à la clinique du campus."
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_4995_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Es-tu curieux de ma relation avec le professeur ? Ce n'est pas un secret, alors je vais te le dire. Le professeur Dexter est mon père adoptif. Quant à ma mère adoptive... J'ai grandi à l'école et j'étais pris en charge par tous les enseignants. Cependant, parmi eux, je suis le plus proche de Poupée."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_4996_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Que ce soit pour les procédures au Bureau des Réveilleurs ou pour le rendez-vous pour un repas indien à la cantine, je peux répondre à n'importe quelle question sur les affaires de l'académie—ne vous inquiétez pas de me déranger. Ai-je l'air si peu abordable ?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_4997_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Miroir, miroir, qui est le plus grand magicien au monde ? Moi ? C'est ça!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_4998_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_4999_AwakerVoiceContent = {Text = "Pas mal."},
  Voice_4999_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "Très bien~"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Est-ce que ça... a marché ? Ai-je pu t'aider ?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5003_AwakerVoiceContent = {Text = "Inutile !"},
  Voice_5003_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5004_AwakerVoiceContent = {Text = "(Endurer)"},
  Voice_5004_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "Regarde par ici !"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Que cet endroit devienne une mer d'excitation pour tous !"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "Besoin d'un gardien pour vous accompagner ? Si votre quête est juste, je vous aiderai."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5008_AwakerVoiceContent = {
    Text = "Impossible d'être complètement brûlé."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "Impossible d'être complètement brûlé."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Veux-tu un câlin ?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Regarde ces chaînes sur moi—ce ne sont pas des décorations, mais des rappels. Des rappels de trahison et d'humiliation."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Si vous voulez connaître le passé de l'académie, je vous suggère de consulter les archives.\nAllez, y compris son prédécesseur, c'est une histoire qui s'étend sur 300 ans ! Vous ne vous attendez pas vraiment à ce que je la raconte année par année, si ?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "C'est une provocation ? Je suis prêt à tout moment !"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Aequor vous accorde un repos éternel."
  },
  Voice_5014_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5015_AwakerVoiceContent = {
    Text = "Aequor vous accorde un repos éternel."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "Sink and burn! Danse vers la destruction!"
  },
  Voice_5016_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5017_AwakerVoiceContent = {
    Text = "Voici, la Danse de la Destruction de la Flamme Verte Éternelle !"
  },
  Voice_5017_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5018_AwakerVoiceContent = {
    Text = "Cette dame, comme un phare... Si j'avais pu voir sa lumière éblouissante pendant la nuit éternelle, peut-être que je ne me serais pas perdu..."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Chat · À propos de Faros"
  },
  Voice_5018_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Faros »"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Tu ferais mieux de prouver que tu es digne de me faire quitter le laboratoire, nouveau Gardien."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5020_AwakerVoiceContent = {
    Text = "Je suis le maître, et tu es le serviteur. Tout ce que je désire doit être livré immédiatement. Quel est le problème ? T'attends-tu à une récompense ? Très bien, très bien, prends-la !"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Déshonneur, que ce mouvement te purifie !"
  },
  Voice_5022_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5023_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Donner, c'est recevoir."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Donner, c'est recevoir."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Tu vas te blesser !"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "Ne t'approche pas !"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "J'aime la lumière dorée de la pleine lune. Elle est mystérieuse et douce. Quand le vent souffle, la mer scintille d'une phosphorescence dorée, comme une romance onirique."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Si notre maison n'avait pas subi de Dissolution, Tinct et moi ne serions pas séparés... Je déteste la Dissolution plus que je ne déteste les légumes."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Que ce qui se trouve devant nous soit un trésor ou un port, cela ne me fait aucune différence. Ma mission est d'assurer votre retour en toute sécurité."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5031_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Suivez la trace de l'oiseau du paradis ; la destination se trouve devant dans le bleu azur."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5032_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Je regarde souvent l'horizon, imaginant les scènes au-delà—une terre lointaine à laquelle je me rapproche mais que je ne peux jamais atteindre. Si ce jour venait, je te prie de m'accompagner pour le voir."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5033_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Merci pour votre gentillesse. Maintenant, même la mer déchaînée ne peut m'empêcher de vous transmettre mes bénédictions inébranlables."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5034_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "On dirait entendre les chants des rameurs, le goût familier de chez soi."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5035_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Es-tu ici pour me sauver ? Du monde en décomposition, de la haine qui tache mes yeux, des flammes vertes éternelles..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Récalcitrant escroc !"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "Je considère cela comme mon serment de loyauté envers vous."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5038_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Apprends ta leçon !"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5040_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5040_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5041_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5042_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "Ressentez le pouvoir du rat !"
  },
  Voice_5044_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5045_AwakerVoiceContent = {
    Text = "Ressentez le pouvoir du rat !"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "Le dé a été jeté. Alors, finissons cela rapidement !"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "J’inclurai ton nom dans mes remerciements. C'est toi qui as permis à ces pieds, teintés de sang noir, de fouler à nouveau le merveilleux monde du ballet. À partir de maintenant, s'il te plaît, regarde-moi danser, Gardien."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5047_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Peu importe combien tu luttes, tu ne peux pas défier le destin. Mais ce moment éphémère de brillance sera gelé dans l'éternité."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5048_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "Que devrions-nous faire de ces vaincus ?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Même si mon cœur n'a plus de désir, je jouerai toujours le rôle du cygne."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5050_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Fermez les yeux et dites-moi, que voyez-vous ? L'éclat immaculé de la lune, un lac tranquille..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5051_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Pourquoi les calamités de destruction et de malheur m’entrelacent-moi et ma sœur ?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Accepte mon affection."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Accepte mon affection."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Je me sens beaucoup mieux maintenant, merci."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5056_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Si possible, j'aimerais vous présenter un nénuphar violet pâle en signe de ma gratitude."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Puis-je devenir plus fort aussi ?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "C'est parti... !"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5060_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5060_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "Cette jambe blessée ? Je suis surpris que tu l'aies remarquée. C'est à cause du champ de bataille avant que je ne devienne une Réveillante.\nNe t'inquiète pas, cela n'interfère plus avec mes combats.\nDouleur ? Non, je n'y ai pas pensé."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5061_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Sylvia a demandé comment j'allais mentalement, c'est toi qui l'as envoyée, n'est-ce pas ? J'admets que la douleur fantôme revient parfois. Mais ne t'inquiète pas pour moi. Je suis ton épée, ta lame, tant que je peux encore combattre pour la justice, la douleur ne m'affectera pas"
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5062_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Tea party, tea party, organisons une tea party ! J'ai pris beaucoup de thé et de gâteaux chez Sylvia ! Oui, en échange d'une danse de Fortvoken !"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Mon titre autoproclamé ? Êtes-vous vraiment si intéressé par mes affaires personnelles ? Vous voulez juste discuter... très bien.\nDans l'armée, nous ne faisons pas de distinction entre camarades en fonction du sexe, y compris la force et la vitesse, et naturellement, aussi les coiffures et les titres. Avec le temps, je me suis habitué à cette façon de m'exprimer."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5064_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Intéressant... N'avez-vous pas peur que je vous déchire en morceaux et que je vous donne à manger aux poissons une fois que j'aurai le pouvoir ?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Pour être digne d'être mon Gardien, tu as certainement beaucoup travaillé !"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Il est temps de déchirer les gorges de quelques faibles et de leur donner une chance."
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "La danse est pure. Les mots peuvent mener à des malentendus, mais les pas de danse ne le font jamais."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur la Danse"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Je déteste la mer, et pour une bonne raison. L'océan a tout dévoré ce que j'aimais..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Que ce soit l'oubli ou la perte, cette fois nous allons certainement revenir !"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "Que ce soit l'oubli ou la perte, cette fois nous allons certainement revenir !"
  },
  Voice_5071_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5072_AwakerVoiceContent = {
    Text = "S'il vous plaît, s'il vous plaît, ne vous approchez pas. C'est dangereux."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5073_AwakerVoiceContent = {
    Text = "N'hésitez pas à toucher... Ce sont des cicatrices de l'arène, un insigne d'honneur pour un homme !"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Cri de douleur)"
  },
  Voice_5074_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5075_AwakerVoiceContent = {
    Text = "Aïe, aïe, aïe !"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "（grogne de douleur）"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "（Gronde imperturbable）"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "On dirait que quelque chose bout à l'intérieur du Corps. Est-ce cela, la sensation de subir l'Illumination ?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5078_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Est-ce une sorte de nouvelle technologie ? Mon membre prosthétique se sent beaucoup plus léger."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5079_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "La brise salée de la mer me dit que ma patrie n'est pas loin."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5080_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Les camarades disparus peuvent-ils retrouver leur chemin en suivant cette lumière ?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5081_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "J'ai cherché pendant des dizaines de milliers d'années ; un siècle éphémère n'est rien. Jusqu'à ce que j'atteigne votre rivage, je continuerai à vous aider."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5082_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Je brillerai uniquement pour ma patrie. Toi..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5083_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "J'ai senti la brise, portant du sable fin sur mes pieds."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5084_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "L'étendue de ma contribution à ton pouvoir s'arrête ici. Être trop avare n'est pas une bonne chose, tu sais ?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5085_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "Que t'attends-tu que je rende ? Juste une bataille ?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5086_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Crâne d'amour, crâne de ressentiment, crâne de haine, crâne de désirs... Oh, tu es revenue ?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5087_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Puisqu'il s'agit d'une transaction, je ne peux pas simplement accepter ton cadeau. Voudrais-tu choisir quelque chose dans la boutique ?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5088_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Je vais t'enseigner la joie, le plaisir, l'excitation d'atteindre le sommet... En retour, tu devras révéler honnêtement tes désirs, d'accord ?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos du Gardien 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Je suis l'Arbre Mère, et l'Arbre Mère est moi. La sève coule dans mes veines, et la volonté de l'arbre demeure dans mon esprit..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Conversation Inactive · À propos de l'Arbre Mère"
  },
  Voice_50899_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 7 de l' \"Opération d'Investigation\""
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Payer le prix de votre trahison !"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Je pense avoir vu ta pierre tombale en cherchant un endroit caché dans la Tombe Clé... Ma momie sera-t-elle enterrée ici aussi ? Non ? Quel dommage."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos de la Monticule de Clés"
  },
  Voice_50900_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 7 de l' \"Opération d'Investigation\""
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "Le gars loup... Il a une relation ambiguë avec ce N..."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Chat·À propos de Ryker"
  },
  Voice_50901_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Ryker »"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Approche, embrasse-moi, goûte-moi... n'oublie pas moi."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos du Gardien 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 7 de l' \"Opération d'Investigation\""
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "Elle était une enfant trop assidue et prudente. Bien sûr, je ne pourrais pas lui en vouloir~ Sans elle, la tribu libre d'esprit aurait été détruite au milieu des changements depuis longtemps, n'est-ce pas ?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Chit-Chat : À propos d'Alva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Alva »"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Né des sables jaunes, et aux sables jaunes tu retourneras. Lors de ce bref voyage, ne devrais-tu pas laisser quelque chose derrière et semer quelques graines ?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos du désert"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Tous les désirs proviennent de l'amour ; l'amour est la graine initiale avant que l'arbre géant n'émerge."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos du Désir"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Oh là là, une petite souris mignonne vient de passer en courant... J'ai entendu dire que les souris adorent se faufiler, mais hélas, celle-ci est encore trop jeune, pratiquement un nouveau-né."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_50906_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Ils ont porté mon sang et ma lignée, se transformant en les eaux florissantes de Lemwahi... À partir de ce jour, il est de ta responsabilité de veiller à ce que mon héritage perdure."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos d'Alan"
  },
  Voice_50907_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 7 de l' \"Opération d'Investigation\""
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Araignées... araignées. Hmm~ J'aime les araignées. Elles naissent avec le pouvoir de marcher, et leurs capacités de reproduction et de survie sont véritablement enviables..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Agrippa\""
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Tous les êtres ayant le sang de l'arbre en mouvement sont mes enfants. Cela inclut vous, qui avez avalé les graines de l'arbre, n'est-ce pas ?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos de la Descendance"
  },
  Voice_50909_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 7 de l' \"Opération d'Investigation\""
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "Mes marchandises ? On pourrait dire que j'ai tout pour satisfaire tous vos désirs... pour un prix."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5090_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Oh chérie, je dois admettre que j'ai perdu contre elle cette fois... Mais heureusement, puisque elle t'a choisi, tu boiras la sève de l'arbre et porteras mon sang et mes graines vers un nouveau monde, n'est-ce pas ?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Tawil"
  },
  Voice_50910_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Ramona\""
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "En tant que l'une des trois grandes essences, ce type est un monstre insondable. Ne te laisse pas facilement séduire par ses mots doux, sinon je serai le cœur brisé..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Chit-chat · À propos de N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Tant qu'il y a de la conscience, il y a du désir. Même les êtres mécaniques ne font pas exception, n'est-ce pas ?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos d'Erica"
  },
  Voice_50912_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Erica »"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Payer le prix de votre trahison !"
  },
  Voice_5091_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5092_AwakerVoiceContent = {
    Text = "Bienvenue dans ce royaume incroyable !"
  },
  Voice_5092_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5093_AwakerVoiceContent = {
    Text = "(Nombre bas)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Je connais bien la douleur de la sculpture et la brûlure de la transformation. Pourtant, tout cela s'efface dans l'insignifiance par rapport à la beauté éternelle."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5094_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "Les mots non prononcés te seront transmis à travers mon travail."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5096_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "Le souverain endormi murmure à mon oreille, les ruines des profondeurs marines se reconstruisent constamment devant mes yeux... Les scènes de rêve innombrables se sont-elles enfin réalisées ?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5098_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Merci d'avoir préparé le studio pour moi. Tout ici est baigné de soleil. Il semble que chaque œuvre, chaque couteau de sculpture, brille d'une lumière dorée. Oh, le printemps est doré."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5099_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Bien que nos tempéraments diffèrent, j'admire vraiment cet enfant. Elle possède un courage qui transcende toutes les épreuves et limitations. Si j'avais été aussi brave et résilient qu'elle, peut-être je n'aurais pas choisi de mettre fin à ma vie dans la mer..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Murphy"
  },
  Voice_5100_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "La Dame Rouge est différente de tout seigneur que j'ai jamais servi... Non, ce n'est pas que je ne l'aime pas ; c'est juste... juste un peu difficile à gérer..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de Sorel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Débloqué après avoir obtenu Éveillé«Sorel»"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Embrasser la folie !"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "À peine accroché."
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "Exterminez!"
  },
  Voice_5104_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5105_AwakerVoiceContent = {
    Text = "Vous n'avez pas à..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "Le cœur est un abîme sans fond, jamais rempli."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Pas de douleur, pas de démangeaison, mais... toujours extrêmement reconnaissant."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... Vous vous adressez à moi ? Désolé, je me rappelais juste de la vue depuis le mât. Pourriez-vous répéter votre question ?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos du Passé"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "À la fois un maître et une mère."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Une ouverture !"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Une ouverture !"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5112_AwakerVoiceContent = {Text = "Prêt—"},
  Voice_5112_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5113_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "Pousse un peu plus fort ~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "Amour brûlant !"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "D-phénomène... Je ne peux pas en révéler beaucoup. Cependant, son apparition est bien antérieure à ce que vous pensez."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Hmm—"},
  Voice_5118_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5119_AwakerVoiceContent = {Text = "Bien."},
  Voice_5119_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5120_AwakerVoiceContent = {Text = "Partons."},
  Voice_5120_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "Heh, notre princesse marionnette pleure encore. Le biberon ne passe pas, ou la berceuse est désaccordée ?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Murphy"
  },
  Voice_5121_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Bouhou... Je ne veux pas faire face à ces choses..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Maintenant, c'est à mon tour de te rembourser."
  },
  Voice_5123_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5124_AwakerVoiceContent = {
    Text = "Le flux de pouvoir ressemble à des flammes brûlantes pénétrant dans les os."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... Désolé, ne bougez pas, s'il vous plaît !"
  },
  Voice_5125_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5126_AwakerVoiceContent = {
    Text = "La chaleur à portée de main..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Les roses dans la cour sont en pleine floraison."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Bon travail ! As-tu encore l'énergie de continuer à avancer ?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "Le chevalier est une entité intangible, façonnée par la loyauté, le courage et la vertu. Mon arme est la même, donnée forme par la volonté de protéger : une lance et un bouclier."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Chit-Chat : À propos des chevaliers"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mike, Tyug, Marron... Wow ! Désolé, je parlais juste à moi-même ! Tu te demandes pourquoi je récite ces noms ? Parce qu'Aigis ne veut pas oublier tout le monde..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos des Amis"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "Ne t'approche pas de moi !"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "Je ne peux plus le supporter !"
  },
  Voice_5132_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5133_AwakerVoiceContent = {Text = "Ah~ Hé !"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5134_AwakerVoiceContent = {Text = "Ah~ Hé !"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Merci pour votre appel. S'il y a une occasion où ma voix est nécessaire, veuillez me le faire savoir à l'avance."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5137_AwakerVoiceContent = {
    Text = "Ça... c'est le liquide noir visqueux qui surgit à travers les veines, le pouvoir ultime qui fait taire tous les gémissements ! \"Je\" suis né de cela, né pour détruire ! Hahaha !"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "Vous m'appelez, vous voulez parier ? ...Quoi, une enquête ? Pas question, c'est une perte de chance..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5139_AwakerVoiceContent = {
    Text = "Le cours de théorie est plutôt ennuyeux. Je lis en cachette des dossiers d'enquête au fond de la salle de classe. Juste pour te le dire, ne laisse pas la Poupée le savoir."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Goûtez aux conséquences amères !"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Goûtez aux conséquences amères !"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Je n'ai jamais blâmé Juliette ; elle n'était qu'une victime de la souffrance noire. Mais... elle ne semble pas vouloir entendre cela de ma part. Pourrais-tu lui transmettre, Messager ?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Potins · À propos de Juliette"
  },
  Voice_5142_UnlockDesc = {
    Text = "Voix pas encore implémentée"
  },
  Voice_5143_AwakerVoiceContent = {Text = "Ralentis."},
  Voice_5143_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Bien."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "Hé ! Arrête de toucher aux choses, tu mets du désordre ! ...Oh bien, je vais laisser passer cette fois-ci puisque je suis généreux."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "Pas besoin !"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5147_AwakerVoiceContent = {Text = "Tsk !"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "Depuis le jour où tu m'as éveillé des ténèbres, j'ai été certain que tu peux sauver tous de ce désespoir connu sous le nom de Dissolution et le guider vers les terres Pures. J'attends ce jour."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Conversation Inactive · À propos du Gardien · I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Je sens... l'odeur du sang."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Où est la cible ? En tant que marque de gratitude pour m'avoir éveillé, je m'en occuperai pour vous."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5151_AwakerVoiceContent = {
    Text = "Mon chapeau ne peut plus attendre !"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Cette coquille ne devrait pas s'agiter pour quelqu'un d'autre que Lui... Pourtant, votre chaleur..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Que dirais-je d'un combat ?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5154_AwakerVoiceContent = {Text = "Profane..."},
  Voice_5154_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Impardonnable."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica fonctionne normalement et est bien connectée à l'équipement électrique de l'Université de Mythag. Avez-vous besoin que je allume les lumières du dortoir ?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos d'Erica"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Ensuite, il est temps de manger, hehe..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Ne laissez pas la femme au chapeau violet à large bord près de la scène ! Pas de questions à poser—gardez-la juste éloignée si vous ne voulez pas que de la matière grise visqueuse déborde de son chapeau !"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos des Jonquilles"
  },
  Voice_5159_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jonquille\""
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Es-tu toujours comme ça ? Faire confiance à tout le monde et leur tourner le dos ? Trop naïf."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "La haine peut être atténuée, mais elle ne peut jamais être effacée."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Éveilleur ? Hmm... Oui, 7 heures du matin est le meilleur moment pour se réveiller ! Ramassons des coquillages sur la plage demain matin à 7 heures !"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Bavarder·À propos d'Éveillé"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Accorde-toi la vie éternelle !"
  },
  Voice_5163_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5164_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Désolé, si Aigis te cause des ennuis, je partirai immédiatement !"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5166_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Tu m'as fourni un endroit où rester, et je t'en suis reconnaissant. Mais pardonne-moi, je ne mérite plus de me tenir sur la scène à nouveau."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Merci de m'avoir permis de rester ici. S'il y a un moyen de vous rendre la pareille, veuillez le faire savoir à Aigis. Voulez-vous du thé ?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5168_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "Il fait si chaud que je ne veux pas partir. Quand je suis seul, c'est vraiment sombre, froid et effrayant..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5169_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... Puis-je vraiment retourner dans la foule ? Je ne suis pas encore prête, mais tu m'as déjà acceptée... Dans ce cas, s'il te plaît, continue de veiller sur moi... Gardien."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5170_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Je me souviens, je me souviens...! Le sang sale des humains m'a piégé... Je ne pouvais pas me transformer ! Comment, comment... où sont mes branchies ? Pourquoi ne bougent-elles pas ?! Pourquoi !"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5172_AwakerVoiceContent = {
    Text = "J'adore le poulpe grillé, le poulpe bouilli, le poulpe frit... Certains disent que je commets un sacrilège. Désolé, mais le poulpe est juste si délicieux, ha ha ha !"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Vers. Étoiles. Je suis... Uvhash ! Tuez... laissez-moi tuer !"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5173_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Corps cramoisi, tentacules pulsants, parties buccales qui s'ouvrent et se ferment constamment... Très bien, très bien ! J'ai hâte de déchirer la gorge de quelqu'un !"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5174_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahaha, c'est ça le sentiment ! Donne-moi plus... le double, non, dix fois la dose !"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5175_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Je vais le supporter."
  },
  Voice_5176_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5177_AwakerVoiceContent = {
    Text = "Ce sentiment étrange... pas mal. Mieux que la belladone du sorcier levantin."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5177_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Compagnons ? Hmph... Je n'en ai pas besoin. Je ne porterai pas le même fardeau deux fois."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5178_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Je coopérerai avec vous uniquement parce que vous avez démontré une force suffisamment comparable à la mienne. N'oubliez pas, ce contrat prendra fin lorsque votre pouvoir faiblira, et je n'hésiterai pas à trancher votre tête."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5179_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "Dans vos yeux... Je vois une lueur, le feu ardent de l'ambition et du désir. Mortel, connais-toi toi-même ! Nous sommes des âmes sœurs !"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5180_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Connaissez–vous l'albatros ? Ils affrontent bravement les tempêtes, mais une fois bannis au sol, entourés de moqueries, ces ailes géantes et tombantes deviennent ironiquement un obstacle pathétique. Enfin, cette histoire ne veut rien dire... Elle m'est venue à l'esprit car je me sens très détendu en votre compagnie — juste un bavardage."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5181_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Peut-être que les temps ont vraiment changé. Maintenant, même les fragiles peuvent surmonter les récifs, commander les vagues et devenir le Roi des Cieux.\nMortel, j'attends le jour où tu réécriras l'histoire. Ce sera un honneur pour moi de devenir la puissante lame dans ta main !"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5182_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "Le taux de conversion est trop bas. Faites rapport à mon bureau demain pour une nouvelle formation."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "As-tu rencontré une autre Poupée ? La soi-disant \"vérité du monde\" peut transformer une Poupée si calme et rationnelle en une personne complètement différente... À la fin, toi et moi deviendrons-nous aussi comme ça ?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé@2"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Maître... J'ai besoin d'ordres. Veuillez me donner des ordres."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5186_AwakerVoiceContent = {
    Text = "Les performances du mech ont été améliorées."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "Hmm-hmm-hmm !"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "Plus d'alliés !"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "Plus d'alliés !"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Désolé, je ne peux pas quitter le berceau... Cela pourrait bloquer la vue de tout le monde, donc je resterai à l'arrière de la classe."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "Quoi ! Pas un seul tapis de Constantinople, pas de thé de Céylon, ni de churros d'Andalousie...? Ugh... cette femme obtient toujours ces choses si facilement. Je pensais qu'elles étaient courantes..."
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Je suis encore loin de ma forme originale."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5194_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Si avide, cela semble un peu grossier pour quelqu'un de ton calibre."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Peu importe combien cela s'améliore, l'apparence de cette bête ne changera pas. Après tout, ce n'est qu'une manifestation de mon pouvoir."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5196_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "On dirait qu'on est de retour dans l'océan chaotique, pas mal"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5197_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "À la lumière de tes efforts énormes, je vais à contrecœur t'accepter comme compagnon."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5198_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Casser les barrières du Pouvoir, tout comme briser les murs d'un Labyrinthe."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5199_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Vous ne pouvez pas déchirer la nourriture ou écraser les bancs de la cafétéria... D'accord, Lily ne le fera pas la prochaine fois."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5200_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Puis-je vous appeler Mère ?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5201_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "Y a-t-il un commandement, maître ? \n\"Ne les prends pas dehors, tout le monde aura peur ?\" \nLily comprend et va les cacher tout de suite."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5202_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Alors, c'est ça, devenir un Réveilleur."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5203_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Mère, puis-je dormir à côté de toi ? Quand je suis seule, j'ai des rêves sombres et effrayants. Les mains et les pieds de Lily sont tombés... Ça fait vraiment mal."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5204_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ah ! Merci pour ta gentillesse, Karen n'est qu'une humble servante..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5205_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hmph~"},
  Voice_5206_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "J'ai besoin de rassembler des matériaux de sculpture, de préférence frais."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Veuillez vous taire."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Ceux qui restent obstinés dans leur folie accomplissent des actes futiles."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5209_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "À ce stade, je peux quelque peu comprendre votre intention. Ça va, continuez."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5210_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Je vois votre détermination. Avant de sombrer à nouveau dans le sommeil, je serai votre témoin, témoignant de la défiance du destin par le fils de l'homme. Mais pour l'instant, j'ai besoin de repos."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5211_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "N'est-il pas bon de suivre la volonté du ciel ? Pourquoi résister à la volonté du destin ?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5212_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Pour exaucer ton vœu, tu es prêt à sacrifier tant de choses..."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5213_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Huh ? N'est-ce pas ennuyeux ? Arrête de me déranger avec ce type ! ...D'accord, fais ce que tu veux. C'est juste pour passer le temps de toute façon."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Dissolution... Ces liquides noirs sales envahissent souvent mes rêves, vraiment insupportable."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "La puissance est une arme à double tranchant. Comment pourrais-je ne pas comprendre ? C'est juste que je me suis rendu compte trop tard, bien trop tard. Une fois que je lâcherai prise, ils vont me déchirer... Si j'avais été aussi clairvoyant que vous dès le début, je n'aurais pas rencontré une fin aussi tragique. Eh, eh ? Vous dites qu'à l'avenir je peux organiser des salons dans le salon ?! C'est... Comment puis-je vous rendre hommage à part vous servir personnellement..."
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5216_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Tu es un invité plutôt inflexible. Que dois-je faire pour te faire renoncer au privilège entre tes mains ? Le pouvoir n'invite qu'aux problèmes—une vérité si simple, tu dois certainement la comprendre, n'est-ce pas ?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5217_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Avant que le salon ne commence, aimeriez-vous entendre une histoire ? Un conte sur comment une fille de village a revendiqué la couronne du pouvoir... Par où devrions-nous commencer ? Par ses parents l'obligeant à épouser un homme âgé, ou peut-être préféreriez-vous la partie où elle s'épanouit dans le jardin noble ?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5218_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "Dans le passé, les invités m'appelaient \"Dame Rouge\". Bien sûr, vous pouvez aussi m'appeler \"Sorel\", après tout, vous êtes mon invité le plus spécial..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5219_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "En tant qu'hôtesse du salon, il est de mon devoir de m'assurer que chaque invité est satisfait."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5220_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5221_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "Maître? Y a-t-il un problème avec ma posture ?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Oups !"},
  Voice_5223_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5224_AwakerVoiceContent = {
    Text = "Mauvaise chance~"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5225_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Je me souviens de ce sentiment... Le moment glorieux approche."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5226_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Bien que les marques branchiales ne soient pas encore apparues, je ne me sens plus anxieux à ce sujet. Cette aile membraneuse se transformera en un bouclier pour te protéger, Gardien."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5227_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Vous... êtes en effet plus patient que les autres humains... Vous avez réellement investi tant de ressources en moi. N'avez-vous vraiment... pas de haine envers moi ?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5228_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "Huh ? Le rituel est fini, mais je n'ai toujours pas de branchies ? La transformation a encore échoué ?! Zut alors ! Zut alors ! Zut alors !"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5229_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Cette voix m'appelle à nouveau... le son éthéré venant des profondeurs de l'Aequor !"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5230_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Devine—faux—encore—"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Sanga, la sculptrice de la Cité, t'offre son ciseau. Tu peux être imparfait, mais tu vaux toujours la peine d'être sculpté."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5238_AwakerVoiceContent = {
    Text = "Les enfants qui n'écoutent pas, rassemblez-vous~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "Le véritable art n'a pas besoin d'explication."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "Le véritable art n'a pas besoin d'explication."
  },
  Voice_5240_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5241_AwakerVoiceContent = {
    Text = "Aurita, peux-tu aider ?"
  },
  Voice_5241_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5242_AwakerVoiceContent = {
    Text = "Sonne la corne !"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "À tout prix!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "La sensation d'être baigné de lumière du soleil... si douce, elle vous fait pleurer."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5244_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Pour exprimer ma gratitude... je construirai un autel caché pour vous dans les profondeurs de ma souffrance."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5245_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "Le Caro de mon frère et mon Corps fusionnent de manière plus parfaite et plus serrée..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5246_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Je suis plus résilient que tu ne le penses. Donc, en m'utilisant, tu peux appliquer plus de force. Ne te retiens pas."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5247_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "Est-ce juste mon imagination ? L'envie de sang semble avoir diminué quelque peu."
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5248_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Même avant que nous ne commencions officiellement, j'attendais déjà votre arrivée. Il semble que nous travaillions plutôt bien ensemble, hein ? Partenaire."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "C'est honteux."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5251_AwakerVoiceContent = {Text = "Aah !"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5252_AwakerVoiceContent = {Text = "Hahaha !"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Frappez·Manie"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Frappez·Dépression"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Frappe-moi autant que tu veux !"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Aigis a vraiment peur. Non, pas de vous tous, mais d'elle-même apportant à nouveau peur et chagrin."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "Les livres de contes de cette époque sont beaucoup plus intéressants que ceux que je lisais à l'époque ! Ah, ah ! Mon seigneur, ne vous méprenez pas ! Je suis au-delà de l'âge des histoires du soir !"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Frappe-moi autant que tu veux !"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Ouf... Aigis a-t-elle causé des problèmes à tout le monde ?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Vous vous êtes toujours accroché à cette confiance amusante et êtes resté à mes côtés... Très bien, peut-être que vous mettre à contribution n'est pas une mauvaise idée. Mais souvenez-vous de ceci : je ne peux tolérer aucune trahison, surtout de votre part."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5259_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Je ne fais que regretter de ne pas avoir empalé leurs cadavres sur des piquets et de les avoir accrochés aux murs ! Je n'épargnerai aucun traître, piétineur ou insulteur !"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5260_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Oui, j'ai bien rampé devant ces gens ; il n'y a rien à y redire. Ils ont profité de mon ignorance, et je leur ai fait payer."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5261_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Penses-tu que quelques mots doux et quelques jours de fausse gentillesse me feront les chaînes à nouveau et devenir ton jouet ?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5262_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Tous ceux qui ont essayé de me contrôler ou de m'utiliser ont fini dans l'au-delà par mes propres mains—je ne me dérange pas de vous y envoyer aussi."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5263_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... Désolé, ne bougez pas, s'il vous plaît !"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "Ne me touche pas !"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "Manque de respect !"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Rends-toi... Bienvenue dans le royaume du plaisir et des rêves."
  },
  Voice_5267_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5268_AwakerVoiceContent = {
    Text = "Ceci est la ville où d'innombrables âmes perdues errent, incapables de trouver leur chemin vers chez elles."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "Aigis fera de son mieux !"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Euh... Je ne peux pas contrôler ma capacité à absorber la force vitale, donc s'il te plaît, ne mets pas ta main dans le berceau, sinon tu vas tomber malade."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "J'espère qu'elle ne fera pas de dysfonctionnement pendant notre conversation. Mon adorable mais exaspérante assistante, il n'y a plus de laboratoires de secours pour qu'elle fasse exploser."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos d'Erica"
  },
  Voice_5271_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Erica »"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Bras, ces bras ennuyeux ! Ils s'accrochent toujours à mes cheveux. Je ne peux même pas contrôler mes propres mains—quel gars inutile je suis... Peut-être que je devrais..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Chitchat · À propos de moi"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Merci pour vos conseils. Je comprends enfin le choix de Faint. J'ai tout pris pour acquis, ne réalisant pas le fardeau mental que cela lui imposait. Désormais, j'essaierai de vivre pour moi-même..."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5274_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "À travers les longs et infinis temps, Faint et moi n'avions que l'un l'autre... Mais maintenant, j'ai de nouvelles personnes importantes... Gardien, veuillez me permettre de retirer mes paroles précédentes. Vous êtes différent. Vous ne vous souciez pas seulement de ma voix chantante ou de ma robe de cérémonie ; vous me voyez vraiment. Par conséquent, je veillerai également sur vous."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5275_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Les étoiles dans le rêve, se dirigeant vers leur destination, pointent vers le royaume de Dieu !"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "Pourquoi suis-je toujours habillé de cette robe ? Pour que je puisse chanter pour vous à tout moment."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5277_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "Que veux-je faire ? ......Désolé, je ne comprends pas ce que vous voulez dire......En réalité, Évanouissement m'a posé cette question plusieurs fois, mais tout ce que je souhaite, c'est qu'elle se rétablisse bientôt......"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5278_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Pendant notre séjour sur la planète désolée, la compassion de ces figures influentes a fourni à ma sœur et à moi les ressources pour survivre. À la fin, ils m'ont aussi donné la chance d'échapper à la planète, bien que cela ait été limité à une personne. Ils sont tous mes bienfaiteurs, tout comme toi, Gardien, qui m'as offert un endroit où rester."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5279_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Tu es la personne bienveillante qui me fournit un endroit où séjourner. Aigis t'écoutera. Si seulement Aigis pouvait être un peu plus utile..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "N'oublie pas de préparer le lieu. Celui que tu as réservé n'est pas plus petit que celui d'Elworth, n'est-ce pas ?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5281_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Bien, Karen est maintenant plus motivée et peut nettoyer vingt chambres par jour !"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5282_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "C'est la musique aussi ancienne que l'eau du lac, appartenant à \"nous\". Maître, dansons ensemble ! Avant que la voix de Karen ne soit prise par \"Lui\"..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5283_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Maître ! La voix de Karen... s'estompe... Aidez..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5284_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "La vue de Karen s'est améliorée... Maître, avez-vous encore oublié de vous peigner les cheveux!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5285_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Même si elle devient plus forte, Karen ne veut pas de revanche. Karen veut juste chanter ! Danser ! Faire la fête !"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5286_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Pour survivre après la destruction totale, j'ai partagé mon esprit et mon sang avec trop de personnes. Mon pouvoir actuel est bien loin de ce qu'il était lorsque j'ai d'abord accepté cette volonté."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos du Passé"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Ne t'attends pas à me trouver dans le bâtiment des cours. Il est rempli de l'odeur de vieux érudits moisis ; je ne peux pas supporter d'y être même une journée."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "Ne courez pas."
  },
  Voice_5289_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5290_AwakerVoiceContent = {
    Text = "Ma patrie vénère les \"Dieux\", et par conséquent, le roi que je suis est naturellement un \"communicateur divin\"."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos du Royaume Éternel"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Vous avez tout un rassemblement de talents ici, digne d'un grand salon... Rassurez-vous, l'invitation vous sera délivrée par mon serviteur."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5292_AwakerVoiceContent = {Text = "Allez !"},
  Voice_5292_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "Si seulement nous avions plus de compagnons..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Je ne suis pas comme elle. Elle offre seulement des frissons hostiles et de la peur, tandis que je te donne de la douleur et de l'amour intimes, doux et brûlants."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de Wanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Wanda\""
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Ne pense pas que c'est fini ! Je te ferai payer chaque once de cette humiliation !"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Vos mains, comme votre âme, sont chaudes. Le feu pâle... J'apprécie votre touche."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Qu'est-ce qui ne va pas à jouer au bridge en classe ? Il y a une table, des gens, et j'ai apporté les cartes. Cela signifie \"Jeu en cours\" !"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5299_AwakerVoiceContent = {
    Text = "Ne le faites pas..."
  },
  Voice_5299_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "Regarde dans l'Abysse !"
  },
  Voice_5300_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5301_AwakerVoiceContent = {
    Text = "Regarde dans l'Abysse !"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5302_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5302_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5303_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5304_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5304_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5305_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "Baignez-vous dans la lumière divine !"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5307_AwakerVoiceContent = {Text = "Hé !"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "Les âmes faibles se rassemblent, mais quel bien cela fait-il leur bruit ? Soupir..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "La guerre apporte toujours de la douleur, et endurer la souffrance est le devoir d'un guerrier. Même si je perds mes mains, mes pieds, et tout le reste, je me battrai toujours pour vous et pour la justice du monde."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "Est-ce l'hommage que vous lui offrez ?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Penses-tu que cela peut changer l'avenir ?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Sa gestation... dans mon ventre..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Heh, tu es plus intelligent que je ne le pensais."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Rendre hommage au maître est tout à fait naturel."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Vous avez l'air plutôt mignon quand vous essayez de me plaire."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownie, pudding au caramel, Sachertorte, mousse au chocolat, biscuits... Chaque table doit les avoir !"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5318_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Vérifie ma jupe pour moi, veux-tu ? Pas de plis, pas de lâche... Qu'est-ce qui ne va pas ? Es-tu insatisfait ?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5319_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Bienvenue à ma dernière cérémonie d'Illumination ! Tout cela a été soigneusement conçu par moi. Bien sûr, le Gardien a contribué juste un peu..."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5320_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "Les tables et les chaises devraient être ornées de dentelle correspondant à ma tempérament, et les plantes en pot doivent présenter des plantes araignées rouges... Dépêchez-vous et préparez-vous !"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5321_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Va faire la réservation pour l'invité ! Comment peux-tu rater une tâche si simple ?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5322_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Aucune échappatoire !"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "Aucune échappatoire !"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Je ferai de mon mieux ! Pour vivre à la hauteur des attentes de mon seigneur."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5325_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "J'aime beaucoup cette femme. Nous avons... qu'est-ce que je dis déjà ? Une langue commune !"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de Wanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Wanda\""
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "Espèce de fou insolent !"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "Espèce de fou insolent !"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Devenu des débris."
  },
  Voice_5329_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5330_AwakerVoiceContent = {Text = "Briser."},
  Voice_5330_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "Casser les barrières de la réalité !"
  },
  Voice_5331_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5332_AwakerVoiceContent = {
    Text = "Prévois-tu de partir en mer bientôt ? Pourrais-tu exaucer ma humble demande et me laisser t'accompagner ? Laisse-moi juste atteindre la mer..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5332_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Si vous avez encore confiance en moi, permettez-moi d'être la lumière guida dans ce voyage. Cependant, même dans une tâche si simple, j'ai échoué auparavant..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5333_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Tu n'as pas envie de partir en mer ? Laisse-moi vérifier la carte actuelle... 47°9' S, 126°43' W, juste ici."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5334_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "J'ai causé de nombreux désastres dans le passé, faillit même apporter la destruction à certaines civilisations... Si je dis que ce n'était pas intentionnel, est-il déjà trop tard ?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5335_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Je suis le gardien de l'entrée du Royaume Éternel, guidant ceux qui rentrent chez eux. Comme il est ironique que quelqu'un avec un tel devoir ait oublié le chemin de la maison...\nVeux-tu... être mon phare ?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5336_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Amas d'étoiles."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5338_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "Brouillard dense."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5340_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5341_AwakerVoiceContent = {
    Text = "Pour la plupart des gens, être une escorte gardienne ne fait aucune différence, mais cette femme est une exception. Si possible, merci d'arranger un autre itinéraire pour moi."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Chat·À propos de Miryam"
  },
  Voice_5341_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Miryam »"
  },
  Voice_5342_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "Il n'importe pas."
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Laissez vos mains tranquilles."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Avant de retourner au Palais d'Aequor, je te prêterai, à toi, un simple humain, un peu du pouvoir d'Aequor, mais seulement cette fois-ci."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5346_AwakerVoiceContent = {Text = "Allez !"},
  Voice_5346_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5347_AwakerVoiceContent = {
    Text = "Comme ça ? J'aime la douleur—la sensation de la peau enflée et brûlante, les gémissements mêlant plaisir et souffrance. La douleur est le désir le plus primal et authentique, n'est-ce pas ?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Rejoins Aurita !"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Rejoins Aurita !"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Cette grande sœur me lance toujours des regards féroces. Mais pour une raison quelconque, je ressens un sentiment de familiarité. Est-ce parce qu'elle me rappelle ma mère ?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Bavardage Inactif · À Propos de Hilote"
  },
  Voice_5350_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Hilote »"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Mon esprit semble plus aiguisé, pas mal."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5351_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Je préfère le travail en laboratoire à l'obligation de terrain—pensais-tu que ces outils d'assistance avaient été pêchés dans la mer ?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5352_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Que ce soit des vis ou des clous, plus il y en a, mieux c'est !"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "Le corps peut à peine supporter ce Pouvoir, mais ce n'est pas le moment de changer de marionnettes. Pourquoi restes-tu là ? Aide-moi à maintenir cette jambe ; j'ai besoin de faire quelques ajustements."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5354_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "Le fardeau de la lumière guidante peut submerger même les saints les plus purs. Si vous vous sentez fatigué, ma flamme pâle, veuillez vous confier à moi. Je ferai tout mon pouvoir pour alléger votre fardeau et partager le poids de ces innombrables bénédictions."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Conversation Inactive · Sur la Fatigue"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Votre approbation est la raison de mon existence en tant que chevalier."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5356_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Baigné dans la lueur des dieux, est-ce le pouvoir divin de mon Seigneur ? Si vaste, si sacré"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5357_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "La porte du divin est à portée de main."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5358_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Plus brillant et plus clair..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5359_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Pour retrouver ma forme humaine complète en tant que Réveilleur... J'ai déjà entendu la mélodie sacrée jouée pour moi par le Royaume Divin..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5360_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Il m'accueillera dans l'Église, me donnant un repos paisible..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5361_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Ne vous inquiétez pas, nous sommes tous assez utiles. Je peux coudre et nettoyer, un autre moi excelle au combat, et les autres..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Je déteste les choses brillantes et douces. La douceur est comme un miroir, révélant toute la laideur, la cupidité et la fragilité."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Tu veux caresser Brown ? Je ne peux pas décider pour toi. Tu dois lui demander toi-même."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Tu veux me plaire ? Alors mets-toi à genoux, offre ton cou, et reste silencieux jusqu'à ce que j'aie fini de te vider."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "J'ai fait un rêve la nuit dernière ; il a marqué le début de mon voyage à travers les étoiles."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5367_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "Aigis peut-elle être d'aide ?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5368_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Je le sens~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5370_AwakerVoiceContent = {Text = "Tapez !"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Carte de compétence·Trois"
  },
  Voice_5371_AwakerVoiceContent = {
    Text = "Attention !"
  },
  Voice_5371_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5372_AwakerVoiceContent = {Text = "Recule."},
  Voice_5372_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "Personne ne sera blessé... dans ce... monde..."
  },
  Voice_5373_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5374_AwakerVoiceContent = {
    Text = "（coquettement）"
  },
  Voice_5374_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5375_AwakerVoiceContent = {
    Text = "Veuillez me permettre de dresser un autel pour mon Seigneur. C'est une statue sculptée par des fidèles et n'apportera aucune malédiction sur vous."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Juste un petit peu..."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "Ma clé à molette n'est pas encore en position !"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Chimie, physique, applications en Argent... À cette époque, n'est-il plus nécessaire d'apprendre les Sept Compétences Chevaleresques ? Je comprends. Dans ce cas, veuillez organiser les cours correspondants pour moi, mon seigneur !"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Aurita a voyagé ! Pas emportée par les vagues, mais a effectué un voyage avec une caravane !"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5379_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Méduse de phare, méduse couronne, méduse fleur de pêcher - elles se déplacent toutes en groupe. Bien sûr, Aurita aussi ! Aurita veut être avec tout le monde !"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5380_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Événements passés ? Difficile de s'en souvenir... Mais Aurita se souvient d'avoir travaillé dans un aquarium ! Le salaire quotidien était de 2 Pensh !"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5381_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Laisse-moi te dire un secret : Aurita est en fait un Aram, Trans... euh, fondamentalement, Aurita est une personne de la mer ! Si Aurita se comporte bien, mange des légumes et se fait des amis, Atlanta l'accueillera !"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5382_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "La maison d'Aurita, les amis de l'aquarium, sa méduse préférée—tout est parti... Vas-tu également disparaître ? Ne peux-tu pas rester avec Aurita pour toujours ?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5383_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Avons-nous gagné ? C'est merveilleux..."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "Pour la paix."
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Pour la justice."
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Je sais que vous êtes en moi !"
  },
  Voice_5389_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5390_AwakerVoiceContent = {
    Text = "Humains, faux dieux, Éveillés, et même Dissolution... Tous serviront de fondation à ma terre éternelle."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Réveillez, réveillez ! Je sais que tu es en moi !"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... Il me rappelle mon frère, faisant remonter des souvenirs de jours sombres, froids et sans sommeil."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Chat·À propos de Uvhash"
  },
  Voice_5392_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Uvhash »"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Notre relation est comme celle de Sherlock Holmes et du Dr Watson, n'est-ce pas ? As-tu suivi les derniers magazines populaires ?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Inclinez-vous devant la beauté."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Inclinez-vous devant la beauté."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Aversion, un verbe descriptif, signifiant développer une aversion pour quelque chose. Dégoût, un verbe, fait référence au sentiment d'aversion lorsque quelque chose est détesté et évité. Aversion, un nom, le sentiment de dégoût, <Del:Le dégoût réprimé me fait détruire me fait détruire me fait> — Désolé, mais j'ai peur de ne pas comprendre ce que signifie \"dégoût\"."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "En fin de compte..."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "Devenir encore plus distinct."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Souviens-toi de mon nom, Goliath. Ce nom est destiné à fouler l'insignifiante histoire de l'humanité."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Veuillez ne pas avoir d'inquiétudes."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "J'espère que tu ne laisseras pas tomber ton potentiel et les attentes de l'humanité, nouveau Gardien."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5402_AwakerVoiceContent = {Text = "Surcharge."},
  Voice_5402_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5403_AwakerVoiceContent = {Text = "Surcharge"},
  Voice_5403_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Hmm, la photo que tu as trouvée dans ton portefeuille ? Ah, c'est l'ancien moi. Mon apparence actuelle a été façonnée par mon ami parieur et rival."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5404_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Parfait—vous voulez parier ? Si vous gagnez, je partagerai un secret avec vous.\nMais faites attention, Alva pourrait vous attraper~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5405_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Te soucies-tu de cette fourrure ? Veux-tu la toucher ? Ne t'inquiète pas, je suis très généreux !"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5406_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Bien sûr, il y a des avantages. Ne t'ai-je pas rencontré, mon Watson ? Comparé à cela, la vie et l'apparence n'ont pas d'importance, n'est-ce pas ?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5407_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Est-ce que je le regrette ? Pas du tout. La vie serait trop ennuyeuse si tout se passait toujours bien, n'est-ce pas ?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5408_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "À mon époque, les écoles étaient des lieux pour former des guerriers. Il semble que cela soit toujours le cas maintenant."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... Non, ça va. Au moins nous pouvons être à nouveau ensemble, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Discussion inutile · À propos de \"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"24\""
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Pas mal, non ? Maintenant, la récompense. — Quoi ? Il n'y a pas de déjeuner gratuit !"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Je viens de Cité. Là-bas, tout le monde veut être acteur ; personne n'est content de simplement regarder. En réalité, nous ne sommes que de pitoyantes notes de bas de page de la ville."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos du Passé"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Avez-vous vu les anciennes sculptures sur pierre ? Fusionnées avec les montagnes, survivant au passage du temps à travers la nature, de si merveilleux reliques... mais ce n'est toujours pas suffisant..."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "Le pigeon n'est pas revenu..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5415_AwakerVoiceContent = {Text = "Reculez !"},
  Voice_5415_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5416_AwakerVoiceContent = {Text = "Hmph !"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "Exécutez la commande !"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5418_AwakerVoiceContent = {Text = "Imbécile"},
  Voice_5418_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "...Hein ? M'appelles-tu ? Je n'ai pas entendu en réparant la moto... Au fait, aimable inconnu, as-tu vu ma clé à molette ?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5419_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Ma mémoire est toujours floue, et je ne peux me concentrer que sur ce qui est juste devant moi. Cependant, je ferai de mon mieux pour graver votre nom dans mon esprit... Quel était-il déjà ?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5420_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Vous avez l'air quelque peu familier, mais je ne me souviens pas de votre nom... Êtes-vous mon assistant ? Pourriez-vous m'apporter sept boulons ?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5421_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "J'ai gravé ton nom sur le Fantasme. Lorsque nous partirons à l'aventure un jour, je n'oublierai pas comment t'appeler."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5422_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Si familier, si familier. Quelque chose a dû se passer entre nous, n'est-ce pas ? Donne-moi un moment pour me rappeler... Ah, c'est toi, le Gardien !"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5423_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Vous êtes vraiment un enfant peu sincère. Heureusement, j'ai suffisamment de temps et de patience pour vous attendre..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "\"Tout le monde est heureux,\" n'est-ce pas ?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "J'ai un bon trophée... Bien qu'il ne puisse pas se comparer à ma meilleure collection, le frisson de la chasse aux nouvelles pièces est toujours excitant. Invite-moi la prochaine fois aussi."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Une servante professionnelle défrichera tout pour son maître, y compris les vilains~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Nous sommes complices maintenant, non ? Si tu te retrouves un jour dans la rue, je ne te laisserai pas survivre avec les ordures."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Grandis et prospère, ma petite pousse."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Grandis et prospère, ma petite pousse."
  },
  Voice_5431_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5432_AwakerVoiceContent = {
    Text = "On a l'impression que ma chance aux dés s'est un peu améliorée !"
