  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Je dois vous accuser, Gardien. Votre gentillesse me rend mal à l'aise — seule la douleur physique est vraiment éternelle pour moi."
