  Voice_5440_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Ugh ! La saleté et le désordre partout... Je ne peux même pas trouver un endroit propre où poser mes pieds. Très bien, offre-moi ton dos doux, mortel."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Enfin... trouvé !"
  },
  Voice_5442_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5443_AwakerVoiceContent = {
    Text = "Même le pelage de Brown est devenu plus lisse."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5443_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5444_AwakerVoiceContent = {
