  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa ? Désolé, j'ai moi-même renvoyé trop de gens. La plupart d'entre eux n'ont pas de visage et ne valent pas la peine d'être retenus."
  },
  Voice_5448_AwakerVoiceTitle = {
