  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Membres d'équipage dangereux... Non, c'est juste d'un point de vue de sécurité de navigation..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Chat · À propos de Faros"
  },
  Voice_5449_UnlockDesc = {
