  },
  Voice_5451_AwakerVoiceContent = {
    Text = "Fais attention !"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "J'ai complété tes instructions... Ah, j'en ai fait un fiasco encore, n'est-ce pas ?"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, c'est exactement la partie dont j'avais besoin, merci ! ...Hein ? Je vous ai demandé de le trouver ? Je ne me souviens pas du tout de ça. Êtes-vous sûr de ne pas vous tromper ?"
