  Voice_5454_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5455_AwakerVoiceContent = {Text = "Bon goût."},
  Voice_5455_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5456_AwakerVoiceContent = {
