  Voice_54628_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "Toutes les coquilles sont ici !"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "Le pouvoir extraordinaire ne peut être supporté que par un Aequor. Vous devez m'envier, haha. Ce n'est pas de votre faute d'être un humain fragile ; il suffit de s'y faire."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5462_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Inclinez-vous et embrassez le bout de mes pieds !"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "Puis-je transformer ces individus vaincus en mes esclaves ?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5465_AwakerVoiceContent = {
    Text = "Tout comme prévu."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5466_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5467_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Si j'avais su plus tôt que ces personnes étaient tourmentées par cette malédiction dévorante, je... Non, il n'est pas trop tard maintenant. Je dois l'éradiquer et éliminer toute souffrance, même si cela me coûte à nouveau la vie."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Ne perds pas espoir. La mer embrasse tout le monde."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Avec un corps aussi fragile, il est trop demandé que vous deveniez mon compagnon. Allez, emmenons-vous au club de sport de l'académie pour élargir vos horizons et subir un entraînement rigoureux !"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Cette pauvre âme qui a emprunté mon pouvoir a été tourmentée par Dissolution... Quel genre de regard est-ce ? N'y pensez même pas ! Je ne vous dirai pas où elle se trouve !"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Tant que tu as la chance, tu peux devenir invincible."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Sera-t-il trop sévère ?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Oh là là, la plupart des gens ici sont encore des enfants. Cet homme a déjà les cheveux blancs, et le jeune homme au visage sévère a perdu un bras. Aucun d'eux n'est un choix idéal... C'est un vrai dilemme."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Sera-t-il trop sévère ?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Des runes minutieusement dessinées, des statues profondément sculptées, des potions tabous raffinées à maintes reprises... aucune ne peut être épargnée."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5476_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "Le trône devrait être construit avec de l'ancêtre jade de Aequor, et l'autel devrait être enduit de sang sacrificiel... Ne devrais-tu pas commencer à préparer ?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5477_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Invoquez-les tous ; ils devraient trembler et s'agenouiller en attendant Son arrivée."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5478_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Je vais me diriger vers les ruines d'Aequor, me baignant dans les eaux où Il est né..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5479_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Bienvenue à la cérémonie de Sa naissance, pour témoigner de Son arrivée... Quoi ? Tu dis que Sa demise est aussi inévitable ? ... Non, c'est impossible... J'ai déjà payé un si lourd prix..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5480_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Suivez les commandements divins."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "Ton côté sera-t-il l'endroit où Évanouissement et moi appartenons ?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5482_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Hmm, à ce moment-là, j'ai perdu ma voix. Ta grâce l'a ramenée."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5483_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "Suivez les commandements divins."
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "Le vaste cosmos, l'immensité de l'espace profond, et le voyage sans fin m'ont jadis laissé un sentiment de perte..."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5485_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Les méthodes rapides peuvent vous donner un coup de pouce, mais ne négligez pas l'entraînement de vos compétences."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "Alors cette méthode s'applique aussi à moi..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Une sensation merveilleuse."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "L'arrivée de lui ne mettrait-elle pas fin à la souffrance causée par cette peste noire ?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Bonjour, mon seigneur. Si vous sortez pour mener une investigation, permettez-moi de vous accompagner en tant que gardien."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5493_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "Que faire ? Si tu t'ennuies, va juste écrire ce rapport de mission."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Est-ce que ça commence enfin ? Mes petits animaux de compagnie ont eu si faim depuis si, si longtemps..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "Le pouvoir de la lignée est en pleine montée."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...Attendez une minute, j'ai déjà vu ça avant. Ils m'ont donné de l'eau avec cette goo noire dedans. Cela pourrait-il être lié à l'acquisition du pouvoir de la Flamme Verte ? Je suppose que c'est une bénédiction déguisée."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, appelle-moi juste Ramona. J'ai hâte de travailler avec vous, Gardien."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5499_AwakerVoiceContent = {Text = "Oui."},
  Voice_5499_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5500_AwakerVoiceContent = {
    Text = "Commande reçue."
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "Hmph, irrespectueux, laissez-moi m'amuser un peu avec vous."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Aime les choses ? Une canalisation qui se vide juste à temps, un train manqué, de la pluie en portant des nouvelles chaussures. Fondamentalement, toute la malchance est ennuyeuse."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Clé, clé réglable, clé à œillet, tournevis à tête plate, tournevis cruciforme, vis fraisée, vis à tête bombée... Si ça peut réparer des choses cassées, je l'aime."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Oh non~ Tu m'as attrapée~\nC'est bien, les Réveilleurs ont une telle puissance spirituelle abondante. Je dois voler au moins 365 fois avant qu'ils ne deviennent des marionnettes sans esprit~ Tu ne peux pas le faire ? D'accord, je ferai plus attention la prochaine fois ! Juste un petit peu de \"peur\" pendant le sciage, d'accord ?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5504_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Hey, tu connais déjà les secrets de la magie de Casiah, n'est-ce pas ? Hmm, pour s'assurer que tu ne dévoiles pas les choses, tu devras me suivre partout où je vais en tournée~ Haha, tu penses que je collecte tes émotions ? En effet, rien ne t'échappe !"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5505_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "Vous, soyez l'assistant magique de Casiah ! N'ayez pas peur ~ Grimpez juste dans ma boîte magique pendant un moment.\n\nVous cachez-vous bien ? Je suis sur le point d'insérer l'épée ~ Oh, il n'y a pas de pièges à l'intérieur ~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5506_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Ici, mets ce haut-de-forme ! Ensuite, dis-moi le cadeau que tu désires le plus. Compris, je vois ! Maintenant, plonge la main dans le chapeau —"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5507_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Un peu troublant. Ces enfants viennent à chaque représentation, et mon stock s'épuisent... Hmm, un magicien ne peut pas exécuter les mêmes tours pour le même public. Créer de la nouvelle magie ? Désolé, je n'ai pas ce talent ; je ne suis bon qu'en imitations."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5508_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Cette académie est dans un état de délabrement ; seul le salon du principal est quelque peu présentable. Que penses-tu ?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5509_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Ces arrogants et méprisables imbéciles deviendront tous des esprits vengeurs sous mon commandement."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "La lame de la vengeance devient de plus en plus tranchante."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Mon salon n'est pas aussi innocent qu'un bal. Es-tu prêt ?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5512_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Mon salon est le sol, le jardin, où la beauté et la puissance enivrantes fleuriront..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5513_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Coussins en soie, thé noir, macarons... J'ai aussi besoin de roses fraîches avec la rosée du matin pour orner mon salon."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5514_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Ne pouvons-nous pas faire une exception et permettre aux invités à l'extérieur d'entrer dans l'académie ?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5515_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Erreur d'exécution, erreur, erreur, erreur..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ah ! Quelle heure est-il ?! Désolé, Maître... Karen ne devrait pas paresser ! Mais je suis tellement épuisée..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "Est-ce que ma seule option est d'attendre la mort ? Quelqu'un peut-il m'aider ? Puis-je résister à leur contrôle ? Je me posais ces questions tous les jours, mais la réponse était toujours dans mon esprit — je n'osais tout simplement pas y faire face... Si vous n'étiez pas apparu, je ne sais pas si j'aurais eu le courage de riposter.\nE-Eh, merci — ne vous méprenez pas, ce n'est pas une confession ou quoi que ce soit !"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5518_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Je vis dans leurs faux rêves, dépouillé de mon droit d'être une personne ordinaire par une prophétie ridicule, sans même la liberté de choisir... Je ferai tout pour échapper à cette vie."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5519_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = ":\"Des nénuphars suspendus soupirent tout autour,\nElle remue parfois parmi les aulnes endormis ;\nUn oiseau bruisse, tremblant dans son nid,\nUne chanson mystérieuse descend des étoiles dorées.\n\"Ah, as-tu entendu ça ? Désolé, c'est un de mes favoris... Veux-tu le lire avec moi ?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Conversation Inactive : Sur la Lecture"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Ne pénètre pas dans la chambre d'une dame à ta guise, ni ne fais de commentaires sur son comportement. Pars maintenant, j'ai besoin de repos."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5521_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Tu ferais mieux de ne pas te donner des airs avec moi. Connaîs ta place et ouvre les yeux pour voir qui est le véritable maître."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5522_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Oh, avez-vous besoin d'afficher les articles ?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Bien joué. Il est temps de célébrer la victoire avec un fût de rhum !"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "Disparaître."
  },
  Voice_5525_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5526_AwakerVoiceContent = {
    Text = "Laisse-le à moi !"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "La sensation d'être écrasé sous mes pieds doit être absolument merveilleuse~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "Tiens bon !"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "Vous vous demandez ce qu'il y a sous le cache-œil ? Je vous le montrerai dans un cadre plus approprié, alors ne soyez pas trop impatient."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Est-ce déjà fini ? ... Mon excitation ne faisait que commencer à monter."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Hey, arrête de te moquer de moi. Les véritables guerriers ne se reposent jamais sur des aides extérieures."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5531_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Aigis est devenue plus forte... Je vais utiliser ces yeux pour paralyser l'ennemi !"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "Mythag University n'est pas différente de l'armée. Chacun de nous se tient en première ligne, polissant nos armes et se préparant à la bataille."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5534_AwakerVoiceContent = {Text = "Parfait !"},
  Voice_5534_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5535_AwakerVoiceContent = {Text = "Parfait !"},
  Voice_5535_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Je peux être enchaîné, traîné par les cheveux pour m'agenouiller devant toi, être ton esclave. Tout cela ne pose aucun problème—tant que tu me laisses tuer, sculpteur, porteur de lanterne, vieille dame asthmatique de passage... n'importe qui, je te promets de leur déchirer la gorge et de boire leur sang"
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5536_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Des blessures de Dissolution s'écoulent non seulement de la boue noire, mais aussi une inspiration infinie. Honnêtement, cela ne me dérangerait pas d'en avoir un peu plus"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Effrayé ? Hahaha, c'est vrai ! Au diable tout ça. Je veux juste savourer ta peur."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5538_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Intéressant, ton sang a un goût... sucré, comme de l'hydromel."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5539_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "À l'époque, des dizaines de milliers acclamaient mon nom. La mer appelée \"Uvhash\" a noyé tout, célébrant ma rupture du cou d'un faible chauve. C'était incroyable. En tant que mon camarade, tu dois comprendre."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5540_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "Attendez, attendez !"
  },
  Voice_5541_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5542_AwakerVoiceContent = {Text = "Non !"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5543_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5544_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Recherche \"Dissolution\" dans les vastes Archives... Pas nécessaire ? Vous souhaitez connaître ma position sur la Dissolution ? Compris. Recherche d' \"armes de Dissolution\" dans le domaine privé de l'Éveilleur... Résultat : \"0\"."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Des objets faux, fragiles comme de la poussière, peuvent être emportés par une simple brise..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Murphy"
  },
  Voice_5546_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Un peu bruyants, sont-ils des étudiants ?\nIls me rappellent des albatros. Connaissez-vous ces oiseaux ? Énergie sans fin, voyages qui semblent sans fin..."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ha"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Hmph"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "Ramona est la seule intéressante ici, talentueuse en escrime. Les autres sont tous rigides... Êtes-vous l'un d'eux ? Trouvez-vous vraiment amusant d'écrire des rapports de mission ?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Pas la peine d'en parler."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "Les mères ne sont pas toutes les mêmes. Certaines sont bonnes, et certaines sont mauvaises.\nLe Maître est une bonne mère."
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5552_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Je suis désolé de ne pas avoir réussi à te protéger..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Avez-vous réservé le lieu ? Il doit s'agir d'un jardin de plus de 150 mètres carrés !"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5554_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "Le sang des mourants est un liquide glissant. Avec juste une légère coupure au cou, le sang s'écoule entre les dents, se transformant en ruisseaux chauds qui remplissent lentement mon ventre... Heh, délicieux."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur le Sang"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Ah"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Hé !"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Eh"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Merci pour votre gentillesse en me fournissant un abri. J'espère que je ne vous causerai pas de destin tragique..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Je viens d'une planète extraterrestre lointaine, un endroit de tempêtes de neige incessantes et de froid extrême. Mais ça va ; dans mon manoir, plus de mille serviteurs offrent une chaleur réconfortante par leur proximité."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos du Passé"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "Je ne peux pas tomber ici avant ton retour."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "Je ne peux pas tomber ici avant ton retour."
  },
  Voice_5562_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5563_AwakerVoiceContent = {
    Text = "Oh, comment peut-il y avoir un invité si arrogant dans le monde, voulant \"l'arme la plus puissante du monde\" ? Je lui ai dit qu'il faudrait une tête trempée dans la haine pour l'échanger, et il est parti en maugréant..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Chat · À propos de Goliath"
  },
  Voice_5563_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Goliath\""
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Votre regard sûr de vous, comme si vous étiez toujours prêt à \"sauver le monde\", me donne des démangeaisons aux articulations rien qu'en le regardant."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5564_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Juste avant que l'interdiction de recherche ne soit imposée, j'étais sur le point de laisser l'annihilation engloutir ce qu'on appelle le sanctuaire Dissolution... Quel dommage."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5565_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Oui, j'ai d'innombrables corps et évasions de dissolution. Mais j'ai poursuivi la vérité, et je ne le regrette pas"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5566_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "La vérité du monde, son début et sa fin—tout cela est insignifiant. Si vous souhaitez emprunter le chemin de la vérité, je ne me dérangerai pas d'être votre guide... comme avant."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5567_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Vous pouvez peut-être m'arrêter, mais la fin est inévitable... Je sauverai cette école — et vous — en dernier. Ensemble, nous baignerons dans le crépuscule du temps au sommet de la tour, témoignant de la chute de la civilisation... Qu'en pensez-vous ? De cette façon, notre lien n'aura pas été vain, n'est-ce pas ?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5568_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5569_AwakerVoiceContent = {Text = "D'accord."},
  Voice_5569_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "Disparaître."
  },
  Voice_5570_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5571_AwakerVoiceContent = {
    Text = "Que mes prières soient la cloche du matin qui réveille la patrie..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Je n'ai jamais pensé que quelqu'un d'autre que Tinct m'accepterait. Je suis heureux de t'avoir rencontré, Gardien. Je ferai de mon mieux pour apprendre à contrôler mon pouvoir, afin que lorsque je te ferai un câlin, je ne te prive pas de ta force vitale... Un câlin, n'est-ce pas ? La façon humaine d'exprimer la gratitude ?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5572_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Si je reste ici, je n'ai pas besoin de payer quoi que ce soit ? Je peux t'aider à obtenir du statut ici. Il suffit de menacer de leur vider la vie — c'est simple, comme ce que j'ai fait pour Teinture... Ah ! Ne dis à personne cela !"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5573_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Désolé, je ne suis pas comme les autres... Je suis imparfait."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5574_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Une serveuse expérimentée peut grandement améliorer le salon, mais une serveuse bleu-vert... laissez-moi reconsidérer..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Chat·À propos de Karen"
  },
  Voice_5575_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Karen »"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "Teinture est ma sœur jumelle. Contrairement à moi, elle brille toujours intensément...\nSans mon poids, elle aurait un avenir plus radieux, son chant résonnant à travers la galaxie..."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5576_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "Le berceau est exigu, sans place pour étirer mon corps... Mais Tinct a dit que, pour la sécurité de tous, je devrais rester dans le berceau... Puisque c'est son souhait, je vais m'y conformer."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5577_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "J'ai souvent l'impression d'exister dans l'intervalle entre la vie et la mort. Où que je sois, la mélancolie se répand comme une marée, et des tragédies se déroulent les unes après les autres. Même ainsi, voudrais-tu toujours que j'écrive un poème pour toi ? Hmm... peut-être que tu mérites le plus doux..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5578_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "\"Les roses n'ont pas encore fleuri, mais l'aube approche.\""
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5579_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "Que désires-tu ? Est-ce la beauté des mots élégants, la renommée répandue, ou la sincérité sincère derrière ces mots ?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5580_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Avec de l'encre invisible, esquissez les bourgeons déformés... Cette branche de rose fantomatique et éthérée peut en réalité inspirer l'inspiration poétique..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5581_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Écoutez mon Seigneur."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Réveil · II"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Sacrifice ! Redessine le Royaume de Dieu—"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Réveil III"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Si tu insistes, je vais retourner au soleil... le même soleil que le jour où j'ai quitté la Cité..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5582_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, veux-tu voir un univers en destruction ? Eh, il est trop tard pour faire marche arrière maintenant !"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5583_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Bois, le goût sucré de la mort."
  },
  Voice_5584_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5585_AwakerVoiceContent = {
    Text = "Bois, le goût sucré de la mort."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "C'est assez !"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5587_AwakerVoiceContent = {Text = "Non..."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "Regarde la majesté de Yu."
  },
  Voice_5588_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5589_AwakerVoiceContent = {
    Text = "L'air sur le campus à 4 heures du matin est rafraîchissant. Je suis heureux que tu sois prêt à t'entraîner avec moi. Je dois dire que sculpter est un véritable exercice."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de la matinée"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Ce pouvoir se sent plutôt bon à utiliser."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5590_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Je déteste les gens qui ne paient pas pour ce qu'ils achètent. Si vous tenez une boutique assez longtemps, vous rencontrerez ce genre de problème. Je n'ai d'autre choix que de m'en occuper moi-même et de récupérer la facture~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Torturez lentement."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Torturez lentement."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5594_AwakerVoiceContent = {Text = "Charger."},
  Voice_5594_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5595_AwakerVoiceContent = {Text = "Commencer."},
  Voice_5595_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "Que cet endroit devienne une mer d'excitation pour tous !"
  },
  Voice_5596_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5597_AwakerVoiceContent = {
    Text = "Quoi ? T'attends-tu à ce que je te remercie ?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "En tant qu'hommage, ceci est loin d'être adéquat... mais à la lumière de votre sincérité, je vais l'accepter à contrecœur."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Penses-tu vraiment que cela me ferait t'écouter ?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5601_AwakerVoiceContent = {Text = "Allez !"},
  Voice_5601_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "Monstres ingrats, assassins et tueurs – ont-ils une valeur que vous reconnaissez ? Monstre."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5602_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Peu importe combien de coussins vous empilez, un trône en lapis-lazuli ne peut pas se comparer à un lit de plumes. À cet égard, il y a quelque chose de louable dans votre endroit."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Une punition mineure."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Je déteste la solitude, déteste m'inquiéter des sentiments de quelqu'un dans une obscurité sans fin... Alors, s'il vous plaît, ne m'abandonnez pas, d'accord ?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Si j'étais toi, je mettrais tous les Réveilleurs en cage ! Une fois que des chiens fous se libèrent, ils mordent toujours leurs maîtres en premier."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5606_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "J'avais une heure de retard pour cette réunion—blâmez ces bienfaiteurs qui ont aboli l'esclavage ! Maintenant, il n'y a personne pour me coiffer !"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5607_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Incroyable, ma maison a péri ainsi... C'était la grande Rome ! Tu dois en avoir entendu parler !"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5608_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Allez, commençons par une victoire !"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "C'est la bénédiction de mon seigneur."
  },
  Voice_5610_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5611_AwakerVoiceContent = {
    Text = "Garde ta pitié pour toi. Je n'aime pas ça, et je n'ai besoin de la sympathie de personne. Si tu continues à me regarder comme ça, je pourrais ne pas pouvoir résister à l'envie de te tourmenter... Tu ne veux pas que les choses échappent à tout contrôle, n'est-ce pas ? Alors sois un bon garçon/une bonne fille, écoute, et deviens obéissant comme mon gladiateur."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5611_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Ne *silence* demande pas à nouveau. J'étais imprudent, j'ai laissé le gladiateur s'échapper, et ma famille entière a été tuée ! Tout comme l'Empire romain maintenant, réduit en cendres !"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5612_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Comparé aux autres, Nymphaea est juste une personne ordinaire sans réalisations ni valeur.\nCe qui m'a réveillé... pourrait être quelques petits souhaits modestes."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Aujourd'hui, j'ai de nouveau enfreint les règles de l'école en arrivant cinq minutes en retard en classe... Par conséquent, je demande sincèrement la punition la plus sévère, de préférence infligée par le Gardien."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Les outils ont aussi besoin d'entretien. Un ensemble d'outils pratique est l'âme d'un mécanicien."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5615_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Endurance méprisante)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Si cela se reproduit, je demanderai une probation disciplinaire pour toi."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "En plus de me battre, j'ai d'autres tâches à accomplir. Même à l'Éon archéen, je n'étais pas inactif... Hé, vous ne pensez pas vraiment que je suis juste un brute qui ne sait que se battre, n'est-ce pas ?"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos du travail"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Lorsque les gens s'approchent de moi, ils se remémorent toujours leurs souvenirs les plus tristes et ne peuvent s'empêcher de pleurer. Quelqu'un comme moi peut-il encore grandir ?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5619_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "Est-ce correct ?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "Cet endroit est bien mieux que la sale et puante Prison de la Nouvelle Porte ! Que ce soit en s'étendant sur le canapé ou serré dans un coin, tout est assez confortable, n'est-ce pas ?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5623_AwakerVoiceContent = {Text = "Brown... !"},
  Voice_5623_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5624_AwakerVoiceContent = {
    Text = "Coquille, où est-elle allée"
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5625_AwakerVoiceContent = {Text = "Rusé !"},
  Voice_5625_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "Où est passée la coquille en spirale ?!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "La Voie lactée en mouvement..."
  },
  Voice_5627_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita n'aime pas que ses amis partent soudainement... Mais, s'ils reviennent, Aurita leur pardonnera !"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Une femme qui navigue seule à travers la mer est soit une déesse, soit une folle. Prendre Miryam pour une déesse était une grave erreur."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Chat·À propos de Miryam"
  },
  Voice_5629_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Miryam »"
  },
  Voice_5630_AwakerVoiceContent = {
    Text = "...D'accord !"
  },
  Voice_5630_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "J'ai secrètement observé la magie de Mademoiselle Casiah. Sa performance a apporté de la joie au public, mais moi, j'apporte toujours de la tristesse... Pensez-vous que les larmes et les sourires sont également précieux ? Peut-être..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Chat · À propos de Casiah"
  },
  Voice_56313_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Casiah\""
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "La poésie, les flammes et la tristesse sont similaires ; elles vous engloutissent sans préavis... Au moment où vous reprenez vos sens, vous êtes déjà immergé dans le monde de la poésie..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Laisse les poèmes du passé éveiller le jardin caché dans ton cœur."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "La poésie et les fleurs sont probablement la même chose, n'est-ce pas ? Toutes deux sont éphémères mais éternelles. Dans ce monde sans limites, elles capturent les moments les plus inoubliables dans un petit espace... Je pense que tout le monde est tombé silencieux devant un poème, tout comme ils s'arrêtent pour admirer la floraison d'une fleur."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos de la Poésie"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "J'ai presque oublié... Quels types de fleurs fleurissent à Cité cette saison ?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos de Cité"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Votre présence a ravivé l'encre dans ma plume, lui permettant de couler à nouveau comme un doux ruisseau. Je continuerai à écrire de la poésie pour votre histoire."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos du Gardien 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "La beauté des fleurs en pleine floraison est égalée par la tristesse de leur flétrissement. Peu importe combien de fois je ressens de la peine, je ne peux pas m'empêcher de m'arrêter et de les pleurer. Si je devais les ignorer par peur de la douleur, comme ces fleurs seraient tristes..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos de la Souffrance"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Pour étudier la structure interne de ce corps pendant qu'Erica est \"endormie\", Winkle a demandé que je me repose dans son bureau la nuit.\nDois-je mentionner qu'Erica conserve une partie de sa conscience pendant son sommeil ?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Discussion·À propos du Bigorneau"
  },
  Voice_5631_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Bigorneau »"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "La Dame Rouge est vraiment belle. Sa force et sa confiance, son sourire gracieux face au destin, et sa force vitale vibrante mais résolue, tout cela me rend jaloux"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de Sorel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Débloqué après avoir obtenu Éveillé«Sorel»"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "J'ai écrit un nouveau poème hier, mais je ne l'ai montré à personne. Ce n'est pas très bon, mais... Gardien, seriez-vous prêt à y jeter un coup d'œil ?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos du Gardien 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Le Club de Poésie des Étudiants veut que je sois leur conseiller... Je ne peux pas accepter. Je ne veux pas assombrir leur esprit, mais je ne ferais que leur apporter déception et découragement."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "Il n'y a rien à détester dans ce monde. Les années dorées méritent des éloges, tandis que le déclin de la vieillesse mérite de la pitié ; la beauté de la jeunesse est enviable, tandis que les lambeaux usés évoquent la réflexion."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Chaque fois que je vois Mademoiselle Nymphaea, je pense à cette peinture de nénuphars. Elle porte l'amertume tranquille et le parfum des nénuphars... Je me demande à quoi ressemble son monde ?"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos de Nymphaea"
  },
  Voice_56324_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Nymphaea »"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "J'ai toujours senti la présence de \"fantômes\" autour de moi, comme une possession ou un enchantement inexplicable, drainant mon espoir pour le monde. Mais si c'est un fantôme, comment expliques-tu que le lait et l'eau disparaissent dans l'air... ?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos des Fantômes"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Mon corps n'était pas affecté par la Dissolution ; ces liquides noirs ne sont que de l'encre. Mais honnêtement, même sans Dissolution, tout finit par se transformer en Illusion, n'est-ce pas ?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "Dans la pierre tombale de la Clé Sépulcre, j'ai vu le nom du Gardien... Les souvenirs de la vie étaient douloureux, mais je n'avais jamais l'intention de les oublier. Pour le Gardien, ces souvenirs perdus doivent également être précieux, n'est-ce pas ?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos de la Mémoire"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Si la poésie existe pour louer la beauté, alors son existence est comme une poésie elle-même. Quand elle commence à chanter, je comprends soudain ce que les anciens décrivaient comme la voix d'un rossignol..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Chit-chat·À propos de la Teinture"
  },
  Voice_56328_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Teinture »"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "La belle danseuse... Ses flammes vert émeraude sont irrésistibles, même si elles réduisent quelqu'un en cendres..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Liz\""
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Remplacer l'absorption de l'essence primordiale de cette manière ?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Délicieux, absolument délicieux."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Invité, quel genre de récompense désirez-vous ?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Dépêchez-vous de finir. Ne traînez pas dans les rues."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Sacrifice inévitable"
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(Un gémissement étouffé d'endurance)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Entrée actuelle complète. Émettant le courant actuel."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Ne sous-estime pas le meilleur voleur de rue !"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "Voici l'hommage d'ouverture !"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "Le Mirage Millénaire apparaît ici !"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "S'approchant..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5638_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Sink and burn! Danse vers la destruction!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Ceci est la ville où d'innombrables âmes perdues errent, incapables de trouver leur chemin vers chez elles."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Laisse-moi te donner mon énergie de transfert restante... !"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Ne sous-estime pas le meilleur voleur de rue !"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = [[
Est-ce un ennemi ? Veuillez me donner le commandement d'attaque.
La boue noire est un ennemi... Lily est-elle aussi un ennemi ?]]
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Erica l'Automate, Torse No. EA307881, Moteur No. MF311028. Enchantée d'être à votre service."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5641_AwakerVoiceContent = {
    Text = "Combattre de toutes vos forces jusqu'à ce que l'ennemi soit complètement vaincu !"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Bonjour, je suis... Peux-tu me dire mon nom ?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5643_AwakerVoiceContent = {
    Text = "Après être venu à l'école, j'ai compris la maladie appelée Dissolution qui m'avait infecté. Mes parents m'éloignaient toujours de l'océan pendant que j'étais en vie, et maintenant il semble que cette infection soit en effet liée à ma proximité avec la mer..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "D'accord, je ne vais pas vous \"décevoir\""
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Cette respiration ardente—"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Allez."},
  Voice_5646_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5647_AwakerVoiceContent = {Text = "Tournez."},
  Voice_5647_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5648_AwakerVoiceContent = {Text = "Hé !"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "Le jour est enfin venu..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "Je n'ai pas fini... Que diriez-vous de vous lever pour que je puisse vous tuer à nouveau ?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Gardien, je dois te parler. Avant d'atteindre la victoire finale, certaines personnes ne devraient pas être si extravagantes. Souviens-toi, je ne me bats pas pour les vies luxueuses de ces gens."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de Sorel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Débloqué après avoir obtenu Éveillé«Sorel»"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Si je suis emporté en tant que prisonnier de guerre, quel cruel destin m'attend ?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "Regarde ça !"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Hmph !"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Ouf—tellement somnolent. Avant de nous reposer, as-tu préparé des rafraîchissements pour la détente ?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Mère, voudrais-tu les toucher ? On dit qu'ils sont très doux."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5659_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hmm hmm hmm, la la la~ Nettoyer, nettoyer, j'adore nettoyer, je me sens génial~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos du travail"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Gémissant de douleur)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm... Pas mal."
  },
  Voice_5662_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5663_AwakerVoiceContent = {
    Text = "(Gémissant de douleur)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(Gémissant de douleur)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Colère brûlante !"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "J'ai vu beaucoup de gens devenir fous à cause de la Dissolution. Honnêtement, je suis déjà assez fou. La Dissolution ne m'affectera pas."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Heh~ Hahaha !"
  },
  Voice_5667_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5668_AwakerVoiceContent = {
    Text = "De bons outils sont la moitié du succès !"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "On se sent comme revenu à la vie."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5670_AwakerVoiceContent = {Text = "Pas mal."},
  Voice_5670_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Maintenant, je peux balancer avec plus de puissance."
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Équilibrer l'assiduité, maintenir les progrès de la recherche et accomplir les tâches d'enseignement. Il semble que l'expérience de compression temporelle inverse doive être priorisée."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5672_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Un pas de plus vers l'aventure officielle."
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Ne laissez personne près de l'eau, sinon la flamme de votre amour risque de s'éteindre !"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Combattre jusqu'à la fin !"
  },
  Voice_5675_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5676_AwakerVoiceContent = {
    Text = "Vous avez vraiment un courage remarquable. Regardez ces tentacules—n'avez-vous pas peur d'être consumé par la folie ?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5676_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_5677_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5678_AwakerVoiceContent = {Text = "Aïe..."},
  Voice_5678_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Veuillez arrêter !"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "Souhaitez-vous le toucher ? Mon cœur bat à cause de votre présence."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5680_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Ils chantent joyeusement. Merci, Maître."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5681_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Quelque chose s'éveille dans ma poitrine... chaud et doux. Lily, les larmes de Lily sont presque...\nMère, célébrons ensemble."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5682_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Être avec ma mère me remplit d'un sentiment de bonheur."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5683_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Je suis plein... Mon estomac est plein.\nLily deviendra-t-elle plus forte après le rituel ?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5684_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "J'aime la mer. Est-ce ironique ? Parce que tout ce que je possédais est maintenant coulé dans Aequor..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "Fais attention !"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Ce que je déteste...? Rien. Détesterais-tu une poussière ou une feuille ?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "J'ai refusé plusieurs fois les invitations du banquet de la servante. Elle semblait un peu découragée... Mais par rapport à s'amuser, la sécurité du maître est bien plus importante !"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Chat·À propos de Karen"
  },
  Voice_5688_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Karen »"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "Le seigneur est la raison de l'existence d'un chevalier, alors n'hésitez pas à me donner des ordres !"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...Nous pourrions avoir besoin d'une clé dynamométrique pour cela... Hmm, désolé, tu viens de m'appeler ?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "Comment oses-tu !"
  },
  Voice_5692_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5693_AwakerVoiceContent = {
    Text = "（Hum élégant）"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(Un gémissement étouffé d'endurance)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "C'est assez."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "Soyez doux."
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Il est clair qu'il est toujours difficile de se concentrer..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Elle reste souvent près de moi la nuit. Est–ce simplement parce que ma tête est trop visible ?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Discussion·À propos du Bigorneau"
  },
  Voice_5698_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Bigorneau »"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "J'ai toujours attendu l'arrivée de la destruction, sans jamais considérer \"la résistance\"... Vas-tu aider mon âme superficielle à traverser l'abîme ? Même dans un monde où j'ai à peine survécu, tu m'accordes encore le salut..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5699_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Puisque je suis Éveillé en tant que ton apôtre, je cherche rien d'autre que ta paix et ta joie, c'est mon souhait... Ugh... Ah... En effet, survie, survie, survie, vivre"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5700_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Pourquoi ne pas te perdre dans mon amour ? Ne m'as-tu pas réveillé pour la chaleur de mon étreinte ?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5701_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Ne souhaites-tu pas éviter de t'entrelacer avec des femmes d'origines inconnues ? Très bien, très bien. Le roi déchu de Ninive, les gens de Shinar qui aspirent à atteindre les cieux, la fille dont la volonté a été prise sous l'arbre sacré de l'Euphrate... Par où aimerais-tu commencer ?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5702_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Pourquoi m'évites-tu toujours ? Es-tu timide ? Comme c'est mignon, cette réticence à affronter tes désirs"
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5703_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Cet endroit est terrible, absolument terrible ! Comment osent-ils me faire partager une table pour le thé de l'après-midi ! ...Les biscuits faits maison sont plutôt bons cependant. Envoyez-en à ma chambre après le dîner."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5705_AwakerVoiceContent = {Text = "Salut !"},
  Voice_5705_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5706_AwakerVoiceContent = {
    Text = "Regarde ça !"
  },
  Voice_5706_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5707_AwakerVoiceContent = {
    Text = "Dissolution... Il y a des enregistrements dans l'académie de ma maison, mais Karen déteste lire et a tout oublié !"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Souhaites-tu que je mette les voiles à nouveau ? Si tu peux ignorer mes échecs passés, je vais essayer."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5708_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Des aversions ? Beaucoup - des patrons qui font rester les employés tard, des religieuses auto-satisfaite, des estomacs grognants, du pain noir avec des éclats de verre..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "C'est de la faute d'Aigis... Tout est de ma faute..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Terminons cela !"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "Grâce à la bonté de Mademoiselle Hannah, j'ai assisté à la répétition de la chorale. Les hymnes sont assez différents des shanties de mer. Pendant mon temps à protéger le navire, je n'avais jamais entendu de telles mélodies distinctives..."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "Que dirais-tu de ce mouvement !"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "Que dirais-tu de ce mouvement !"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "Si effrayant~"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Ouh"},
  Voice_5716_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Bonjour, mon nouveau maître ! Le menu d'aujourd'hui comprend du pudding d'escargot, un ragoût de crapaud et du vin de flamme verte. N'hésitez pas à choisir."
  },
  Voice_5717_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5718_AwakerVoiceContent = {
    Text = "Est-ce la forme de retour à la Genèse...? Non, c'est un peu différent de ce que j'imaginais. Mais si je pouvais devenir comme ça, ce serait génial."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Bavard · À propos de la lignée Aequor"
  },
  Voice_5718_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'un des Éveillés: \"Tulu\", \"Murphy\", \"Miryam\" ou \"Goliath\"."
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Attendre le bon moment."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "Regarde ça !"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Agneaux, la miséricorde de Dieu vous rachètera."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Agneaux, la miséricorde de Dieu vous rachètera."
  },
  Voice_5722_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5723_AwakerVoiceContent = {Text = "Meurs !"},
  Voice_5723_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5724_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5725_AwakerVoiceContent = {Text = "Hmph !"},
  Voice_5725_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5726_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "Elle est aussi une âme pitoyable, destinée à être dévastée par le destin. Car quand Il descendra vraiment, ce sera le moment où je lui livrerai la mort."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Chat·À propos de Miryam"
  },
  Voice_5727_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Miryam »"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "Soyez tâché de sang !"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "Vengeance... !"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5730_AwakerVoiceContent = {
    Text = "Cela fait mal..."
  },
  Voice_5730_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5731_AwakerVoiceContent = {
    Text = "(Gémissement réprimé de douleur)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(Gémissement réprimé de douleur)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5733_AwakerVoiceContent = {Text = "Aïe..."},
  Voice_5733_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "Souhaitez-vous couler avec moi ?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5735_AwakerVoiceContent = {Text = "Va-t-en !"},
  Voice_5735_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5736_AwakerVoiceContent = {
    Text = "Des choses que je déteste... un bureau en désordre, une garde-robe en fouillis, des rebords de fenêtre poussiéreux—oui, je décris ta chambre. D'ici demain à 7 heures, je veux qu'elle soit restaurée comme elle était avant que tu emménages."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "（Fredonnant avec intérêt）"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "Intéressant !"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "（Ricaner avec dédain）"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Si nécessaire, je peux quitter le berceau..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "Le veux-tu ?"
  },
  Voice_5741_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5742_AwakerVoiceContent = {
    Text = "Attention~ !"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "On double ! On redouble !"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Cela me rappelle la première paire de chaussures de danse rouges que j'ai reçue quand j'avais huit ans. Je les aime vraiment. Merci, Gardien."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5744_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Ami... Maître ? Ou Mère ?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Ma protection peut également échouer parfois..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5747_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5747_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5748_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5748_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5749_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5749_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "Aime ? Quelqu'un m'a déjà posé cette question sur les champs de bataille du Péloponnèse... Il est trop tard. J'ai longtemps abandonné de telles préférences personnelles."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Chut... s'il vous plaît ne laissez pas \"eux\" découvrir que je deviens plus fort."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"Ils\" ont dit... Merci beaucoup."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Uh... Qu'est-ce que c'est ?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Cela ne fera que m'approcher de l'Abysse."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5754_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Vous êtes mon serviteur bien-aimé. Je sais que vous l'appelez un ami, un partenaire, un camarade... Peu importe ce qui vous rend heureux."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "J'ai eu la réponse... Même si ce n'était pas ce à quoi je m'attendais, j'ai quand même eu la réponse."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5756_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "Est-ce de la \"peur\" ? Ou de la \"tristesse\" ? Votre expression de désespoir est vraiment captivante."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5757_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "Le parfum de la mort et de l'annihilation, si vif."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5758_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "La vie ici ? Plutôt, plutôt bonne. Tant que je partage un peu de connaissances sur la science mécanique et la recherche spirituelle avec Mme Poupée, elle me permet de garder les lumières allumées."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "J'espère que Jenkin et Marron passent un bon moment à l'académie. Comparé à sa liberté, les boutons de manchette de Père sont insignifiants. Je suis sûr qu'il a toute une boîte de pièces de rechange."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_5760_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Impossible de partir..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Ayant transcendé les races inférieures, je ne crains pas une telle influence. Même si le corps hôte est brisé, la noble lignée ne périra pas."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Je déteste les gens avec des sourires faux ! Vous ne pouvez rien leur voler en émotions !"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Hmm ? Pourquoi tout le monde est-il silencieux ? Karen déteste le silence. Laisse-moi te raconter une histoire. Il était une fois, une montagne..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "Lily saisira l'avenir... Tokuli—Li !"
  },
  Voice_5765_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5766_AwakerVoiceContent = {
    Text = "Lily saisira l'avenir... Tokuli—Li !"
  },
  Voice_5766_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5767_AwakerVoiceContent = {
    Text = "Si tu cherches à percevoir Sa présence, je pardonnerai temporairement ton impolitesse."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "Je ne veux pas faire ça..."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5769_AwakerVoiceContent = {Text = "Reculez !"},
  Voice_5769_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "Progressivement, je commence à m'harmoniser avec le rythme de ton commandement !"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "Se rapprochant de devenir un véritable chevalier!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Merci pour votre promotion, c'est un honneur"
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "Le bain est un excellent endroit pour passer le temps. La nourriture est délicieuse et ils offrent des services de relaxation musculaire. Tenté ? Construisez-en un à l'école dès maintenant !"
  },
  Voice_5773_AwakerVoiceTitle = {
