  Voice_5785_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5786_AwakerVoiceContent = {Text = "Ha !"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "Hmm... Le maître semble contrarié ? Laissez Karen vous remonter le moral avec une grimace drôle, hehe !\nVous vous sentez mieux maintenant ?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Dévoilez l'essence du monde avec l'intellect humain...!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "J'ai rencontré des individus troublants dans le couloir. Tu devras peut-être coopérer avec eux en raison des circonstances, mais reste vigilant. Le cœur humain est plus cruel que la guerre, et les pires trahisons viennent souvent de l'intérieur."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Hilote\" ou \"Lily\""
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "Votre devoir est terminé, n'est-ce pas ? Pouvez-vous venir avec moi à la ville de Londinium... Hein ? Vos devoirs de mathématiques ne sont pas encore faits ?!\nAh... désolé, je ne m'attendais pas à ce que quelqu'un ne comprenne pas le calcul... Laissez-moi vous aider."
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Petits Entretiens : Sur l'Apprentissage"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Je te jure, ce commerçant est définitivement apparu au salon de Fontainebleau... Je vois, elle est comme ça depuis lors. Je me demande combien de secrets nous pourrons échanger avec elle ?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos des Jonquilles"
  },
  Voice_5791_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jonquille\""
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5792_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5793_AwakerVoiceContent = {
    Text = "Ne le casse pas."
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "Aurita adore jouer avec tout le monde ! Vas-tu te joindre à nous ? Celui-ci est Jelly, celui-là est Hela, et là-bas c'est Jelly... hein ?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Déshonneur, que ce mouvement te purifie !"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "La boutique de Daffodil est maintenant ouverte. Les enfants qui ne sont pas préparés, merci de ne pas entrer sans y penser."
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5796_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Veuillez ne pas toucher mon cou... Juste parce que vous ne pouvez pas le voir, cela ne signifie pas qu'il n'existe pas."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "J'admire ceux qui ont des convictions, qu'ils soient animaux, Éveillés ou humains. S'ils sont des combattants talentueux, c'est encore mieux."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Allez."},
  Voice_5799_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "Ne t'inquiète pas !"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona déteste perdre... Désolée, je veux dire, je n'aime pas les adieux ; c'est trop triste."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Je ne suis pas doué pour traiter avec les clercs. Ils sont ennuyeux et rigides, et ils ont donné leurs ceintures à leur bien-aimé \"Dieu\". Quel dommage, M. Salvador sent si bon..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos de Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Salvador\""
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "L'adrénaline de la bataille surpasse tout, y compris la victoire ou la défaite"
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Qui n'aime pas un lit douillet et une salle de drainage à l'abri des courants d'air... ?"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "...Ne me fais pas rappeler... les jours emprisonnés à Elworth..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Brûle tout !"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "Brûle tout !"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "J'ai suivi l'odeur du sang jusqu'à cet endroit. Puis-je demander... proposez-vous des poches de sang frais ici ?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm... Agrippa a de nombreux compagnons, mais ils semblent tous avoir peur d'elle. Pourrait-il être qu'elle leur vole leur nourriture ?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Agrippa\""
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "Ma vie tourne autour de la danse. Apprendre d'autres connaissances est difficile pour moi. Mais tout le monde est gentil ; ils ne me trahiront pas par vanité ou par argent — je le sens."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Lâche ! Tu possèdes un pouvoir puissant semblable au mien, mais tu te contiens. En quoi cela est-il différent de porter volontairement un collier ?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Lily\""
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Pas assez... toujours pas assez de pouvoir..."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5813_AwakerVoiceContent = {Text = "Revenez."},
  Voice_5813_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5814_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Chapeaux haut de forme, chapeaux melons, chapeaux de détective, bérets... Je dois dire que c'est plutôt amusant de voir à quel point vous, messieurs de la haute société, allez si loin pour dissimuler votre calvitie."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Idle Talk · Sur l'Étiquette"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "J'admire profondément cette personne, le dieu maritime aussi pur et élégant qu'un lys... Vous dites même qu'elle ne pouvait pas contrôler son destin et a finalement sombré dans la mer ? C'est vraiment difficile à imaginer..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Discussion·À propos de Céleste"
  },
  Voice_5816_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Céleste »"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Il n'y a rien dans le monde qu'un géant ne puisse surmonter !"
  },
  Voice_5817_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5818_AwakerVoiceContent = {
    Text = "Il n'y a rien dans le monde qu'un géant ne puisse surmonter !"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Damn, damn...! Le Pouvoir ne me garde que piégé dans ce corps..."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5819_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Je souhaite rester dans un endroit toujours lumineux... Oui, les pôles. Sur cette planète, seuls les pôles."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5820_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Je... je ne peux pas supporter de lourdes responsabilités. Je ne peux que courir après la lumière. Alors, s'il te plaît, ne cesse pas de briller..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5821_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Si je pouvais migrer, je voudrais devenir une étoile..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5822_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Peu importe comment je calcule, la formule pour le transfert de conscience reste insoluble..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5823_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Bienvenue ! Amusons-nous ensemble !"
  },
  Voice_5824_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5825_AwakerVoiceContent = {
    Text = "Monsieur, prenez votre temps pour votre repas !"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "Huff—C'est Aurita ! Un, deux, trois... Waouh ! Bienvenue, bienvenue ! Un nouveau partenaire a rejoint ! Hein ? Je suis le nouveau partenaire ? Eh bien, on peut dire ça !"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5827_AwakerVoiceContent = {
    Text = "Vous appelez ce petit jouet un pistolet ? Seuls les lâches se cachent dans l'ombre pour tendre une embuscade à leurs ennemis."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "C'est sans signification. Faire cela est complètement inutile."
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Vous ne savez absolument rien."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Tu comptes toujours sur moi pour être le backup du \"Sauveur\" ?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Désolé, as-tu vu ma vis ? C'est étrange, mais chaque fois que ce gamin avec les oreilles de souris est là, j'ai l'impression d'oublier où j'ai mis mes affaires..."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_5831_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Je n'oublierai pas tout ce que tu as sacrifié pour mes retrouvailles avec mon maître..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Une Chanson Maîtrisée !"
  },
  Voice_5833_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5834_AwakerVoiceContent = {
    Text = "As-tu reconnu mon souhait ?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "J'espère que ton commandement ne décevra pas."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "Est-ce ce corps ou ma conscience qui a évolué ? Un sujet intrigant."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5836_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5837_AwakerVoiceContent = {Text = "Recule."},
  Voice_5837_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "Écartez-vous."
  },
  Voice_5838_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "Mes veines sont enflammées par la volonté de survivre, hurlant et me poussant à verser du sang sur chaque centimètre de cette planète... Ah, j'ai trop divagué ; veuillez me pardonner. Je suis Thais. M'avez-vous invoqué ? Êtes-vous prêt à fusionner avec moi ?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5840_AwakerVoiceContent = {
    Text = "Si seulement Aigis pouvait supporter ce liquide noir pour tout le monde... Après tout, Aigis n'a jamais existé, ce qui pourrait être une bonne chose pour ce monde, non ?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Les hobbies incluent l'Hypothèse de Riemann—c'est le slogan du paon, pas le mien. Personnellement, je m'intéresse davantage aux normes de masse atomique."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "Le goût de l'exil et d'être dérivé en mer... Une fois suffit."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Regardez attentivement !"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "Regardez attentivement !"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Tant que vous pouvez maintenir cette justice, je porterai toujours le fardeau de la lame."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Savais-tu légende du \"Peintre\" ici ? À partir de ces graffitis expressionnistes, je sens un toucher familier..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Tellement douloureux, et pourtant si exaltant—"
  },
  Voice_5848_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5849_AwakerVoiceContent = {
    Text = "Ressentez ma colère !"
  },
  Voice_5849_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5850_AwakerVoiceContent = {
    Text = "Laisse cette victoire être consignée en poésie."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Grandissez—"
  },
  Voice_5851_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5852_AwakerVoiceContent = {
    Text = "Regarde ça !"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5853_AwakerVoiceContent = {Text = "Hé !"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Peut-être qu'une fois grand, je vais pouvoir me contrôler et ne pas drainager la Vie des autres... Juste un petit peu suffit pour que je survive."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5854_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Il semble que j'ai pris du poids. Le berceau peut-il encore porter mon poids ?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5855_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "Le pouvoir est sur le point de déborder, et mon dos me démange. Est-ce que je grandis ?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_5856_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Bien que j'ai encore l'air d'un enfant, maintenant... j'ai le pouvoir de te protéger."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5857_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Je ferai de mon mieux pour grandir."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_5858_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Tu ingrat, pourquoi es-tu si obstiné à me réveiller ?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5860_AwakerVoiceContent = {
    Text = "Je deviendrai la Mère des Dieux !"
  },
  Voice_5860_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5861_AwakerVoiceContent = {
    Text = "Combien de fois ai-je été convoqué... Humain, tu ferais mieux d'avoir suffisamment de \"nourriture\" préparée, sinon je ne peux rien garantir."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5862_AwakerVoiceContent = {
    Text = "Au-delà de la Porte !"
  },
  Voice_5862_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5863_AwakerVoiceContent = {Text = "Insensé."},
  Voice_5863_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5864_AwakerVoiceContent = {Text = "Haha"},
  Voice_5864_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "Hmph, pas mal. Je vais mettre tout dans notre prochain duel."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "Espèce insolente !"
  },
  Voice_5866_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_5867_AwakerVoiceContent = {
    Text = "Parfois, la beauté de l'art réside dans son annihilation. Mais votre échec... ne tombe clairement pas dans cette catégorie."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Vous êtes mon auditeur le plus important. Chaque fois que vous en avez besoin, je suis prêt à chanter et à vous donner tout."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Choses préférées ? Algues, bancs de poissons, colonnades, labyrinthes... Bien sûr que je les ai vus ! Ils sont tous dans le livre de l'Oncle Ornn !"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Est-ce une préparation pour une mission d'enquête ? Je comprends."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5870_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Mon nom est Céleste. Tant que tu as encore besoin de moi, je serai ici."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5872_AwakerVoiceContent = {
    Text = "Apprends ta leçon !"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Montrez un peu de respect, junior. Dans l'armée, la hiérarchie est respectée, et les ordres doivent être suivis sans exception. Un tel comportement inapproprié sera puni."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Je serais prêt à fournir un service après-vente pour ces \"petits jouets\", mais la question est, oses-tu accepter mon service ?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Petits Entretiens · Sur les Inventions"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Tu es le maître ici, mais aussi un invité dans mon salon. Je préparerai le meilleur accueil pour ta visite—préférerais-tu un jupon écarlate ou une chemise de nuit rose blanche ?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Désolé, la lumière du soleil ici est un peu éblouissante... Une souris d'une grotte sombre ne peut pas s'adapter rapidement."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Capable de corroder tout, effaçant tout... C'était tout un arme. Si seulement j'avais su à l'époque... Heh."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "On dit que les corps qui tressautent dans les flammes semblent danser."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Chitchat·À propos du feu"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Ne sortez pas la nuit. Même avec une lumière de 2000 lumens, ce n'est pas complètement sûr... Une fois que vous pénétrez dans l'obscurité, le mal qui se cache au-delà de votre vue vous poursuivra, vous dévorera, vous poursuivra, vous dévorera... jusqu'à ce qu'il ne reste rien."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de la Nuit"
  },
  Voice_5881_AwakerVoiceContent = {Text = "Crier."},
  Voice_5881_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5882_AwakerVoiceContent = {Text = "Reçu."},
  Voice_5882_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "C'est le désir de vie qui pousse le cygne à lutter pour son retour vers le ciel lointain."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5883_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Ça commence à changer !"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5885_AwakerVoiceContent = {
    Text = "Au secours !"
  },
  Voice_5885_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5886_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_5887_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5887_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5888_AwakerVoiceContent = {Text = "Ah !"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "Ah, Marron s'est enfui ! Je... Je devrais probablement reculer un peu...\nJe voulais être son amie, mais au lieu de ça, je suis devenue son cauchemar... Elle ne veut probablement pas me voir de toute façon..."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_5889_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Chapelle ? Merci, mais je ne suis pas si démodé. Tant que je garde les enseignements du Dieu de la Bonté dans mon cœur et que je suis sa volonté, mon âme ne s'éloignera jamais de sa gloire."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Chitchat · À propos de la chapelle"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Mon nom est Ogier. Selon notre contrat, je jure ma loyauté de chevalier envers toi, de protéger ton bien-être et d'éliminer tes ennemis. Ce serment je fais, jamais je n'oublierai."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5892_AwakerVoiceContent = {
    Text = "Cette femme émaciée avec des pupilles doubles sent exactement comme un insecte spartiate."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Agrippa\""
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Aime ? Bien sûr, bonne fortune. Je cherche toujours un bon signe avant de sortir chaque jour."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "P-Peut-être ne dis pas à Mlle Hannah que je me cache ici. Je ne suis pas encore prêt..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos de Hannah"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Que diriez-vous de ceci ?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "Tu es mon précieux invité. Souviens-toi, tu es le seul autorisé à avoir une dette. Après tout, cela fait des années que je n'ai pas vu un crâne aussi parfait..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_5898_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5899_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "Aime... Un roi ne devrait pas montrer de telles préférences, mais si je pouvais échapper aux mémoriaux et prières ennuyeux, je profiterais certainement d'un moment de loisir sur un canapé moelleux."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Je vais prendre ton irrespect comme une supplication pour un repos éternel."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Tu détestes ça ? Je déteste un destin inéluctable et une tragédie inévitable."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hmph !"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(Humming étouffé)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Ne t'approche pas !"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Oh, curieux de mon secret ? Ce nom, ce corps, ce visage, cette voix—tout vient de la femme qui possédait une tête de San Pedro. Elle a conclu un accord avec moi... Après sa mort, je suis devenue elle. Quant à son emplacement... eh bien, c'est ma collection la plus exquise, vous savez ?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5906_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Vous êtes un invité délicieux ; même moi, je suis captivé par votre tête unique... Si jamais vous envisagez de vous en séparer, assurez-vous de visiter ma petite boutique. Haha... juste une blague."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5907_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Vous vous demandez quelle est ma véritable identité ? Il est encore trop tôt pour ça. Croyez simplement ceci : les enfants perdus peuvent retrouver leur chemin dans ma boutique. Peut-être que cela vous inclut aussi ?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5908_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Personne ne sera blessé."
  },
  Voice_5909_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5910_AwakerVoiceContent = {
    Text = "Ce n'est pas encore fini !"
  },
  Voice_5910_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5911_AwakerVoiceContent = {
    Text = "Voyant à quel point vous travaillez dur, je me sens presque coupable de réclamer ma récompense si tôt. Alors, je vais laisser votre tête là où elle est pour l'instant.\nMais n'oubliez pas, elle est déjà réservée comme ma propriété personnelle, d'accord ?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5911_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Je n'ai pas toujours été comme ça ; elle m'a donné une nouvelle vie. En ce sens, vous m'avez aussi donné une seconde vie, donc je vais chérir votre tête aussi."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5912_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Échapper complètement à l'obscurité."
  },
  Voice_5913_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5914_AwakerVoiceContent = {
    Text = "Alors l'aventure est aussi dangereuse que cela..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Pourquoi cette fille idiote s'enfuit-elle dès qu'elle me voit ? La prochaine fois, je vais marcher sur son fil de laine et voir où elle peut aller."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Chat · À propos d'Aigis"
  },
  Voice_5915_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Aigis »"
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5917_AwakerVoiceContent = {
    Text = "Hmph~ Hahaha !"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5918_AwakerVoiceContent = {Text = "Hahaha !"},
  Voice_5918_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Ce gamin est astucieux ; la survie dans la rue nécessite ce genre d'esprit. Si je menais encore mon enquête, je deviendrais définitivement son ami."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_5919_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "Le Saint Père ne peut sauver tout le monde. Il peut peut-être aider une âme malheureuse, mais il ne peut pas sortir tout le monde de la boue... J'attends avec impatience sa chute, l'effondrement de sa foi."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos de Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Salvador\""
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Vous pouvez trouver tout dans les égouts de Londinium : saumon, savon, whisky à moitié bu... \nQuoi ? Vous demandez pourquoi je sais cela ? Une fois, j'ai traîné le corps de mon frère à travers cinq miles de cela..."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos des égouts"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Genoux devant moi !"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "Genou devant moi."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Après avoir entrevu le vrai monde au-delà du champ de bataille, je me suis un jour demandé la valeur des \"héros\". Mais heureusement, je vous ai rencontré — honnête, courageux et pur. Sous votre direction, je lutterai sans relâche pour la paix et la stabilité. Cette fois, je terminerai sûrement ma rédemption."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5924_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Aïe ! Oh non..."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Impur, sale, chaotique—c'est notre Pouvoir."
  },
  Voice_5926_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5927_AwakerVoiceContent = {
    Text = "J'ai horreur de ton acte prétentieux. Tu penses que je suis fou, pathétique, n'est-ce pas ? Pour moi, tu es comme Icare, aveuglé par le soleil. Ce sont vraiment les pathétiques ici."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Laissez-moi prendre les devants !"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Ces gars-là semblent étranges. Ils ne doivent pas être des formes de vie nées naturellement sur cette planète."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Chit-chat: À propos des Voyageurs des Étoiles"
  },
  Voice_5929_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'un des Éveillés \"Bigorneau\", \"Teinture\", \"Évanouissement\" ou \"Wanda\"."
  },
  Voice_5931_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5931_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "Disparaissez !"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Veuillez ne pas..."
  },
  Voice_5933_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5934_AwakerVoiceContent = {
    Text = "Être un monstre, ça me va. Tout ce que j'ai toujours voulu, c'est le pouvoir pour me venger."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5934_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "En plus d'éliminer votre adversaire, avez-vous d'autres désirs ? En retour, je réaliserai votre souhait... selon mes capacités, bien sûr."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_5935_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_5936_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5936_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "Un compagnon ? ... Je vais y réfléchir. Ne meurs pas avant que je prenne ma décision."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_5937_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Depuis qu'il a été clairement documenté pour la première fois, le D-phénomène a affecté la vie de plus d'un million de personnes. Nos actions sont cruciales pour la survie de l'ensemble de la population humaine."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "Plein gaz !"
  },
  Voice_5939_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "Prenez garde à la Furie de la Mer"
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Prenez garde à la Furie de la Mer"
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5942_AwakerVoiceContent = {Text = "Hé !"},
  Voice_5942_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "Je suis sa princesse et sa mère. Quant à toi, tu n'es qu'une fourmi insignifiante devant Lui."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Tout va bien, levons les voiles triomphantes."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Restez loin de moi ! Souhaitez-vous devenir le jouet de la princesse ou un sacrifice pour la naissance divine ?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5945_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Une victoire facile, une victoire totale !"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Une victoire facile, une victoire totale !"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Je te permets de devenir témoin, de contempler le moment radiant qui défie l'éthique."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5946_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Creux ? Les creux sont souvent créés lors de la télékinésie. Les creux créés par Casiah sont-ils liés à une autre dimension, comme ceux dans la Dissolution ?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Gardien, par le pouvoir de la Déesse Mère, j'ai réservé une place pour toi à côté du Trône Aequor. Tu seras témoin de l'ère de renaissance après la Destruction. Réjouis-toi, car c'est la promesse de la Déesse Mère !"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5948_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "En reconnaissance de votre comportement respectueux, je vous accorderai une réponse. Au début, il y avait en effet lutte. Mais maintenant je comprends : ma vie de luxe provient de Lui. La mort n'est pas la fin; Il me renaîtra, me conférant la vie éternelle à travers ce cycle tordu..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5949_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "Le souhait de cette femme est risible. Rien ne peut survivre à l'anéantissement, pas même un \"dieu\"."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Thais"
  },
  Voice_5950_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Thais »"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Je suis un praticien du Spiritisme, pas un être omnipotent, et donc je suis sujet à des erreurs. Les actions de cette femme, qui ont entraîné tout le monde dans la ruine, étaient mes erreurs involontaires... Par conséquent, j'ai besoin de votre assistance. Pour m'assurer que vous pouvez répondre à mon appel à tout moment, vous êtes autorisé à placer un lit dans ma chambre."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5951_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Vous portez le fardeau de faire face aux Clades, un poids lourd pour quelqu'un de votre âge... Si vous aviez su dès le départ que vous ne pouviez pas changer l'avenir, auriez-vous tout de même fidèlement exécuté votre mission ? Ne vous précipitez pas pour répondre ; réfléchissez-y pendant que je me repose. Je suis curieux de connaître votre réponse."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5952_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "Cela fait un certain temps que je me suis réveillé, n'avez-vous rien à me demander ? Les révélations de Dieu, la prophétie absolument vraie, même le trésor de la terre engloutie—n'êtes-vous pas curieux ? \nHum... étrange."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5953_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Je n'ai jamais exigé de culte de quiconque. La folie des autres ne fait que m'épuiser davantage... Reste en retrait, il est temps de se reposer."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5954_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "Je ne vois aucune des qualités de mes subordonnés en vous... Peut-être que c'est mieux ainsi. La pensée de cette femme m'épuise."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5955_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Dieu traite tout le monde de manière égale."
  },
  Voice_5956_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5957_AwakerVoiceContent = {
    Text = "Je sais, tu es un public spécial. Je ne peux pas simplement te zapper dans une autre dimension ; cela causerait de gros problèmes. Hey, l'as-tu déjà fait à quelqu'un d'autre ? Ne demande pas, c'est mon secret !"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Eek, es-tu intéressé par cette apparence ? Il semble qu'il y ait toujours un échange. Cela doit être l'un de mes coups de chance, la chance de Ryker !"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mythag est le lieu où j'ai le plus de souvenirs, et aussi... mon foyer le plus chaleureux."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Laisse-moi faire."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "Comme c'est naïf !"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "Hymne d'Aequor !"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "Ce qui m'a été conféré—"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Compétence·Un·Océan Calme"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Si tu es prêt à reconnaître que je suis encore \"Ramona\", s'il te plaît continue de m'appeler ainsi."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5965_AwakerVoiceContent = {
    Text = "Quoi ? Tu veux aussi exploiter ma colère ?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_5965_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "La vérité... est révélée ici."
  },
  Voice_5966_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_5967_AwakerVoiceContent = {
    Text = "Selon les règles de la rue, la nourriture doit être mangée immédiatement."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "On se sent plein."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hmm... Ça démange. Marron, gratte mon dos pour moi."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "De nouvelles pièces mécaniques aideront grandement mon système à fonctionner — cela ne compte-t-il pas comme aimer quelque chose ? Désolé, j'ai peur de ne pas comprendre ta question. Les préférences n'ont aucun sens pour les poupées mécaniques."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "Regarde ça."
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "Regarde ça !"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Réfléchis bien."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Restez calme et réfléchissez."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "Miss Winkle, comme moi, n'est pas de cette planète... Il n'y a rien qui me relie à ma maison sauf la Teinture. Je me demande ce que Miss Winkle pense de sa patrie ?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Discussion·À propos du Bigorneau"
  },
  Voice_5976_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Bigorneau »"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Ne t'approche pas de moi par derrière, à moins que tu ne veuilles te faire casser le cou."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_5977_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Hah—Comment peux-tu laisser des chats errants traîner sur le campus ?! Et si cette créature mal élevée griffait quelqu'un ?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Mon regard vous met-il mal à l'aise ? Bien, c'est la férocité qui m'a gardé en vie en purgatoire."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_5979_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Épargne-moi les paroles grandiloquentes. Que veux-tu de moi ? Il doit y avoir une raison de garder ma santé mentale intacte."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_5980_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "Ma vengeance était toujours dirigée contre les Spartiates, mais maintenant, même cet État de la cité n'existe plus... Très bien, devenir votre lame n'est pas impossible. J'accepte à contrecœur de vous considérer comme mon partenaire, mais si vous osez me trahir, je vous arracherai le cœur."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_5981_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Mes mains sont tachées de sang. Mes proches faibles ne comprennent pas ma vengeance ; ils murmurent sur ma cruauté, ma ingratitude et ma trahison... La vengeance a toujours été pour moi seul, et personne d'autre."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_5982_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "Il est temps d'utiliser plus d'acier."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "Il est temps d'utiliser plus d'acier."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Mourrez."},
  Voice_5985_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "Je suis... appelle-moi juste Winkle, c'est ainsi que tout le monde m'appelle. Oui, appelle-moi comme cela, exactement comme eux."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5987_AwakerVoiceContent = {
    Text = "Ce corps sera le bouclier de mon maître !"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "Ce corps sera le bouclier de mon maître !"
  },
  Voice_5988_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_5989_AwakerVoiceContent = {
    Text = "\"Casse-Noisette\" est censé être un conte de fées romantique pour les filles, mais ces individus répugnants ne voient que les membres gracieux en mouvement et des désirs vulgaires... Dégoûtant."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Doit... éliminer... !"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... Elle appelle cela un entraînement ? Haha... Permets-moi de rire un moment. Les humains sont encore trop tendres ; tout ce qu'ils font semble être un jeu d'enfant."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Chat·À propos de Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Pandia\""
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Ne t'approche pas !"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "Dois-je me présenter encore ? Tu es vraiment un cas. Je suis Jenkin, et ce gamin est Marron. \"Creak!\"\nN'oublie pas ! Si tu te trompes de nos noms, je te frapperai le *censuré* avec ma lanterne ! \"Creak creak?!\""
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_5994_AwakerVoiceContent = {
    Text = "Saute, saute !"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "Saute, saute !"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "Voici l'hommage d'ouverture !"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5997_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_5998_AwakerVoiceContent = {
    Text = "Juste un peu de pierre, deux ciseaux, et trois iris tournés vers le soleil... Je peux créer n'importe quoi pour vous."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_5998_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_5999_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_5999_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "C'est tout ce qu'il y a ?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Bien."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Cette lutte sans signification..."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6003_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6003_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "Après la mort de Tibère, le peuple de Rome a enfin réalisé son vœu longtemps tenu — le jeter dans le fleuve Tibre pour nourrir les poissons. Bien sûr, ils ont payé un petit prix pour cela : être jetés dans l'arène par Caligula pour mon amusement."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6005_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6005_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6006_AwakerVoiceContent = {
    Text = "Je peux sentir que la petite fille possède des pouvoirs similaires aux miens. Elle n'a pas encore entièrement compris l'ampleur de leur force. Pour ton bien, je vais l'entraîner convenablement."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Lily\""
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Merde, tu continues à me mépriser ?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Preuve d'existence"
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Preuve d'existence"
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Je crois que tout arrive pour une raison, mais... la violence insensée, les préjugés qui poussent des frères et sœurs à se retourner les uns contre les autres, me peinent vraiment. Si quelque chose que je déteste, c'est probablement cela."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Je ne veux vraiment pas utiliser ce pouvoir."
  },
  Voice_6011_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6012_AwakerVoiceContent = {
    Text = "Ne baisse pas ta garde."
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Hmph"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6014_AwakerVoiceContent = {Text = "Arrête !"},
  Voice_6014_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6015_AwakerVoiceContent = {Text = "Arrête !"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Casiah est incroyable ! Elle peut faire apparaître un lapin en un clin d'œil !"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Chat · À propos de Casiah"
  },
  Voice_6016_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Casiah\""
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "Magie, prête !"
  },
  Voice_6017_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6018_AwakerVoiceContent = {
    Text = "Dissolution... Je dois admettre qu'il y a des choses dans ce monde qui échappent au contrôle du pouvoir."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Danse au milieu des flammes émeraude."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Ne t'inquiète pas ; les cicatrices sont le badge d'honneur d'un guerrier."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Tremblez devant ces muscles... toujours prêts à trancher votre tête."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "L'heure du repas ? Ou le temps d'activité ?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6024_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Hmm ! Comme ça, les compagnons d'Aurita ne disparaîtront pas !"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6025_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "Mme Sylvia a dit qu'il faut dire merci quand on reçoit quelque chose... Merci, merci, merci !"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6026_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "C'est le tour d'Aurita d'être le fantôme cette fois ! Vous n'avez que 5 secondes pour vous cacher ! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6027_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Tout le monde a disparu après avoir commencé à jouer à cache-cache. Cette fois, Aurita est déterminée à retrouver tout le monde !"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6028_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Parce qu'ils ont trouvé mes os sous l'eau, ils pensent que j'aime l'eau et veulent construire une piscine devant ma chambre ? \nHaha... Faites comme vous voulez. Ne me dérangez plus avec de telles trivialités."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Une petite goutte dans l'océan, un croyant immortel mais superficiel, Miryam... te salue."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6031_AwakerVoiceContent = {
    Text = "C'est mon tour d'agir."
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6032_AwakerVoiceContent = {Text = "Ho !"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "Absolument incroyable... Ta remarque anodine a résolu un problème créatif qui me tourmentait depuis des mois."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6033_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Comparé aux dames nobles lors de la fête du vin, le tempérament de Murphy est tout simplement adorable."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Murphy"
  },
  Voice_6034_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Maître de la Guérison Mentale ? Ces enfants me louent trop. Je fais simplement de mon mieux pour écouter et les aider à libérer leur détresse intérieure — comme je l'ai toujours fait."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Ne me sous-estime pas !"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "Ne me sous-estime pas !"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Vous avez soif ? L'eau propre est un luxe rare dans la prison."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6038_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Bonnes enfants, enfants obéissants~ Vous ne devez pas abandonner à mi-chemin~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6039_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Vous devez être tombé dans mon doux piège, n'est-ce pas ?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6040_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Continue, encore un peu~ Tu es presque au sommet de l'extase~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6041_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "J'ai rejoint l'école à l'âge de 14 ans. Si j'avais obtenu mon diplôme normalement, tu m'appellerais maintenant \"Principal\"."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Votre cerveau faible semble incapable de retenir les leçons."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "Vous demandez quel est mon vœu ? Des voyages sûrs et la paix—cela ne compte-t-il pas ?\nQuant aux autres vœux, je n'y ai pas beaucoup réfléchi... Mais je vais y penser sérieusement et vous le dire plus tard."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6044_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"Ce que je cherche, ce sont les mystères de l'univers. Je veux comprendre quel Pouvoir me contrôle.\" Bien que je ne sois pas satisfait de l'intrigue de ce roman et trouve sa science fictive ridiculement naïve, après l'avoir lu, tu devrais me comprendre... Attends, n'as-tu pas lu ce livre ?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6045_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "La mission et le destin sont similaires. Ils ne peuvent pas être facilement abandonnés, ni est-il nécessaire de le faire."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6046_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Ai-je l'air toujours occupé ? Oui, les assistants peuvent parfois aider, mais dans certaines recherches, je suis irremplaçable. Vous voulez aider ? Alors vérifiez de temps en temps si je suis toujours en vie."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6047_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Vous pensez que je suis en colère ? Savez-vous combien de muscles il faut pour sourire ? J'ai déjà expliqué cela en classe, ce qui a clairement échappé à votre cerveau lisse. La réponse est au moins dix-sept, et je n'ai aucune raison d'être en colère contre vous."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6048_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Mademoiselle Ramona a dit : \"Je n'ai pas besoin de loger tout le monde. Comprenez-vous ce que cela signifie ? ...Cela signifie-t-il que je n'ai plus besoin de sa protection ?\""
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6049_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Treize rapports nécessitent une approbation urgente, six communicateurs endommagés attendent d'être réparés, et je dois également surveiller les résultats de cinq expériences d'extraction d'Argent différentes... Alors, au lieu de perdre mon temps limité à me déranger, pourquoi ne pas essayer d'exercer ta matière grise faible ?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6050_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "J'espère qu'à la prochaine fois, ma patrie répondra à mon appel."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Verrou déverrouillé."
  },
  Voice_6052_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6054_AwakerVoiceContent = {
    Text = "Je suis si heureux... Tu es tellement biaisé et me favorises tant."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6054_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Les autres pourraient se fâcher s'ils pensent que vous montrez du favoritisme."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6055_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "As-tu aussi envie de moi ?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6056_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Enfin, c'est fini. Plus de visions de ces choses noires et visqueuses..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Pour tout ce que tu m'as donné, ton amour est déjà devenu un avec le mien..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6058_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Hé !"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "Alors dangereux."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "Vous avez tellement travaillé ; il est temps de profiter des fruits de votre labeur, n'est-ce pas ? Approchez-vous, je ne vous décevrai pas ~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6061_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "Je... Je comprends ton intention. Bien que je sois encore maladroite, Aigis se battra pour toi de toutes ses forces !"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6062_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Votre regard me brûle... Aigis vous a-t-il causé des ennuis ?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6063_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Aigis est très anxieuse... incertaine de pouvoir répondre à vos attentes..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6064_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Votre regard sur moi rend Aigis mal à l'aise... N'avez-vous pas peur de la malédiction ?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6065_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "P-s'il te plaît, ne regarde pas dans mes yeux... Aigis a peur de te blesser... Après tout, je suis comme un monstre..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6066_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "Le sens de l'odorat de la bête est juste de la chance, d'accord ? Ne vous trompez pas, d'accord ?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6067_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Je ne peux pas encore arrêter..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Puissance, incessante !"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Puissance, toujours en flux."
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "Aimes-tu la mer ? J'aime la mer quoi qu'il arrive. Je me souviens encore de ce jour il y a de nombreuses années où la mer a doucement apporté la mort tant attendue à l'infortuné que j'étais."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Pour une raison quelconque, un plaisir sans précédent a émergé..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Ce courant sous-marin va déchirer les ennemis."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Ce courant sous-marin va déchirer les ennemis."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "J'ai attendu quelqu'un pour m'enseigner le véritable amour, la douleur et le désir. Peux-tu exaucer mon souhait ? Peux-tu me délivrer de cette sombre prison ?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6076_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Veux-tu connaître la vérité ? Je déteste la prison, je déteste l'obscurité, et je la déteste tant que je pourrais mourir. Je veux être remarqué et je veux être enflammé..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6077_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Tout est pour le bien-être éternel de l'avenir."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Tu veux profiter de moi ? Alors deviens mon esclave. Je te ferai fondre de chaleur~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6079_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Considérez-le comme une humble offrande de votre serviteur."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Je m'ennuie tellement, tellement. Comparé à ces grands prisonniers qui tremblent, c'est juste comme jouer à la poupée. Pourquoi ne restes-tu pas avec moi~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6081_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Je désire plus d'esclaves, pour entendre leurs gémissements et leurs supplications—\nApportez-moi plus d'esclaves~ S'il vous plaît~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6082_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Désolé, je me suis perdu dans mes souvenirs encore une fois. S'il te plaît, ne sois pas triste. C'est à ton tour de narrer ton histoire. As-tu envie d'écrire un poème ? Tes aventures, tes expériences, tes joies, tes peines, s'écouleront-elles comme un ruisseau flottant de ton esprit à tes doigts ?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6083_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Je n'étais qu'une éphémère marque d'eau sur du parchemin, pourtant notre rencontre m'a fait persister. Peut-être est-ce un miracle. Je chérirai ce miracle et composerai des poèmes intemporels pour vous."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6084_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Quelqu'un m'a dit un jour que la poésie est écrite pour être appréciée... Puis-je entendre vos pensées à ce sujet ?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6085_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "As-tu déjà vécu cela ? Faire face aux offenses des autres avec un cœur pardonneur, pour n'obtenir en retour le résultat désiré. Tu offres une rose, mais tes mains restent sans parfum, seulement les marques sanglantes des épines aiguës."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6086_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "Mon stylo et mon encre..."
  },
  Voice_6088_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6089_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6090_AwakerVoiceContent = {Text = "Faux..."},
  Voice_6090_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "C'est une bénédiction du Grand Être !"
  },
  Voice_6092_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6093_AwakerVoiceContent = {
    Text = "Bénédiction du Grand Pâle"
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "Je n'ai pas le temps de me reposer. Le D-phénomène a détruit deux de mes corps. Avant que la fin ne me rattrape, il y a beaucoup de choses que je dois comprendre... Aide-moi, en commençant par préparer les matériaux pour l'expérience. Je te fais confiance pour ne pas mal calculer l'équilibre."
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6094_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "J'aime les vitraux de Fontainebleau. Ils projettent différentes teintes sur les visages des gens : le violet désespéré, le bleu flatteur et, bien sûr, mon préféré—le rouge ambitieux..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Ici, je sens souvent la présence de mon Seigneur, mais peut–être ne suis–je pas encore prêt à Le rencontrer... Quoi qu'il en soit, merci de m'offrir un abri."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "La trahison transforme les gens en monstres, peu importe de quel côté ils se trouvent. C'est pourquoi je déteste les traîtres."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, à votre service."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_60986_AwakerVoiceContent = {
    Text = "J'ai une fois rencontré quelqu'un avec une compréhension presque instinctive de la musique. Les concertos et symphonies créés par cette personne étaient inoubliables.\nUn vrai génie."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Discussion décontractée : À propos des vieilles connaissances"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Je n'apprécie pas de passer du temps sur la stratégie. Comparé à la musique, l'art de la stratégie a peu de valeur. Cependant, en tant qu'outil pour surmonter les obstacles, c'est nécessaire. Pour atteindre le sommet de la musique, je ne vois pas de problème à l'utiliser."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Discussion décontractée : Sur la stratégie"
  },
  Voice_60988_AwakerVoiceContent = {Text = "Impoli."},
  Voice_60988_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Voici encore. Qu'est-ce que cette mélodie ? Depuis la dernière fois que je l'ai entendue, elle reste dans mon esprit, refusant de partir ou de se reposer."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_60989_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6098_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_60990_AwakerVoiceContent = {
    Text = "En termes de technique, la planification stratégique et la direction musicale ne sont pas différentes. L'humanité, l'émotion, le désir... ils sont aussi clairs et dociles que des notes sur une portée, exhibées devant mes yeux, dansant le long du chemin de la baguette. Comprendre la musique, c'est comprendre tout."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Discussion décontractée : Sur la communauté"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Presque là, juste un peu plus. Je dois le finir ; je dois l'entendre !"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_60991_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60992_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_60993_AwakerVoiceContent = {Text = "Impoli."},
  Voice_60993_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "La musique transcende la langue, l'écriture et tout. Si ce n'est pas la perfection, je ne sais pas ce que c'est."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_60995_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Faites attention au rythme."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Accord terminé."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Content que tu comprennes l'importance de l'entraînement."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Je fournirai une performance parfaite."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Envieux? Ces écailles dures sont la preuve d'une noble lignée."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "J'étais autrefois loué, mais... ce n'était pas un vrai talent.\nMes œuvres n'étaient que de simples imitations de mes prédécesseurs."
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Discussion informelle : À propos du Travail"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Les bois et les cordes... s'entrelacent vers le haut et vers le bas, le motif réapparaît... Maintenant je me souviens, c'est le requiem que j'ai composé pour le génie décédé prématurément, l'étoile déchue."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_61001_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm ? As-tu une nouvelle pièce à me montrer ?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Cette mélodie est dédiée aux âmes des défunts."
  },
  Voice_61003_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_61004_AwakerVoiceContent = {
    Text = "La danseuse verte possédait une élégance digne d'être la tête d'une troupe de cour.\nSi l'occasion se présentait, j'espère vraiment que nous pourrions collaborer."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Petits bavardages · À propos de Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Liz\""
  },
  Voice_61005_AwakerVoiceContent = {Text = "Arioso !"},
  Voice_61005_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "Il y a un chef d'orchestre dans l'orchestre, mais un chef d'orchestre à lui seul ne peut pas composer un orchestre complet. Mon orchestre n'a pas de place pour ceux qui cherchent uniquement à se montrer."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Je pense que j'ai entendu une mélodie. Quelqu'un répète-t-il à proximité ?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_61007_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_61008_AwakerVoiceContent = {
    Text = "Dal Segno !"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_61009_AwakerVoiceContent = {Text = "Da Capo !"},
  Voice_61009_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "Préparez-vous à rencontrer votre destin !"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Oui, oui, c'est ça—la messe finale, un requiem pour la musique elle-même !"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_61010_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Gardien, tu es arrivé juste à temps. Dis-moi, que penses-tu de ce mouvement ?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Cordes, commencez."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_61013_AwakerVoiceContent = {
    Text = "Melodie Chargée, Melodie Chargée !"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Il est devenu clair, cette mélodie sinueuse, comme les pleurs d'une âme... Je suis sûr de l'avoir entendue quelque part auparavant."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_61014_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "La rationalité et l'ordre ont ouvert la voie. J'ai marché vers le haut et ouvert les portes de la salle. Au-delà, rien ne restait — la musique véritablement éternelle transcende la raison."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Discussion décontractée : Sur la raison et l'ordre"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Regardez mes mains, un, deux, trois."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "J'ai entendu la performance de votre soi-disant orchestre, pleine d'erreurs. Mais pas de souci, j'ai un plan détaillé pour mettre en scène un spectacle parfait avant le Festival de la Gelée d'Argent."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Je ne peux jamais oublier la première fois que j'ai entendu la musique au fond de ma conscience. Dans ces notes et ces accords, le monde réel a disparu ; seule la musique pure et sublime est restée."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "C'est dommage. Il semble que d'autres répétitions soient nécessaires."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "C'est un ordre."
  },
  Voice_6101_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_61020_AwakerVoiceContent = {
    Text = "Je n'étends généralement pas de telles invitations, mais... aimeriez-vous essayer ? Tenez la baguette et insufflez une nouvelle vie à la musique ?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_61020_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Je préfère m'exprimer par la musique plutôt que par des mots. Mais communiquer avec vous ressemble à diriger un orchestre qui a été répété d'innombrables fois—fluide, et souvent agréablement surprenant.\nVous occupez une place spéciale tant pour la musique que pour moi."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_61021_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "Dans une symphonie, la coordination entre les instruments est cruciale ; la façon dont chaque section rejoint et sort apporte une expérience différente à la musique.\nCe que je veux dire, c'est que si commander les Réveilleurs est une performance, vous le faites bien."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_61022_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Aimes-tu ce morceau ? Il présente pleinement le motif en seulement quatre mesures, avec les instruments à vent poussant la mélodie vers le haut jusqu'à ce que le thème soit atteint. Un tel design a influencé d'innombrables successeurs... Désolé, est-ce que je parle trop ?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_61023_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Performance Parfaite."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_61025_AwakerVoiceContent = {Text = "Forte !"},
  Voice_61025_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_61026_AwakerVoiceContent = {Text = "Accent !"},
  Voice_61026_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_61027_AwakerVoiceContent = {
    Text = "Chacun de nous cache une mélodie dans son cœur, piégée par la raison et le corps, ne pouvant être pleinement exprimée que dans la folie."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Seule la musique mérite des éloges."
  },
  Voice_61028_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_61029_AwakerVoiceContent = {
    Text = "Seule la musique mérite des éloges."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Allez."},
  Voice_6102_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "Écoute, c'est le dernier requiem !"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "Supplie pour miséricorde !"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Écoute, c'est le dernier requiem !"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_6104_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6104_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Souhaites-tu aussi être consumé par les flammes vertes ?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Oses-tu perdre ta concentration ?"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6108_AwakerVoiceContent = {
    Text = ": Concentre-toi !"
  },
  Voice_6108_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6109_AwakerVoiceContent = {
    Text = "Comment peut-il y avoir des étudiants aussi adorables à l'université ~ Je lui ai juste demandé, \"Voudrais-tu être mon serviteur ?\" et il a rougi, bafouillant quelque chose sur le fait que \"je suis déjà un chevalier du Gardien\"...\nVisiblement, il n'y a absolument aucun conflit ~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Discussion informelle · À propos d'Ogier"
  },
  Voice_6109_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Ogier\""
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Ne pense même pas à t'approcher de la princesse."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Compétence·Un·Vagues Déchaînées"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Acceptez votre destin."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Compétence·un·Marée Montante"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Les portes de ma patrie s'éloignent... Non... Pas encore..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Écartez-vous !"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "Écartez-vous !"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Payez le prix de vos actions."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Veux-tu mourir ?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Je pense que j'ai été affligé par la Dissolution à nouveau... Mon cœur se dissout ! Juste quelques aspirines, un fouet et un peu de douleur devraient faire l'affaire pour me guérir..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Même vous ne pouvez pas guérir cette maladie spectrale ? Alors pourquoi poursuivre la Dissolution, en risquant votre vie ?"
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Je suis le dernier guerrier romain—Uvhash !"
  },
  Voice_6119_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6120_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6120_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Je suis le dernier guerrier romain—Uvhash !"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Dissolution...? Bien sûr, je sais. Cela signifie simplement que le lien maître-serviteur est rompu, n'est-ce pas ? Qu'est-ce qui est si difficile à ce sujet ?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "J'ai été convoqué ; la frontière entre les dieux et les fous s'est estompée."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6123_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm... La pression est bien équilibrée, et la technique de massage est assez bonne~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "N'est-ce pas la décoration ici qui est trop démodée ? C'est étrange, comme si c'était hanté."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Ici se trouvent des plantes luxuriantes, un air tranquille, et un remède pour la maladie de ma sœur. Pour nous deux, c'est le plus merveilleux nouveau foyer."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Je ne m'attendais pas à te rencontrer ici... Je me demande comment ma sœur va depuis tout ce temps. Peu importe comment je demande, elle dit seulement qu'elle va bien... Désolé, et merci de nous avoir réunis."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Discussion·À propos de l'Évanouissement"
  },
  Voice_6127_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Évanouissement »"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Une offrande à mon Seigneur."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Une offrande à mon Seigneur."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Calme-toi, calme-toi, calme-toi..."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "Il y a beaucoup de \"moi\" à l'intérieur. Heureux, tristes, en colère... Ils aiment le gâteau éponge, détestent les jours de pluie à Londinium. Ils s'appellent tous \"24\" et ils vous adorent tous."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6131_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Je travaillais jusqu'à minuit chaque jour — à filer, laver, nettoyer, garder des enfants, même à fouiller... Je ferais n'importe quoi pour gagner de l'argent. À l'époque, vivre n'était que survivre.\nMaintenant, nous avons de la nourriture fraîche, des lits chauds et des maîtres gentils comme vous... C'est au-delà de mes rêves les plus fous."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6132_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Peu importe quoi, nous partagerons un steak et un lit, et ne te causerons jamais de problèmes."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6133_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Heh, cette femme a tellement peur que je sorte qu'elle n'ose même pas dormir la nuit. Détends-toi, je ne te tuerai pas—pas quand tu me fais des cadeaux.\nQui suis-je ? Bien sûr, je suis \"24\", hahaha !"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6134_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Je me sens fantastique en ce moment. Quoi ? Vous dites que mon esprit a été pris par autre chose ? N-non... euh..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6135_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "En tant que sujet, vous êtes assez perceptif. Avant mon prochain long sommeil, je vais embellir ce moment de ma présence."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm, la mer est assez chaude ce soir..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "L'oiseau blanc tournoyant dans le rêve est arrivé."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Comme vous le souhaitez, ma présence est devenue plus tangible."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "Tellement satisfaisant, tellement satisfaisant!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6141_AwakerVoiceContent = {Text = "Doux !"},
  Voice_6141_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "Laisse-le à moi !"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Laisse-le à moi !"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "Bienvenue à — notre festin !"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Exalter · Mania"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Cette fille porte sans aucun doute le sang de Yu... Non, Yu n'est pas assez vieux pour avoir des enfants. Cependant, son pouvoir est en effet semblable à celui de Yu."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Conversation Inactive · Concernant la Lignée Divine"
  },
  Voice_6145_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Aigis\" ou \"Murphy\""
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "La bonté du Maître, Karen n'ose pas l'oublier même un instant !"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—Si sucré et délicieux !"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Karen est au régime et ne peut pas manger trop de choses~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Ces gars ne méritent pas d'être mes adversaires."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Expliquer l'art est aussi ridicule qu'expliquer les actions ferroviaires—s'il vous plaît, ne compliquons pas la vie des pauvres artistes."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... Ai-je fait quelque chose de mal ?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Vos prières ont été entendues."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Vos prières ont été entendues."
  },
  Voice_6153_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6154_AwakerVoiceContent = {
    Text = "Hmph, irrespectueux."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, était-ce le Maître tout à l'heure ? Non, peu importe. La dernière fois que je l'ai salué, il ne m'a pas reconnu... Je l'ai attendu en prison, espérant qu'il m'emmènerait, mais il n'est jamais venu, même pendant l'émeute."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Bavardage · À propos de \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Débloqué après avoir complété le Chapitre 7 de \"Opération d'Investigation\""
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Répondre à l'Éveil de l'humanité et former des alliances est pour accomplir mon devoir inachevé—si vous pouvez devenir assez fort pour me défier, ce serait idéal."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Soeur, Marron, la lâche de l'orphelinat, je suis content d'avoir juste eux comme amis. Euh... eh bien, je suppose que tu comptes aussi. Marron, partage un morceau de bonbon avec le Gardien.  \n\"Peep ?!\""
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6157_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "Le Bidonville de l'Est n'est pas un endroit pour les enfants. Des contremaîtres sournois trouveraient des moyens de réduire le salaire des livreurs de journaux et critiqueraient les garçons livreurs de lait pour leur rapidité... parfaitement ridicule ! Pour survivre dans les rues, on ne peut compter que sur soi-même. Personne d'autre n'est digne de confiance."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6158_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Mes \"mauvaises habitudes\" ne peuvent pas changer du jour au lendemain, tu comprends, n'est-ce pas ? Dormir sous des ponts et dans des égouts pluviaux, survivre avec des ordures - juste rester en vie était déjà assez difficile... Tu ne peux pas attendre de moi que je commence à faire mon lit immédiatement ! Cela prendra au moins un mois et demi pour s'y habituer !"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6159_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "Perdre dans l'espace ne fait pas de bien. Puisque tu m'as tiré de là, n'hésite pas à demander quoi que ce soit, mais je ne peux pas garantir que je pourrai aider.\nEn tenant compte de mon âge, tu ne vas pas déranger un enfant, n'est-ce pas ?~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6160_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Hé, Westsider ! As-tu vu Brown ? Ce glouton a dû renifler quelque chose encore."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6161_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"Ceux qui ont de la force ne doivent pas utiliser leur pouvoir pour opprimer les autres, car vous partagez tous mon sang.\" — Je me souviens des enseignements du Dieu de la Compassion et j'utiliserai cette force pour protéger ceux qui m'entourent."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6162_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Vous vous demandez ce que j'ai vu au début de l'univers ? Je peux vous dire qu'il n'y avait rien là-bas."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6163_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "C'est plus lumineux maintenant."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "La lampe éternelle..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "Le lien avec la patrie est devenu plus fort."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Si je peux libérer le monde de ses souffrances, je serai satisfait."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Donnez-moi plus de commandes, Messager Pâle. Que votre flamme éclaire mon chemin."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "La forge d'une personne implique non seulement le corps, mais aussi le cœur."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6171_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6171_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6172_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6173_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6173_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6174_AwakerVoiceContent = {
    Text = "Hmm ! Ta température est un peu haute pour un corail. Mais... c'est chaud et intense. J'aime ça."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Ah... Avez-vous besoin de quelque chose ? Si possible, parlons en coulisses..."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Flétrissant avant de fleurir, comme un lotus imbibé d'eau... Cherchant la paix dans les froides marées en colère, trop timide pour poursuivre mon propre bonheur... Voilà moi, le Gardien."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6176_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Je me suis une fois débattu avec ce dilemme : la douleur est-elle plus longue que la vie elle-même ? Si c'est le cas, un sommeil paisible est-il plus heureux qu'une veille tourmentée ? Après mon réveil, j'étais moi aussi piégé, jusqu'à ce que tu m'apportes ce refuge..."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6177_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Pendant mon temps au sanatorium, j'ai essayé de me faire des amis, mais les gens hésitaient à s'approcher de moi... Est-ce à cause de ce « poison » qui ronge les os ? Quoi qu'il en soit, fais attention quand tu t'approches de moi."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6178_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "Le son de la cloche porté par le vent nocturne apporte la paix. Souhaitez-vous vous asseoir sur la pierre et écouter un moment ? Je vais préparer une place pour vous avec une écharpe."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6179_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "As-tu entendu parler de \"l'inhumation en mer\" ? Dans la ville où je vivais avant, il y avait une coutume de plonger les défunts dans la mer, faisant de l'océan le dernier lieu de repos de tous. Quant à moi, je suis retourné dans les bras de la mer trop tôt..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6180_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hmph !"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6182_AwakerVoiceContent = {Text = "Ah !"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Ah !"},
  Voice_6183_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6184_AwakerVoiceContent = {Text = "Ah !"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "Le journal de combat a été archivé. Merci pour votre travail acharné, Gardien."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(Gémissement de douleur)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(Gémissement de douleur)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(Gémissement de douleur)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Vous pouvez continuer."
  },
  Voice_6189_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6190_AwakerVoiceContent = {
    Text = "Les visiteurs du salon reçoivent l'hospitalité la plus raffinée... En guise de billet d'entrée, les invités ont-ils préparé des secrets dignes de ce grand festin ?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6191_AwakerVoiceContent = {
    Text = "J'aime les choses nouvelles. Au cours de mes millénaires de voyages, j'ai été témoin de nombreuses innovations et inventions fascinantes, telles que les formes poétiques et les scènes cinématographiques. Les humains sont de véritables créatures intrigantes."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Hmm, Lily la reconnaît. Quand sa mère n'est pas là, Lily reste chez elle."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos des Jonquilles"
  },
  Voice_6192_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jonquille\""
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Es-tu celui qui perturbe mon long sommeil ?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6196_AwakerVoiceContent = {
    Text = "Des dieux ? Seuls les idiots confieraient leur vie à de tels êtres intangibles. Au lieu de compter sur des soi-disant dieux, réfléchissez davantage à la manière de devenir plus fort."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Quel maître des gladiateurs, juste un insecte sans valeur."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Agrippa\""
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Après la victoire, permettez-moi de prendre les matériaux nécessaires à la reproduction."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Grand ami ! Partenaire ! Hoo-hoo, soyons les meilleurs amis pour toujours avec Aurita !"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Je suis ravi en ce moment... Si tu ne veux pas mourir, tu ferais mieux de garder tes distances avec moi."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "Est-il vraiment acceptable que cette personne traite les autres de cette façon ? Mme Sarah a dit que les enfants ne devraient pas faire des caprices..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Murphy"
  },
  Voice_6201_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_6202_AwakerVoiceContent = {
    Text = ": La gloire de la victoire vous appartient"
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "Je ne peux plus manger, c'est plein~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "Le vide à l'intérieur a été rempli~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Un peu plus brûlant~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Je connais cette petite fille. Elle se tient parfois au loin, regardant la performance. Mieux vaut qu'elle ne s'approche pas, sinon ces petits spectateurs seront \"épuisés mentalement et physiquement\" !"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Discussion·À propos de l'Évanouissement"
  },
  Voice_6206_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Évanouissement »"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Teinture a dit : \"Rendre la gentillesse.\" Donc, tant que c'est dans ma capacité d'aider, je prêterai main-forte..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Bonjour, Gardien. Comment puis-je vous aider ?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Un jour, je retournerai sur le champ de bataille en tant que leader à l'avant."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6209_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Peux-tu le croire ? Je sens mon os de jambe cassé guérir."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6210_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Merci sincèrement pour votre confiance en me formant à ce niveau. Vous devez aussi être une personne qui poursuit la justice, donc je continuerai à apporter de la gloire à notre armée ici."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6211_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "Le jour du voyage approche, et mon sang bouillonne de passion."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6212_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "L'honneur d'être un guerrier est en train d'être restauré."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6213_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6214_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6214_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6215_AwakerVoiceContent = {Text = "Aïe !"},
  Voice_6215_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6216_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6216_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6217_AwakerVoiceContent = {Text = "Tricheur !"},
  Voice_6217_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "Oups, désolé ! Je ferai en sorte que cela se réalise la prochaine fois !"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "J'entends quelqu'un appeler mon nom, Agrippa, Agrippa, Agrippina..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6219_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Je l'ai vu... Il grimpait depuis l'obscurité du puits, d'innombrables yeux apparaissant sur son œuf de chair. Ils me regardaient, m'appelant... Dieu Labyrinthe."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6220_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "J'ai une très forte envie de regarder un duel... Ce serait encore mieux s'il se déroulait dans un labyrinthe."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6221_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Contrat... Oui, je veux signer un contrat avec toi, un contrat maître-serviteur éternel..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6222_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hmph... Pas mal. Donne-moi plus. J'ai besoin de nourrir ces petites araignées."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6223_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Quel saleté, quelle abomination ! Ah—arrêtez ! S'il vous plaît ! Ne me faites pas le voir, et ne le mentionnez pas près de moi..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Mon passé était routinier et calme, comme les mers près de l'équateur, rien de remarquable."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6225_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hmm...? Mère, un câlin... Mm, si chaud..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Poussière d'étoiles..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Oh non, es-tu perdu ?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6229_AwakerVoiceContent = {Text = "Inutile."},
  Voice_6229_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6230_AwakerVoiceContent = {
    Text = "Chaque fois que je me rappelle ces traîtres à genoux et pleurant pour la miséricorde, je ressens une vague de satisfaction, et les flammes dans mon cœur semblent s'apaiser."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "Le maître de navire m'a emmené de chez moi et m'a confié la mission de la première sortie du navire. Depuis lors, le sens de ma vie est devenu hors de mon contrôle. Quelqu'un m'a dit que, du moins dans cette seconde vie en tant que Réveiller, je devrais vivre pour mes propres désirs... Allez-vous m'aider ? Aidez-moi à être égoïste, aidez-moi à trouver mon souhait."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6231_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Agrippa. Je n'ai rien à te dire—à moins que tu ne sois assez fou pour te porter volontaire en tant que mon gladiateur."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... bien plus dangereuse que nous l'imaginions. Si je ne suis pas là, tu dois être extrêmement prudent avec elle."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Tawil"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Avec ce raisonnement... interprétez le monde !"
  },
  Voice_6235_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6236_AwakerVoiceContent = {
    Text = "Avec ce raisonnement... interprétez le monde !"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "Brillez de tout votre éclat !"
  },
  Voice_6237_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6238_AwakerVoiceContent = {
    Text = "Au mieux de mes capacités."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "Au mieux de mes capacités."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Laissez-le se décomposer."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Laissez-le se décomposer."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Les sourires et l'étiquette servent d'armure, m'aidant à maintenir une distance avec les autres et à éviter les perturbations ennuyeuses. Quant à mon vrai moi... je n'ai rien contre le fait de te le montrer."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6242_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Les pensées s'accumulent comme du calcaire blanc et sont lavées dans de magnifiques coraux. Elles se fusionnent avec moi, pulsant avec mon battement de cœur... Voulez-vous écouter ?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6243_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "L'inspiration est comme des bulles remontant à la surface de la mer : une douce caresse, et elles s'évanouissent. Êtes-vous pareil ?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6244_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "La guerre, le pillage et la gloire sont tous des désirs humains. Le humble sculpteur n'a aucun intérêt pour ce que les humains poursuivent ; elle souhaite seulement être esclave de la beauté."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6245_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Une vie merveilleuse réside dans l'indulgence. Parfois, vous ne devriez pas être trop dur avec vous-même."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6246_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Juste des blessures mineures..."
  },
  Voice_6247_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6249_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6249_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6250_AwakerVoiceContent = {Text = "Merde !"},
  Voice_6250_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6251_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6251_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "Le D-phénomène apporte le chaos et les désastres. Peut-être que mon pays a sombré dans l'Aequor à cause de cela..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Ha !"},
  Voice_6253_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6254_AwakerVoiceContent = {Text = "Ah~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Majesté du géant"
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "Essaie ceci !"
  },
  Voice_6256_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "Sacrifice inévitable"
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "Pas mal, c'est la gloire du guerrier."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Toi ! Comment as-tu pu laisser cette femme ici ? Établis une zone restreinte pour moi ! Ne la laisse pas s'approcher de 50 pas de moi !"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Chat·À propos de Miryam"
  },
  Voice_6259_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Miryam »"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "Pourquoi ai-je envie de devenir plus fort ? Dans ma tribu, les faibles se voient dépouillés de leurs vêtements, rasés et soumis aux humiliations les plus dégradantes — le coût de la faiblesse n'est pas quelque chose que tout le monde peut endurer."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6260_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Déesse de la fortune, accorde-moi ta bénédiction !"
  },
  Voice_6261_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6262_AwakerVoiceContent = {
    Text = "Comme on pouvait s’y attendre... La force humaine a-t-elle des limites... ?"
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Les muscles et les os se sont légèrement détendus."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6263_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "Est-ce la manifestation de votre désir, de renforcer mon affection ?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6264_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "Allez-y à fond !"
  },
  Voice_6265_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6266_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6267_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6267_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6268_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, impardonnable..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "Endroit imprudent !"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6272_AwakerVoiceContent = {Text = "Bang !"},
  Voice_6272_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6273_AwakerVoiceContent = {
    Text = "Continue comme ça ! Tes notes finales sont prometteuses."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "J'ai entendu qu'un voleur des bidonvilles est apparu, amenant avec lui un gros rat ? Hehehe... Regardez-moi éliminer ce fléau pour mon maître !"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_6274_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Allez, prends une profonde respiration—"
  },
  Voice_6275_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6276_AwakerVoiceContent = {
    Text = "Intéressant, ta progression au combat dépasse de loin mes attentes. Avec le temps, tu pourrais devenir le prochain... Étrange... À travers le temps, je trouve encore de l'espoir dans un être aussi faible que toi."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6276_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Peut-être qu'il est temps de dire cela. Écoutez attentivement.\nLotan, la Bête des Étoiles, vous défie officiellement... Mais ne vous inquiétez pas, je veillerai à votre sécurité jusqu'à ce que vous atteigniez votre apogée. Je ne laisserai pas mon adversaire choisi rencontrer le même destin à nouveau."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6277_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hmph... Je ne comprends pas pourquoi Ramona t'approuverait comme partenaire. J'admets, tu portes l'odeur de la force, mais tu es encore loin d'être mon rival."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6278_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Oui, regardez-moi avec révérence. Je suis la plus ancienne Relique de la Planète, méritant le respect des insignifiants—j'ai gardé cette Planète pendant des éons. Demander une bataille palpitante en récompense n'est pas trop, n'est-ce pas ?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6279_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Ha, je n'ai pas l'énergie pour jouer à la maison avec des gamins. Si tu sais ce qui est bon pour toi, trouve juste un coin et reste tranquille."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6280_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Âmes sans protection, je vous accorderai la paix éternelle"
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Alerte."},
  Voice_6282_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6283_AwakerVoiceContent = {Text = "Alerte."},
  Voice_6283_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Quelque chose hurle... dans mon esprit."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6284_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "On dirait qu'un voile de brume blanche obscurcit mes pensées."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6285_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "Le son s'intensifie, et la brume blanche s'épaissit."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6286_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Est-ce le son des aiguilles de l'horloge qui bouge ?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6287_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Lorsque la cloche sonne, serai-je encore ici ?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6288_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Un tel tour maladroit... Hmph, pauvre naïf. Comment as-tu pu penser que tu pourrais me lier si facilement ?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Excusez-moi... Avez-vous vu ma sœur, Jenkin ? C'est une fille qui porte une souris et peut être assez féroce... Je ne pourrais pas me tromper sur elle."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_6290_UnlockDesc = {
    Text = "Débloqué après avoir terminé \"Opération Investigation\" Chapitre 2"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Merci pour votre gentillesse."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6293_AwakerVoiceContent = {Text = "Prêt."},
  Voice_6293_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Veuillez vous en réjouir."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Chanter pour toi."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "Nouveau Gardien ? Donne tout et montre-moi si tu es digne d'être mon adversaire."
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Bien que je sois pacifiste, \"eux\" pensent clairement autrement..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha !"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6299_AwakerVoiceContent = {Text = "Reculez !"},
  Voice_6299_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "Comment oses-tu me humilier ainsi..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Es-tu prêt ? Le spectacle de magie de Casiah va commencer ! Ne détourne pas le regard, ne manque pas les moments forts. C'est l'heure du spectacle !"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6302_AwakerVoiceContent = {
    Text = "Tekeli—Li !"
  },
  Voice_6302_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6303_AwakerVoiceContent = {Text = "Ha !"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "J'ai obtenu ton emploi du temps de la part de Sylvia, c'est trop sévère pour un nouveau. Je comprends que vous faites ce qu'il faut, mais faire porter un fardeau lourd aux recrues pourrait causer des problèmes inutiles pour l'équipe. \n Tu dis que tu n'es pas un recrue ? Non, je vois dans tes yeux que tu n'as pas encore vécu beaucoup de choses."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6304_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Je méprise mes propres échecs... Ah ! Pas besoin de me réconforter ! Ces expériences passées sont devenues la force motrice de ma croissance. Ne suis-je pas déjà devenu votre soutien ?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Je ne m'entends tout simplement pas avec cet homme. La vie ne se résume pas à des péchés et des punitions, n'est-ce pas ? N'est-ce pas plus important de profiter du moment ?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos de Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Salvador\""
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Le temps est compté, avançons."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Je déteste les bougies qui s'éteignent facilement, le pain noir et les fils lâches sur les jupes... Pas de raison, je les déteste simplement. N'est-ce pas naturel ?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Puisque tu m'as couronné comme la Sainte Vierge, tu devras te soumettre !"
  },
  Voice_6309_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6310_AwakerVoiceContent = {
    Text = "Puisque tu m'as couronné comme la Sainte Vierge, tu devras te soumettre !"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6311_AwakerVoiceContent = {Text = "Chante."},
  Voice_6311_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "\"La Garde-Robe de la Dame\" et \"Le Guide de la Femme Active\" sont tous deux d'excellentes lectures... Même si vous ne pouvez pas vous les permettre, admirer simplement les belles robes est assez agréable."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "C'est étrange. J'ai généralement du mal à me souvenir des choses, mais je t'ai mémorisé en quelques jours seulement... Quoi ? Cela fait déjà trois mois ? Je suis désolé, j'ai oublié encore une fois."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Savoure cela."
  },
  Voice_6314_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6316_AwakerVoiceContent = {
    Text = "Continue à améliorer ta maîtrise."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Pratiquez le Tourbillon du Fouet vingt fois de plus."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Mes mouvements sont-ils assez précis ?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Veuillez continuer !"
  },
  Voice_6319_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6320_AwakerVoiceContent = {
    Text = "Dépêche-toi, prends Brown et pars !"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Genou devant le trône."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Genou devant le trône."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "Les diverses expressions des humains face au désir ne cessent de m'étonner. Malheureusement, les humains sont encore trop fragiles, trop insignifiants... Cela seul me fait sentir comme si un chat grattait mon cœur."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "De ses souvenirs, j'ai vu de nombreux événements passés liés à \"Dissolution\"... Mais chaque fois que je voulais te le raconter, ma conscience se rompait. J'ai peur que ce soit aussi son œuvre."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Ne serait-il pas agréable de simplement disparaître dans l'oubli ?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Un serviteur qualifié doit être frêle et vide d'esprit—j'aime les agneaux obéissants."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Notre rencontre doit être une promesse des dieux à ceux qui souffrent — vous êtes la pâle flamme qui dissipe le fléau, et je serai votre bras, restant à vos côtés."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6328_AwakerVoiceContent = {
    Text = "C'est assez !"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "Avez-vous essayé d'injecter directement le D-Slime dans votre corps ? La boue noire s'enroule autour de votre cœur comme un viper, et puis... boum ! Votre corps explose en une chaude mare de slime. Dégoutant, mais efficace."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hmph, un refuge pour les faibles à se regrouper."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "De temps en temps, la fille à moto m'aide à entretenir ma prothèse. Cependant, récemment, la fréquence des contrôles d'entretien n'a-t-elle pas été un peu trop élevée ?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Chat·À propos de Nautila"
  },
  Voice_6331_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Nautila »"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Notre relation ? Tu as vraiment besoin de demander ? C'est exactement ce que tu imagines !"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Ce n'est pas mon genre préféré, mais si tu insistes."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Vos cernes s'aggravent... Pourquoi travailler si dur ? Vous devriez être plus comme moi et apprendre à profiter de votre temps libre."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6334_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Attends, sans ma permission..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6335_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Bien... Ça se rapproche de sa forme originale."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6336_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "C'est le pouvoir de contrer la \"Corruption Verte\"... Tu as touché quelque chose que tu n'aurais pas dû. Quant à moi, je ne te laisserai plus jamais partir."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6337_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Chut... La lueur du matin dans la vallée—c'est sûrement la première fois que tu le vois, n'est-ce pas ? C'est ta récompense pour ta loyauté."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6338_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Ce livre, \"La Révélation @1@2\", t'est offert. Il aide à illuminer l'esprit ou à s'endormir rapidement"
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6339_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "Le monde mortel est encore trop bruyant. Si vous pouvez me trouver un coin tranquille dans l'académie, ce serait parfait... Non, je n'ai pas besoin d'une cheminée. Ce n'est qu'à travers des pratiques ascétiques que les dieux peuvent entendre mes prières..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "Est-ce de la cire ou du miel qui coule de mon corps ? Pourquoi ne pas y goûter et voir par vous-même ?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6341_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "Bonjour... Enchanté de vous rencontrer. Je m'appelle Aigis... S'il vous plaît, faites comme si je n'existais pas !"
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6343_AwakerVoiceContent = {
    Text = "Tant que je suis encore \"Ramona\", nous sommes toujours partenaires, n'est-ce pas ?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Cette dame avec de lourdes cernes m'a un jour consulté au sujet de « vivre éternellement au soleil »... Elle n'avait qu'à migrer entre deux Dimensions. Pourtant, elle refuse de mettre le pied dans le Tunnel Dimensionnel. C'était vraiment un casse–tête."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Discussion·À propos du Bigorneau"
  },
  Voice_6344_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Bigorneau »"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Bienvenue dans mon paradis ! Es-tu prêt à affronter le fouet ?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Puisqu'il vous a reconnu, je ne vous considérerai pas comme un ennemi."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "Que voulez-vous dire, \"je l'ai pris\"? Ne m'accusez pas à tort ! Quand ses vis ont disparu, j'étais—Brown, arrête ! ... Hehe, fais juste comme si tu n'avais rien vu, d'accord?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Chat·À propos de Nautila"
  },
  Voice_6347_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Nautila »"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "L'aventure est tout aussi excitante que dans les histoires ! Quelle était cette histoire... ?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...Hic. Ah, désolé, j'ai encore absorbé trop d'énergie par accident."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Une fois à l'intérieur d'un corps humain, j'ai perdu tout contact avec ma lignée. J'ai peur que les autres n'aient pas échappé aux démons et que je sois peut-être le dernier de ma sorte... S'il te plaît, Gardien, sauve-moi. Permets-moi de rester à tes côtés, ne me laisse pas à l'obscurité."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6350_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Lorsque la planète a été détruite, j'ai abandonné mon corps et transféré ma conscience dans un corps humain... Mais le démon noir m'a poursuivi sans relâche, liant mon esprit et empêchant mon évasion ! Il cherche à entraîner le monde dans un abîme de ténèbres !"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6351_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "S'il vous plaît, Gardien... Tant que vous me laissez reste sur le localisateur et ne partez pas, je ferai tout sauf entrer dans l'obscurité et faire face à ce... ce truc noir ! Je ne peux pas quitter le localisateur. Encore un peu, et je localiserai les restes de la planète d'origine ! Il reste seulement 1,2 milliard de calculs !"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6352_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Pourrais-tu utiliser ta part de fournitures pour me procurer deux sacs de suppléments de caféine ? ... Je ne peux pas dormir. Pourquoi devrais-je dormir ? Ne dors jamais ! Une fois que tu fermes les yeux, tout devient obscurité... obscurité..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6353_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Wow ! Reste loin de moi ! D'abord, prouve que tu n'es pas un serviteur des ténèbres ! Ouais, serviteur. Enlève juste tes vêtements et montre-moi que tu n'as pas ce dégoûtant slime noir sur ton corps, et alors je saurai que tu n'es pas maléfique..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6354_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Ne demande pas, ne demande pas... ! Tu sais exactement ce que je crains et déteste le plus ! L'obscurité, l'obscurité sans fin !"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Une méthode pour guérir la Dissolution ? Une telle chose n'existe nulle part.\nTu demandes comment je reste non infecté ? Hehe... tant que tu \"n'es pas vu\", c'est tout ce qu'il faut."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Merci, Maître."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Ils sont aussi heureux."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily a grandi."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "L'écraser ?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Comment pourrais-tu l'invoquer ! Cet inutilisé endormi ! Paresseux et sans ambition... C'était autrefois quelqu'un que j'avais de grands espoirs pour ! Allons-y ! Je ne veux pas voir ce gars !"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Chit-Chat · À propos de Tulu"
  },
  Voice_6361_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "Dégoûtant !"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "Alors tellement énervant !"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "Next time, let's go see the sea together. Febvre est bien, je peux être ton guide ; ou ailleurs, même aux confins de la terre, je veux aller avec toi."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6364_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "La mer a son propre langage.\n...Comme ça, je peux occasionnellement discuter avec les petits poissons du étang de notre ville natale. Si tu es curieux, je peux t'aider à traduire."
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6365_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Être sauvé par toi me rend souvent si heureux que cela me fait peur... S'il te plaît, dis-moi que ce n'est pas un rêve, et que tu ne disparaîtras pas sans un trace dans la mer, n'est-ce pas ?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6366_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Ce sentiment peut-il être appelé \"bonheur\" ? Je... n'ai jamais osé espérer cela auparavant."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6367_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Mon corps se sent chaud, comme s'il était doucement enveloppé par la mer. C'est vraiment incroyable."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6368_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Est-ce un fragment de Lui ? Impressionnant, il possède vraiment une aura royale."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Chit-Chat · À propos de Tulu"
  },
  Voice_6369_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "Ne le faites pas, ne continuez pas... Il me trouvera, il me trouvera !"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Cela devrait me tenir éveillé."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "C'est fini, c'est fini, c'est fini... Ils vont certainement le découvrir..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Nous avons gagné. Es-tu heureux ? Qu'est-ce que ça fait d'être \"heureux\" ?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Des choses que j'aime ? J'aime les berceuses de Tinct... Bien sûr, ton chant est merveilleux aussi !"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "C'est un guerrier fiable. Je le considérais autrefois comme un \"camarade\"... Quoi ? Vous croyez que ma définition de \"camarade\" est incorrecte ? S'il vous plaît, éclairez-moi."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Chat · À propos de Goliath"
  },
  Voice_6375_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Goliath\""
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "Météore..."
  },
  Voice_6378_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6379_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Une montée continue de pouvoir, remplissant tout le corps..."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6381_AwakerVoiceContent = {Text = ": Vole!"},
  Voice_6381_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "Pas mal, vous êtes plus utile que vous ne le semblez."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Vingt, vingt et un, vingt-quatre... Attends, quel numéro étais-je ? Un, deux, trois..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6383_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "J'ai enfin compris combien de matériaux j'avais avant, je peux donc terminer les réparations plus rapidement—Attends, d'où viennent ceux-ci ?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6384_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Grâce à votre aide, l'efficacité des réparations récentes s'est améliorée. Nous serons bientôt prêts à partir à l'aventure !"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6385_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Je commence à me souvenir des choses... M'as-tu tendu une clé à molette n°7 hier ?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6386_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Réparez, retouchez, complétez ! Une aventure inconnue, un monde mystérieux, j'arrive !"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6387_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boum—"},
  Voice_6388_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6389_AwakerVoiceContent = {
    Text = "Ne te trompe pas. Les chaînes mentales sont toujours des chaînes et ne peuvent pas être considérées comme justes."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Maintenant, la ligne entre moi et le Réveilleur est encore plus floue. Vous feriez mieux de garder un œil sur moi."
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6390_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Allons-y et sauvons le monde."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6391_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "Il est aussi rafraîchissant que de lire \"De l'origine des espèces\" d'un seul coup"
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6392_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Je suis devenu plus fort. Laisse-moi essayer de gérer la prochaine mission tout seul, d'accord ?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6393_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "En plus de mes capacités de combat, ma mémoire et ma pensée logique n'ont pas beaucoup progressé. Je dois encore compter sur mes propres pensées."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6394_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Je veux qu'ils éprouvent ce que c'est que de voir leur vie chamboulée, de tout perdre et d'être piétinés par tout le monde."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6395_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "L'humiliation que j'ai endurée, tout ce que j'ai perdu... Je les ferai payer. Je les ferai tous payer."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6396_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Une telle douce haine, lorsqu'elle est assaisonnée du sang des ennemis, est sûrement le plat le plus exquis du monde."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6397_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Ah ! Ne me surprends pas par derrière !"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Les flammes brûlantes consument ma poitrine... Oui, je n'ai jamais oublié, ni ne pourrai jamais oublier."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6399_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Brûle, ô âme de poésie."
  },
  Voice_6400_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6401_AwakerVoiceContent = {Text = "（Hmph）"},
  Voice_6401_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6402_AwakerVoiceContent = {Text = "（Hmph）"},
  Voice_6402_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6403_AwakerVoiceContent = {Text = "（Hmph）"},
  Voice_6403_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6404_AwakerVoiceContent = {Text = "（Hmph）"},
  Voice_6404_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "Ça chatouille ! Tout comme quand la femme de ménage utilise une plume pour chatouiller les plantes de mes pieds. Tu *bip* ne l'as pas fait exprès, n'est-ce pas ?"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6405_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Que vous ayez de doux rêves."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Que vous ayez de doux rêves."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Accorder la sérénité...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Déplacez-vous avec élégance."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "Peux-tu m'entendre ? Ma voix."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Peux-tu m'entendre ? Ma voix."
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Ça pleut. La pluie lave tout : la nourriture gâtée, la saleté tenace et les gens comme moi... ceux qui sont de trop."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "La marée de vengeance enragée ne cesse jamais."
  },
  Voice_6413_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6414_AwakerVoiceContent = {
    Text = "Sang, baigne tout mon corps!"
  },
  Voice_6414_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6415_AwakerVoiceContent = {Text = "Ah !"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "Regarde par ici !"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "Je n'ai pas peur."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6418_AwakerVoiceContent = {
    Text = "Attention !"
  },
  Voice_6418_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Un monde non touché par la douleur, non souillé par le deuil, libre de toute souffrance et sans souffrance noire—peut-être une illusion inaccessibile, mais c'est l'idéal que j'ai poursuivi toute ma vie."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Regarde la magnificence du Royaume Éternel !"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "Regarde la magnificence du Royaume Éternel !"
  },
  Voice_6421_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6422_AwakerVoiceContent = {
    Text = "Offrir des tributs obéissants encore une fois ? Bon garçon."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6422_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Est-ce que ça fait mal ?"
  },
  Voice_6423_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6424_AwakerVoiceContent = {
    Text = "Restez concentré."
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "Le passage des millénaires m'a rendu quelque peu imprudent."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "Ce jour-là, les flammes de la jalousie se sont répandues comme une mer de roses écarlates en pleine floraison... Tous les poèmes se sont transformés en cendres brisées au milieu des langues de feu cramoisi."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6426_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Nouvelle technique apprise !"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Faites attention."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "La baguette veut danser !"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ah, ce sentiment familier de vide!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "Le mouvement des articulations est devenu plus fluide."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Ce noir ominueux ressemble à mon épée-bouclier amorphe... Ah ! Rassurez-vous, mon seigneur, mon épée gardienne ne vous fera jamais de mal !"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6433_AwakerVoiceContent = {Text = "Allez."},
  Voice_6433_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "On a à peine réussi."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Je ferai de mon mieux."
  },
  Voice_6435_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6436_AwakerVoiceContent = {
    Text = "Jouez ici aujourd'hui ?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "Le sous-sol est rempli d'eau, douce et froide. Ainsi, mon corps est toujours enveloppé d'humidité... Comme si j'étais le seul être physique entre ciel et terre. Parfois, je souhaite vraiment me dissoudre dans l'eau.\nMais alors je cesserais d'exister et ne te rencontrerais jamais."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6437_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Voici un secret... Je déteste en fait le sang. Je déteste sa couleur, son goût. Mais je ne peux pas vivre sans lui.\n...Je déglutis le sang, puis je le vomis tout... Je me dégoûte."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6438_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Hmm ! Ton sang... a un goût de hydromel. Je suppose que je suis le seul à connaître ce secret, n'est-ce pas ?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6439_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "Dans mes fantasmes, un chevalier vaillant me tire hors des ténèbres puis me lie avec des chaînes. Il peut me frapper, me maudire, faire n'importe quoi avec moi—la douleur est ma preuve de vie.\nSerais-tu prêt à être mon chevalier ?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6440_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Le sang coule comme une rivière. Je suis à toi—je n'ai jamais ressenti une telle intensité."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6441_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "C'est la volonté des Trois Déesse de la Vengeance !"
  },
  Voice_6442_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6443_AwakerVoiceContent = {
    Text = "Lames dégainées"
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6444_AwakerVoiceContent = {Text = "Non !"},
  Voice_6444_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "Si sale ! Si sale !"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...Aigis, je le vois !"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...Aigis, je le vois !"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Des pourboires, bien sûr, des pourboires. Regardez ces serveurs perdus dans la cafétéria de l'école ! Ils ne préparent même pas les chaises longues à l'avance, et ils s'attendent toujours à être payés en plus ? Rêvez !"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6449_AwakerVoiceContent = {Text = "Noir."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Laisse-moi sortir !"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Compétence·I·Manie"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Ne fais pas ça..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Compétence·Un·Dépression"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Pas besoin de courtoisie, Messager Pâle. Il ne devrait y avoir aucune barrière entre nous, car nous sommes tous des Reliques de Dieu, marchant ensemble sur ce chemin boueux et éprouvant."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6452_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Bien sûr, je n'ai pas peur d'eux, ces pauvres âmes tourmentées par la Malédiction de Fusion. Je ressens seulement de la tristesse pour eux. Je sais que je ne peux pas supporter leur souffrance, mais je peux leur donner tout ce que j'ai si cela leur apporte un peu de réconfort."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6453_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Vas-tu prier avec moi, Le Feu Pâle ? Prie pour ceux qui sont morts dans notre bataille aujourd'hui. Bien que maudits par la dissolution et la folie, ils sont toujours des reliques du dieu de la bonté, nos frères et sœurs. Puissent-ils trouver la paix qu'ils méritent."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6454_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Même si la flamme rouge me rend mal à l'aise, je remonterais sur la plateforme enflammée pour toi une fois de plus. Ne t'y attarde pas, ma flamme pâle. Mon sacrifice est insignifiant par rapport aux bénédictions que tu apportes."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6455_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Regret? Non, bien sûr que non. Ma mort a apaisé leur souffrance et a acheté plus de temps—c'est suffisant. Mais... tu as été honnête avec moi, alors je ne le cacherai pas : le bûcher ce jour-là a laissé des cicatrices dans mon cœur."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6456_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Peux-tu faire une promesse avec moi ? Hmm... Promettons que, peu importe ce qui arrive, tu te souviendras toujours de \"Ramona\", d'accord ?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6457_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Je ne regrette pas le choix de devenir ce que je suis ; si j'avais à le refaire, je le ferais encore. Mais, Gardien, j'ai très peur... peur que « Ramona » ne laisse aucune trace dans ce monde."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6458_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "Ne t'inquiète pas, le bandeau ne nuit pas à ma vision. Au contraire, il m'aide à éviter de tout voir."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6459_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Mon expression semble-t-elle étrangère ? J'ai essayé de la contrôler... Il semble que sa présence devient plus forte."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6460_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Trop de mystères à résoudre, trop de personnes à sauver. Je ne sais pas combien de temps je peux continuer, et je ne peux pas protéger tout le monde... C'est vraiment difficile."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6461_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Tu veux toujours parier sur moi ? Il semble que vivre comme bon nous semble n'est pas si facile. Ne t'inquiète pas, je vais me relâcher tout en résolvant tes problèmes."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6462_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "À ce stade, nous n'avons d'autre choix que de révéler nos véritables compétences, n'est-ce pas ? Où se trouve la scène du crime ? Même si je dois brûler toute ma chance, je ramènerai définitivement le suspect avant la date limite !"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6463_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Soupir, j'ai pris tant de services de ta part, je ne peux plus garder ce secret : en réalité, je pourrais être la personne la plus malchanceuse au monde"
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6464_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Il semble que tu n'aies pas pris mes paroles à cœur... Peu importe, je vais quand même t'aider à déchirer des ennemis. Après tout, ces griffes et ces crocs ont été acquis par chance, non ?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6465_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "Ma chance ne se transférera peut-être pas à mes compagnons. Vous avez dû entendre le dicton, n'est-ce pas ? \"La patte de lapin n'est pas chanceuse pour le lapin.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6466_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Souhaitez-vous imprégner votre âme du signe de Yu ?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Désires-tu tellement mon pouvoir ?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "N'aie pas confiance en mon apparence ; j'étais autrefois une dame... Je pouvais broder, lire Tennyson... Oh, et je pouvais chanter : Elle coule comme une rivière sans fin dans mes veines~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pikman et moi travaillons sur une installation artistique fascinante, explorant la reconstruction de l'abstraction par la déconstruction du primitivisme visuel... Hein, pourquoi Aurita s'est-elle évanouie ?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Chat · À propos d'Aurita"
  },
  Voice_6470_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Aurita »"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = [[
Veux-tu que je souris ?
Lily, est-ce que je souris ?]]
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur les Sourires"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Quelle surprise, j'ai gagné une amitié égalitaire.\nCependant... je demande à conserver le droit de vous commander, pour un peu de plaisir entre nous. Venez dans ma chambre ce soir ; j'ai encore beaucoup à apprendre sur les émotions humaines..."
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6472_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Tu sais ce qui te rend le plus mignon ? C'est quand tu me dis \"non\". Ton nez se plisse, tes sourcils se lèvent légèrement... Oui, juste comme maintenant."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6473_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "J'aime mes sbires. Ces charmants petits gars, tremblant de Dissolution et se cachant derrière moi, sont si attachants. Les larmes d'une beauté sont toujours captivantes. Et vous ? Avez-vous peur de la Dissolution ?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6474_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Gardien, y a-t-il quelqu'un que tu n'aimes pas ? En guise de faveur, je peux lui donner une leçon. Dans une semaine, ce sera une personne changée, te léchant obéissamment les orteils."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6475_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "Hmm... Bien que vous soyez ennuyeux, vous n'êtes pas entièrement désagréable. À partir de demain, vous me servirez.\nVous ne voulez pas...? Ce n'est pas une demande ; c'est un ordre."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6476_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Cela fait longtemps que je ne me suis pas senti ainsi. Je vais monter sur scène dans une forme parfaite et livrer une onde sonore qui s'étend à travers l'univers juste pour vous."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6477_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Vous devez savoir que cela n'a pas de sens."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6478_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Après avoir cueilli la fleur de la victoire, je voudrais réclamer une petite récompense..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6480_AwakerVoiceContent = {Text = "Ah !"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Frappe·Dépression·III"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "L'aéronef était exigu et claustrophobe, comme un cercueil en métal flottant dans l'espace. J'ai attendu mon Étoile du Matin jusqu'à ce que tu apparaises."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6481_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Comment cela pourrait-il être ?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Frappez·Fureur·Moi"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Frappe·Dépression·I"
  },
  Voice_6484_AwakerVoiceContent = {Text = "Aïe..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Frappe·Dépression·II"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Punition Divine !"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "Punition Divine !"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6487_AwakerVoiceContent = {Text = "Ennuyeux."},
  Voice_6487_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Je tiens toujours bon."
  },
  Voice_6489_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6490_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "Que les irrévérencieux soient dissolus dans la tranquillité ardente."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Faites attention ! Si vous atteignez un autre espace dimensionnel, vous pourriez ne pas récupérer votre main !"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Une bande de perdants. Si vous ne voulez pas finir en viande hachée, vous feriez mieux de faire attention la prochaine fois."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Oh mon dieu, es-tu affectueux avec moi ?\nC'est problématique. Si cela continue, je ne pourrai pas attendre que le Gardien mûrisse complètement..."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Plonger dans les profondeurs du libre arbitre !"
  },
  Voice_6496_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6497_AwakerVoiceContent = {
    Text = "Détester... C'est certainement ceux qui abandonnent en cours de route. Rien que d'y penser me donne envie de vomir le dîner de la nuit dernière."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Regarde ton visage, ô crâne sans fin !"
  },
  Voice_6498_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6499_AwakerVoiceContent = {
    Text = "Regarde ton visage, ô crâne sans fin !"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6500_AwakerVoiceContent = {Text = "Ha !"},
  Voice_6500_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6501_AwakerVoiceContent = {Text = "Ha !"},
  Voice_6501_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "Me fais-tu autant confiance ?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6502_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6503_AwakerVoiceContent = {Text = "Reviens."},
  Voice_6503_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6504_AwakerVoiceContent = {Text = "Bien !"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Bien sûr que je sais, c'est un autre aspect de moi. Mais pourquoi résiste-t-elle ? N'est-ce pas à portée de main d'accepter le destin de l'élu et d'obtenir ce pour quoi on prie ?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Discussion inutile : À propos de \"Murphy\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Bonjour, je m'appelle Jonquille. J'ai une fois échangé avec un invité qui a demandé que je vous aide. Alors, laissez-moi entendre ce dont vous avez besoin. \nOh mon Dieu... ce que vous souhaitez a un prix assez élevé, n'est-ce pas ?"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6507_AwakerVoiceContent = {
    Text = "*Silence* Que faites-vous ! Croyez-le ou non, je vais vous couper la main !"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahaha !"},
  Voice_6508_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6509_AwakerVoiceContent = {Text = "Hahaha !"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Les épines de Rose piquent les doigts, se transformant en poésie."
  },
  Voice_6510_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6511_AwakerVoiceContent = {
    Text = "Courbé sous cette profonde encre de chagrin, devenez une chanson de deuil..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "Regarde ça... !"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6513_AwakerVoiceContent = {Text = "Hmm... !"},
  Voice_6513_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "Arrivée des Clades!"
  },
  Voice_6514_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6515_AwakerVoiceContent = {
    Text = "Donnez-le-moi."
  },
  Voice_6515_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6516_AwakerVoiceContent = {
    Text = [[
...Mon nom, euh, je ne peux pas m'en souvenir.
Oh, d'accord, "24", c'est ce qu'ils m'appellent... Non ! Ne sors pas ! Tu ne peux pas, pas maintenant.]]
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6517_AwakerVoiceContent = {
    Text = "Le flux des marques d'encre..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Émergence..."
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "Je ne mérite pas le titre de \"Voix Céleste\"... Tant que tu apprécies mon chant, c'est tout ce qui compte."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Chit-Chat: Sur le chant"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Les vêtements sales doivent être changés avant le prochain salon."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Ça me rattrape, l'obscurité éternelle... Personne ne peut s'échapper."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Chaque fois que je te vois, je pense aux chaînes invisibles que tu as placées sur moi. Te laisser vivre est mon plus grand acte de tolérance."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Peu importe combien de fois nous recommençons, je marcherai à vos côtés."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Que l'amour de Dieu réchauffe votre âme."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "J'aime errer sans but. Marécages, cimetières, infirmeries, châteaux abandonnés... Dans ces endroits, je trouve toujours des plaisirs inattendus."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Soyez honoré, car les portes du Royaume Éternel sont ici."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Hehe—si chatouillant ! Aurita veut gratter !"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"La Mort du Cygne,\" une performance où la danseuse utilise le langage corporel pour exprimer le désir et la lutte de la vie. N'est-ce pas cette figure tordue dans les flammes qui est la même ?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Tranche, tranche, déchire. Juste comme ils m'ont fait dans le passé... hehe... hehehe!!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Tu ferais mieux de ne pas t'approcher trop près de Mademoiselle Thais... Non, je ne suis pas jaloux. J'ai juste peur que quelqu'un tombe dans les pièges d'une femme."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Thais"
  },
  Voice_6530_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Thais »"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...Merci beaucoup."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6531_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Très bien... tu as un bon œil pour reconnaître les gens."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6532_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "La ville natale de Karen est magnifique! C'est une ville de pierre dans un lac.\nÀ chaque pleine lune, nous dansons silencieusement dans les flammes, adorant...\nHonnêtement, lorsque Karen est venue à l'université pour la première fois, elle manquait de chez elle chaque nuit et pleurait dans son lit. Mais maintenant, Karen a un nouveau foyer et une nouvelle famille. Tout est mieux!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6533_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Oh~ Vous n'êtes toujours pas satisfait ? Allez, laissez-moi vous entraîner rapidement~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Muscles faibles, visage haggard - seuls ces yeux morts ont de la valeur. Parfait pour nourrir les araignées."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "Merci... pour tout ce que vous avez fait pour Aigis. Aigis fera de son mieux... pour ne pas vous décevoir !"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Cri de peur)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6538_AwakerVoiceContent = {Text = "Non !"},
  Voice_6538_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6539_AwakerVoiceContent = {
    Text = "Épargne-moi..."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(Cri de peur)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "La maîtrise de l'escrime de Mademoiselle Ramona est assez différente des techniques que j'ai maîtrisées. Si mon seigneur le permet, j'aimerais croiser le fer avec elle... Bien sûr ! C'est uniquement pour l'amélioration personnelle !"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6541_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Vous demandez pourquoi je ne joue pas avec les autres enfants ? C'est difficile à admettre... Dans ma vie précédente, j'avais peu d'occasions de jouer. Mon seul compagnon était la princesse que je servais... Ah ! Mentionner un autre monarque devant mon seigneur, veuillez excuser ma maladresse."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6542_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Vous êtes reconnu par l'Université Mythag en tant que Gardien, donc je vous accorderai les autorisations d'accès correspondantes."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Discussion inutile · À propos de \"Protagoniste\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Es-tu intéressé par les \"Sept Compétences Chevaleresques\" que j'ai apprises ? C'est merveilleux ! Ah... euh... je te prie de pardonner ma précédente impolitesse. Ce que je voulais dire, c'est que si tu souhaites pratiquer le tir à l'arc monté, je serais honoré de servir de partenaire d'entraînement !"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6544_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Je ne suis pas un chevalier digne. Que ce soit à cause de la vile peste ou des ennemis envahissants, j'ai échoué à protéger mon ancien seigneur. Maintenant, la confiance que vous placez en quelqu'un comme moi est un immense honneur... Je jure sur mon honneur de chevalier et cette vie insignifiante que je veillerai toujours sur votre chemin à venir."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6545_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Ne fais pas de mal."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6547_AwakerVoiceContent = {Text = "Allez~"},
  Voice_6547_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Tapez !"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "Ne tue pas."
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "Alors confortable~ !"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Maintenant, nous sommes comme l'eau et l'huile qui ne se mélangent pas."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "Je n'ai pas de favoris particuliers. Si je devais dire, la sensation de partir en missions est plutôt agréable."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Pourquoi, pourquoi me enfermer ici ? Haha... Je ne te laisserai pas réussir. Je déchirerai ces entraves, cette prison... en morceaux !"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Protéger tout le monde."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Vous les gars, ne vous fatiguez-vous jamais de regarder le spectacle de magie ? Restez tranquilles, d'accord ? Si vous montez encore sur scène, je vous jetterai dans une autre dimension !"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos des Enfants"
  },
  Voice_6555_UnlockDesc = {
    Text = "Débloqué après l'acquisition de l'un des Réveilleurs \"Aigis\", \"Jenkin\", \"Lily\", \"Murphy\", \"Karen\" ou \"Aurita\""
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "J'accepte avec gratitude votre cadeau."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Quel genre de cadeau de retour pourrait correspondre à ton dévouement ?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Quelle splendeur..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Courant élevé détecté, démarrage de la maintenance... Correction, pourquoi n’y a-t-il pas de surchauffe ?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6559_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Depuis le dernier rituel d'Illuminer, j'ai commencé à voir des visions fragmentées pendant l'État de dormance. En elles, je possède un corps Caro comme le tien, et des larmes coulent de mes yeux. Est-ce un rêve ?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6560_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Après chaque rituel, un niveau élevé de chaleur est détecté dans la zone du torse, mais aucun composant lié à l'énergie n'est présent. Sais-tu pourquoi ?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6561_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Je l'ai vu. Tout devrait <Del:périr dans le courant éternel>. Désolé, désolé, le module semble—Alerte, alerte. Activité de conscience non-Erica en augmentation. Détruire, détruire, des... Bonjour, comment puis-je vous aider ?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6562_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Après une analyse minutieuse, j'ai déduit que ce que j'ai vu dans mon état dormant n'était pas un rêve au sens traditionnel, mais plutôt ma <Del:pitoyable Caro Corps qui devrait être détruit> Mémoire. Quant à la chaleur brûlante semblable à une surcharge, cela pourrait être l'émotion connue sous le nom de \"Réticence\"."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6563_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Si tu veux regarder la performance, assieds-toi correctement dans le public !"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6564_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Les flammes de la haine brûlent intensément, jamais éteintes."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "La volonté avec laquelle j'ai fusionné est bruyante ; plus je monte, plus la voix \"de Lui\" devient claire... comme les oies à Hyde Park, plutôt bruyantes."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6567_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "J'utiliserai ce pouvoir pour dévorer le traître."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...Merci beaucoup."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Gardien ? Ridicule. Il est temps de se réveiller de ce rêve irréaliste."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6571_AwakerVoiceContent = {
    Text = "Le sang de la vengeance bout..."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Allez, serviteurs !"
  },
  Voice_6572_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6573_AwakerVoiceContent = {
    Text = "Ne te noie pas !"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6574_AwakerVoiceContent = {Text = "Whoosh !"},
  Voice_6574_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "J'ai jeté les pièges à souris à la porte arrière de la cafétéria. Ils sont trop dangereux. Et si ce maladroit de Brown se mettait à marcher dessus !"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "C'est si étrange... Suis-je en train de mourir ? Non, sauvez-moi ! Non !!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6576_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Je veux une lampe qui ne s'éteint jamais. Elle a en fait dit de l'échanger contre un spécimen de \"hydre volante sans ailes.\" Où puis-je trouver une espèce aussi bizarre ?"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos des Jonquilles"
  },
  Voice_6579_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jonquille\""
  },
  Voice_6582_AwakerVoiceContent = {Text = "Danger."},
  Voice_6582_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6583_AwakerVoiceContent = {
    Text = "Avertissement."
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6584_AwakerVoiceContent = {Text = "Coup."},
  Voice_6584_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6585_AwakerVoiceContent = {
    Text = "Un trésor qui brille comme des emballages de bonbons... Aigis le chérira dearly."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Dégâts subis."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Mon magasin existe dans n'importe quelle dimension, n'importe quel emplacement dans l'univers, et bien sûr, il peut être ici. En outre, j'aime ces enfants insouciants dans Mythag."
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Détester... Les poivrons verts ont un goût terrible."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Notre relation est comme celle entre une voile et un bateau. Sans le bateau, la voile ne devrait pas exister ; sans la voile, le bateau ne peut pas voyager loin. N'est-ce pas vrai ?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "La danseuse dévouée est morte, et le blasphémateur de l'art est également mort, tous deux péris dans des flammes remplies de l'odeur de goudron. La mort n'est pas la fin mais le début, car seuls les humains meurent ; la danse et l'art sont éternels."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6590_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Merci pour votre compréhension. Peut-être que maintenant est le moment de me réconcilier avec mon passé... Je crois que je fais ce qui est juste et que je n'ai pas déshonoré l'héritage de ma famille dans la danse. Je monterai sur la scène que vous avez préparée et brillerai comme vous le souhaitez."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6591_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Faites attention."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "Veux-tu que je monte sur scène et brille ?\nC'est impossible maintenant. Ces yeux ont été consumés par la haine. Tout ce que je peux faire, c'est réduire tout en cendres."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6593_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Comprends-tu ce sentiment ? Tourner, tourner, tourner, sans jamais s'arrêter. Genoux étirés à l'extrême, orteils saignant de noir, imbibant les ballerines, pourtant jamais une pause. Tout ça parce que je refuse d'accepter le destin d'être un jouet..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6594_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Je n'ai pas brûlé de danseurs de cour compétents, de maîtres de ballet gracieux, ou de nobles appréciant le sublime et la beauté. J'ai brûlé des imbéciles inutiles vendant leur corps, des flatteurs méprisant les autres, et des êtres sordides perdus dans la luxure... Vous me comprenez, n'est-ce pas ?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6595_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Je n'aime pas ces gens avec des tentacules visqueux, et je n'aime pas l'océan... Ne me fais pas ce regard compatissant ! Je ne suis pas un enfant qui a peur de ses parents !"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6596_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Votre générosité est grandement appréciée..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "Disparaissez !"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "Disparaissez !"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Dépêche-toi, prends Brown et pars !"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6601_AwakerVoiceContent = {
    Text = "Ne le faites pas..."
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "Défense·Dépression"
  },
  Voice_6602_AwakerVoiceContent = {
    Text = "Fiche le camp !"
  },
  Voice_6602_AwakerVoiceTitle = {
    Text = "Défense·Manie"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Qui est Leigh ? Oh, la femme qui m'a demandé de la frapper. Haha, intéressant... Cet endroit n'est pas si ennuyeux après tout."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Chat·À propos de Leigh"
  },
  Voice_6603_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Leigh »"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "Le coucher de soleil sur la petite colline me rappelle souvent mes jours à Cleveland... Cleveland, je ne peux pas croire que je me souvienne encore de ce nom, l'endroit qui m'a donné ces cicatrices."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Conversation Inactive : À propos du Crépuscule"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah... les étoiles... sont tombées..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Sans aucun doute, les humains. Existe-t-il des créatures plus sales que les humains ?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "C'est maintenant !"
  },
  Voice_6607_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6608_AwakerVoiceContent = {Text = "Hé !"},
  Voice_6608_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6609_AwakerVoiceContent = {
    Text = "Dissolution ? Hmm... Oui ! La glace fond ! Mais si nous la partageons, nous pouvons la manger avant qu'elle ne se transforme complètement en crème !"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "J'utiliserai cette force pour te protéger."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6610_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Oh chérie, aucun retour sur les objets vendus ici ! Tu as bien besoin d'un sous-marin pour plonger dans l'Aequor, n'est-ce pas ?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Chat · À propos de Caecus"
  },
  Voice_6611_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Caecus\""
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Le meilleur spectacle ! Tant les enseignants que les étudiants de l'Université Mythag peuvent comprendre que ma performance est véritable magie ! C'est sûrement ce qu'ils appellent l'esprit de sorcier, n'est-ce pas ?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "L'ordre de l'univers se déplace ici ; l'avenir de la destruction est la croyance du magicien !"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6613_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Aigis peut-elle rester ici un peu plus longtemps ? Je resterai silencieux, ne ferai aucun bruit et ferai de mon mieux pour ne pas vous déranger..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6614_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Dévoilez l'essence du monde avec l'intellect humain...!"
  },
  Voice_6615_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6616_AwakerVoiceContent = {
    Text = "Dans mes rêves, j'entends souvent le bruit de la marée, devenant de plus en plus faible. Je sais que je pourrais rester ici pour toujours, Humain."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Chat · À propos d'Aequor"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Plus de souvenirs, plus d'émotions, plus de rêves—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6617_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Ça commence à changer !"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "Ne cligne pas des yeux !"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Quand Il est né... Je n'aurai plus à endurer cette humiliation."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Choisissez-moi, choisissez-moi ! Là où il y a une fête, il y a Karen !"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hmm ? Intéressé par moi ? Je suppose que... tu es prêt à en payer le prix ?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Pas de pitié, pas de pitié... !"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Toujours chanter les couleurs des étoiles."
  },
  Voice_6624_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6625_AwakerVoiceContent = {
    Text = "Chante, chante !"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "Aime Maman !"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6627_AwakerVoiceContent = {Text = "Allez."},
  Voice_6627_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "Faites attention."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Les Réveilleurs peuvent manger par curiosité, mais la nourriture n'est pas essentielle à notre existence. Donc, il n'est pas nécessaire de m'appeler pour chaque thé de l'après-midi. La consommation de sucre n'accélère que l'usure des articulations de ce corps."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Bavardages : Sur le Thé de l'Après-Midi"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "S'il vous plaît, épargnez mon maître. Karen... faites ce que vous voulez avec Karen !"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Tous ces éléments sont-ils comestibles pour Lily ?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6633_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Ennuyeux ? Puis-je le dire ? Aigis déteste toujours se sentir impuissante... Mais si je dis cela, Jenkin va vraiment se fâcher..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Se transformer en cendres."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Se transformer en cendres."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Bien joué, Gardien. Alors, qui voulez-vous que je tue cette fois ?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6637_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "La Dissolution est la raison pour laquelle cette académie a été fondée et pourquoi nous nous sommes rencontrés. Pour sauver l'étincelle de l'humanité de la Dissolution, faisons de notre mieux, partenaire."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Je peux ressentir l'hostilité de la dame ; c'est sans doute mon amour pour toi qui a éveillé sa jalousie... Regarde, même la bouche de cette baleine à grandes ailes est ouverte par envie."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Chat·À propos de Lotan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Lotan »"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Maître, Maître ! Karen a vu un camée brooch incroyablement magnifique chez Harold aujourd'hui ! Pourriez-vous l'acheter pour Karen ? C'est ma demande de toute une vie !"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Je servirai de lumière guide dans l'obscurité, mais cette période n'est pas éternelle."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Mère, ça fait mal... Mère..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Abandonnez ! La victoire est aussi bonne que mienne !"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "Abandonnez ! La victoire est aussi bonne que mienne !"
  },
  Voice_6644_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6645_AwakerVoiceContent = {
    Text = "Dissolution... Ma capacité cérébrale est limitée ; je ne peux pas comprendre des maladies si complexes... Si vous avez besoin de réparer des machines, venez me trouver !"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Oh non ! Aurita a été retrouvée ! En pénalité pour la perte, tu peux faire une demande à Aurita—s'il te plaît, ne lui demande pas d'aller en classe, je t'en prie !"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Nettoyer le chemin pour son retour..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Un jour, l'oncle Ornn m'accueillera de nouveau chez moi sous l'eau. D'ici là, je peux être à contrecœur ami avec vous."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6648_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"Notre famille porte un grand sang; l'élu jouira d'une paix éternelle dans l'Aequor.\"\nJe ne m'attendais jamais à ressentir cette paix après avoir quitté la mer et être venu à l'académie. Vous êtes différent de ceux qui me harcèlent, donc je ne laisserai pas les autres vous harceler non plus."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6649_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Super matériau sur mesure !"
  },
  Voice_6650_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6651_AwakerVoiceContent = {
    Text = "Être piégé dans cette coquille imprégnée d'éléments humains me rend malade. J'ai enfin débarrassé du passé, et maintenant je dois m'en souvenir à nouveau..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6651_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Je sais, l'héritier de la grande lignée est encore une fois devenu un laquais pour les humains. Mais ne pense pas que tu peux me donner des ordres à ta guise."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6652_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hmph, tu fragiles humains as tout de même un certain talent en commandement, mais ce corps inférieur freine mon plein potentiel."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6653_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Mon corps devient de plus en plus chaud."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Échapper... Je dois fuir ! Je dois m'éloigner d'ici !"
  },
  Voice_6655_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6656_AwakerVoiceContent = {
    Text = "Échapper... Je dois fuir ! Je dois m'éloigner d'ici !"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Merci pour vos efforts. Permettez-moi de vous récompenser en conséquence."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "Ce n'est rien."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "（grogne de douleur）"
  },
  Voice_6659_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6660_AwakerVoiceContent = {
    Text = "Humain, bien que tu sois fragile, ta conviction m'a touché. Je suis prêt à devenir ton arme. Causons un peu de chaos ensemble !"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6660_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "C'est mon salon."
  },
  Voice_6662_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6664_AwakerVoiceContent = {
    Text = "L'Académie de l'Égalité... Je me demande quels rêves futiles vous abritez. Même si vous n'avez commis aucun tort, ils vous écraseront quand même sous leurs pieds. Je connais ce sentiment."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "C'est la source de toute impurité..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Exalter · Dépression"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "J'ai été puni pour ne pas avoir protégé l'équipage. Ils ont dit qu'en raison de ma négligence, les membres manquants de l'équipage ne retrouveraient jamais leurs familles... Est-ce ça, la Dissolution ?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Plus proche de mon Seigneur..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Pourquoi ? Pourquoi ne vas-tu pas... te réveiller ?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Je suis Horla de Cité, nom de plume... J'ai fait une promesse de ne le révéler à personne. Mes excuses, mais appelle-moi simplement Horla."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6670_AwakerVoiceContent = {
    Text = "Je m'oppose à tous les actes d'injustice, la trahison étant la pire. Dans l'armée, si vous ne pouvez pas ou n'osez pas faire confiance à vos camarades pour protéger vos arrières, toute l'unité s'effondrera."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Pourquoi apparais-tu si sombre, mais si radieuse ? ... Non, laisse tomber, ignore juste mes divagations."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_6672_AwakerVoiceContent = {
    Text = "（Gémir）"
  },
  Voice_6672_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(Grogne de gémissement)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6674_AwakerVoiceContent = {Text = "Quoi ?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "J'aime la vie, et j'aime la lumière. Je veux que l'Évanouissement émerge de sa coquille isolée et découvre le monde avec ses propres yeux et oreilles."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Vous ne pouvez pas me voir !"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "Le travail de maintenance doit-il continuer ?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "La maintenance des pièces a été complétée."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "Les gens peuvent trahir, mais les outils ne le feront jamais. S'ils sont utilisés correctement, la dissolution peut aussi devenir un outil de vengeance."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Après un millénaire d'attente, le moment est enfin arrivé... Je suis le véritable souverain des Péritites !"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_6680_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Était-ce un hybride d'Aequor que nous venons de croiser ? Hmm... regarde ce dos droit. Ce soir, je le verrai se prosterner."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Chat · À propos de Caecus"
  },
  Voice_6681_UnlockDesc = {
    Text = "Débloquez après avoir obtenu le réveilleur \"Caecus\""
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "La puissance revient progressivement entre mes mains... La prochaine étape est de saisir le pouvoir qui m'appartient de droit !"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6682_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Pas mal. Nous sommes un pas plus près de déchirer le voile hypocrite de cette femme."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_6683_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Calme-toi, calme-toi, calme-toi..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Pas besoin de s'inquiéter. Mon seuil de douleur pourrait être bien au-delà de ton imagination."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6685_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Si tu veux mon avis, les belles stupidités sont les meilleures. Malheureusement, il y a trop d'esprits intelligents mais inutiles ici."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Alimenté par la fusion nucléaire d'une géante rouge, complété par l'énergie d'une étoile en effondrement, vous pourriez démarrer une machine à mouvement perpétuel et allumer une lampe éternelle... Hein ? Vous dites qu'il n'y a pas moyen de construire une machine à mouvement perpétuel ici, et pas de géante rouge ? Hmm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "Le sang de l'ennemi n'a pas encore complètement drainé."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Donne-leur tous... à moi !"
  },
  Voice_6689_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6690_AwakerVoiceContent = {
    Text = "Donne-leur tous... à moi !"
  },
  Voice_6690_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6691_AwakerVoiceContent = {
    Text = "Il est temps de se diriger vers le champ de bataille."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "Il est temps !"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Quand je dors, des rêves débordants causent un tumulte spirituel. Donc, ne t'approche pas de moi pendant que je dors, et ne me réveille pas à la légère."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos du Sommeil"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "Il est temps !"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Bien que Herbert soit une personne terrifiante, ses chats sont très doux... Non, pour être précis, il y a deux chats, non ?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Paroles Idle · Sur Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Débloqué après avoir terminé \"Opération Investigation\" Chapitre 2"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Cette femme Murphy s'habille trop de façon ostentatoire... Pas question, Karen ne peut pas perdre contre elle !\nOu peut-être, juste la tuer..."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos de Murphy"
  },
  Voice_6696_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ah~"},
  Voice_6697_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "Te sens-tu à l'aise ?"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "Lorsque nous avons collaboré avec l'Université Mythag, il a été clairement convenu que je ne serais pas envoyé au combat..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6699_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Ne te laisse pas emporter. Parfois, la ligne entre noble et bas est juste un pas."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6700_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros vous salue. M'invoquer ici doit signifier que vous êtes prêt à prendre le large."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_6702_AwakerVoiceContent = {
    Text = "Yahoo—Je suis si fatigué, puis-je aller jouer maintenant !"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah... Son éclat est si intense et éblouissant, impossible à ignorer. C'était un zèle insensé qui a troublé mes sens... Non, je ne peux pas trouver d'excuses à ma stupidité."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Chit-Chat · À propos de Tulu"
  },
  Voice_6703_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Tulu\""
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Les étoiles dans le rêve, se dirigeant vers leur destination, pointent vers le royaume de Dieu !"
  },
  Voice_6705_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6706_AwakerVoiceContent = {
    Text = "Ne trouves-tu pas fascinant de pousser tout vers sa fin et de mettre un arrêt aux lois du monde ?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "À ta santé !"
  },
  Voice_6707_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6708_AwakerVoiceContent = {
    Text = "Douloureux !"
  },
  Voice_6708_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "Entrez la commande de bataille."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Pendant mes jours à errer parmi les étoiles, j'ai rêvé de ce moment des milliers de fois... Merci de m'avoir reunie avec Tinct."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Chit-chat·À propos de la Teinture"
  },
  Voice_6710_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Teinture »"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "L'Université Mythag est un endroit formidable, surtout avec le casino souterrain qui ouvre chaque semaine...\nHein, vous ne le saviez pas ? Oups, ai-je laissé échapper un secret..."
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Résister à la crise de Dissolution,\" ha, la satisfaction de soi des humains est vraiment risible."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Chat·À propos de l'Université Mythag"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Après tout, les humains ne sont que des créatures superficielles. Quelques mots, un indice, et ils commencent à se battre les uns contre les autres... Sigh, ce niveau de conflit est à peine suffisant pour inspirer."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Idle Talk · À propos des Humains"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Peut-être ai-je été myope de te considérer comme un humain ordinaire, tirant des conclusions trop rapidement. Je suis curieux—comment un non-croyant comme toi maintient-il sa détermination ? Ce n'est pas une question de la Mère de la Mer, mais une interrogation de Miryam. Peux-tu... y répondre pour moi ?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6714_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "Toi si unique, ne te lasserais-tu pas de ce monde superficiel et tumultueux ? Je crois sincèrement que le royaume éternel est là où tu appartiens. Tu marcheras sur la terre des dieux, te baigneras dans la piscine sacrée et t'enracineras dans un sol fertile... Rejoins-moi dans mon voyage sacré, et transcendons ensemble le plan mortel. Puis, côte à côte, nous nous tiendrons à côté du Trône, partageant la joie de reconstruire le Royaume Divin..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_6715_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Nous ne sommes tous que de simples mortels rampant dans la poussière, mais le Sage est différent. Il est l'Émissaire, une incarnation divine. Ses conseils résonnent avec les mots des dieux, guidant la civilisation vers l'immortalité... Je ne m'attends pas à ce que vous compreniez votre foi en lui maintenant, mais un jour, vous vous agenouillerez devant son Trône."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6716_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Les Élus sont vraiment bénis, n'est-ce pas ? Ils ont été dotés d'un pouvoir divin et d'une longévité prolongée. Lorsque le royaume de Dieu descendra à nouveau et que Sa volonté sera restaurée sur terre, ils deviendront des croyants glorieux. N'est-ce pas une immense fortune et une bénédiction pour l'humanité frêle ?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6717_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "La joie de se baigner dans la lumière divine dépasse la compréhension de quelqu'un comme vous qui manque de foi... Que mon dieu vous pardonne, pardonne votre ignorance et votre insolence."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6718_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Faisons vite, Gardien."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6720_AwakerVoiceContent = {Text = "Eh-heh—"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_6720_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Préparez-vous à mourir, insecte spartiate."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "Miss Doll dit que je peux temporairement éviter la Dissolution en abandonnant mon corps comme elle... Je ne peux pas le faire, je ne peux pas le faire, je ne peux pas le faire. Je vais perdre connaissance pendant la chirurgie, et l'obscurité va prendre le contrôle..."
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Chat · À propos de la poupée"
  },
  Voice_6722_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Poupée »"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hmph... Quoi ? Chercher le destin de l'oblitération ?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Toujours troublé par l'insomnie, Maître ? Karen a préparé le tranquilisant de Dobie pour vous~ ! Bien que la dose soit un peu élevée, un bon sommeil est la priorité absolue !"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_6724_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "Nous étions en train de boire et de chanter quand nous sommes soudainement devenus des monstres ! Mais ça va, la peau verdâtre est plutôt amusante !"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_6725_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "Le rêve de Karen? Hmm... Acheter un magnifique collier de perles et le porter à un bal, devenant la star la plus brillante!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_6726_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "L'extype du désir, Tifhreid, cherchait son chemin d'existence. Face à l'inconnu, personne ne peut juger de la noblesse ou de la bassesse de ses méthodes."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Chitchat · À propos de l'Entité du Désir"
  },
  Voice_67276_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Thais »"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Passez par la Clé Argent pour atteindre Son Trône."
  },
  Voice_67277_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_67278_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "Ne décevez pas Sa connaissance et Sa mémoire"
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Glissez à gauche, glissez à droite, essuyez la poussière et les soucis—"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_6727_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Je ne suis pas ici."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Un fragment du continuum espace-temps infini arrive dans ma conscience."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "J'ai vu l'ensemble du tableau."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Tout existe dans le vide."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Vous êtes allé profondément, très profondément. Bientôt, vous serez témoin d'un miracle extraordinaire. J'espère que vous pourrez rester aussi sain d'esprit et calme que vous l'êtes maintenant."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_67284_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "\"Ignorance.\" Non, rechercher assidûment l'essence n'est pas de l'ignorance ; la véritable ignorance réside dans le fait de vivre dans un flou, ignorant ce que l'on ne sait pas."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Je te montrerai mes rêves. Tout ce qui est bizarre et chaotique que tu y vois est plus proche de la véritable nature de ce monde que la réalité que tu connais."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_67286_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Voici mon conseil : Reste calme. Quand tu te sens fatigué, arrête-toi immédiatement et conserve ta force et ton énergie. Sinon, tu seras perdu à jamais dans le royaume des rêves."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_67287_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "L'univers cycle sans fin."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "La synchronisation entre nous ne devrait pas nécessiter un ajustement aussi long. Cependant, pour protéger votre clarté mentale des illusions, je vais procéder progressivement."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_67289_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Dissolution... Il se trouve que j'ai travaillé sur un cas connexe. Cependant, disparaître semble être une chose naturelle, n'est-ce pas ? À la fin, tout le monde disparaît."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "La Première Porte. L'univers infini est né d'un point."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_67290_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "La Deuxième Porte. Une ligne s'étend d'un point, s'étirant vers des polarités infinies."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_67291_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "La Quatrième Porte. L'archétype éternel solidifié dans un espace de dimensions."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_67292_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "La Troisième Porte. Les plans sont des pronoms partiels et unilatéraux."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_67293_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Portail des Extrêmes. Le vide final liant d'innombrables univers. Passe à travers le Portail des Extrêmes, et les ultimes mystères du monde te seront révélés."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_67294_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "La Cinquième Porte. Le passage du temps n'est qu'une illusion ; il n'y a jamais eu de commencement, et donc, pas de fin."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_67295_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "J'étais censé être juste votre guide, vous menant dans ce voyage avant de me reposer dans les eaux illusoires. Maintenant, vous êtes mon Lien, et notre connexion est si complexe qu'il est difficile de la rompre..."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Souhaites-tu confirmer quelque chose ? Malheureusement, les sens et l'esprit de ce corps sont trop restreints. Si nous nous rencontrons dans l'Abysse, je peux te montrer beaucoup plus..."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Elle est l'un de mes Fragments, d'une autre Dimension qui a été éternellement anéantie. Malheureusement, bien qu'elle ait maîtrisé le retour dans le temps, elle n'a pas réussi à saisir l'essence de la transcendance de l'espace-temps, succombant à maintes reprises à l'angoisse. C'est de ma faute."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Chitchat · À propos de Ramona la Vagabonde"
  },
  Voice_67298_UnlockDesc = {
    Text = "Débloqué après avoir obtenu l'Éveilleur \"Ramona: Ancien\""
  },
  Voice_67299_AwakerVoiceContent = {Text = "Je sais."},
  Voice_67299_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_6729_AwakerVoiceContent = {
    Text = "Es-tu préoccupé par l'apparence de ce corps ? Ne te fais pas trop de soucis. Je suis né avec un visage humain."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_67300_AwakerVoiceContent = {Text = "Je vois"},
  Voice_67300_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_67301_AwakerVoiceContent = {
    Text = "Comme c'est minuscule."
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Maintenir son calme."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Se lier directement à la substance endommagera ton esprit... Cependant, puisque tu insistes, je répondrai à ton appel."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_67304_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "Cet enfant a enduré bien trop à cause de mon Fragment. Heureusement, son Âme reste aussi claire que de l'argent en liquide..."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Chitchat · À propos de Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Ramona\""
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Visitez Son rêve et entrez dans les tabous secrets de l'univers."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Hmm."},
  Voice_67307_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_67308_AwakerVoiceContent = {
    Text = "La Porte des Extrêmes s'ouvre pour vous. Embrassez le monde du silence mortel au-delà."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_67308_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Mon objectif en établissant cette école avec eux est pour le \"Stockage\". Tu as réalisé plus que je ne l'avais anticipé."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "La Dissolution est un don divin. La douleur qu'elle apporte suffit juste à paralyser nos nerfs, nous permettant de nous plonger de tout cœur dans la nourriture, le vin et la fête, puis de nous diriger vers l'extinction."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Chat · À propos de la Dissolution"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Passé, présent et futur : toute la brillance de milliards est liée à cela !"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Passé, présent et futur : toute la brillance de milliards est liée à cela !"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "La Porte desExtrêmes est ouverte. Ici, toutes les choses convergent en une seule!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "La Porte desExtrêmes est ouverte. Ici, toutes les choses convergent en une seule!"
  },
  Voice_67313_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_67314_AwakerVoiceContent = {
    Text = "Écoutez la voix de la sagesse."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Infinie, sans limites, interminable, et illimitée."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Trois"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "C'est Sa volonté... Non, plutôt, c'est un regard inconscient qui englobe toutes choses dans Son souffle."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Incapable d'enquêter en profondeur... traces subtiles..."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Je révélerai la vérité."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "\"Répondre\" Je garde cette Porte par amour, et c'est aussi par amour que je place la Clé dans ta main."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Doit... revenir..."
  },
  Voice_6731_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_6732_AwakerVoiceContent = {
    Text = "Ciel et Terre, le cycle du karma !"
  },
  Voice_6732_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6733_AwakerVoiceContent = {
    Text = "Ciel et Terre, le cycle du karma !"
  },
  Voice_6733_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6734_AwakerVoiceContent = {
    Text = "La lame n'a pas encore perdu sa couleur."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "L'entraînement ne doit pas être négligé."
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Plus agile maintenant."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Des entités invisibles seront sous votre commandement."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_6737_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Ressentez ce souffle brûlant—"
  },
  Voice_6738_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6739_AwakerVoiceContent = {
    Text = "Nous allons tous devenir... partie de la Flamme Verte..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Mon bouclier brillera pour vous, mon seigneur."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_6740_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Amélioré encore une fois, profondément apprécié !"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_6741_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Tch"},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(Endurance méprisante)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(Endurance méprisante)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(Endurance méprisante)"
  },
  Voice_6746_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6747_AwakerVoiceContent = {
    Text = "Le temps passé avec tout le monde semble toujours si relaxant..."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "Le Hilote de Massacre, Messager de Tisiphon, Lame de Haine... Ils m'ont attribué ces titres. Bien sûr, cela ne me dérange pas d'être cette personne."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Chitchat · À propos de moi"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6749_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_6750_AwakerVoiceContent = {Text = "TAPIS !"},
  Voice_6750_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "(Exclamation)"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "Pouvons-nous aller plus loin cette fois-ci ? Allons à la plage !"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "Wow—merci, pote~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Compagnons~Plus de Compagnons~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash... il est spécial. Pensez-vous que la prospérité de ma famille est venue facilement ? C'est grâce à lui tuant comme un chien enragé dans l'arène. C'est notre plus grande vache à lait."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Chat·À propos de Uvhash"
  },
  Voice_6757_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Uvhash »"
  },
  Voice_6758_AwakerVoiceContent = {Text = "Insensé !"},
  Voice_6758_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "Allez ! Donnez l'ordre de bataille !"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "Dans l'abîme... il y aura une lumière de justice."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "La lumière de la justice est allumée ici !"
  },
  Voice_6762_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6763_AwakerVoiceContent = {
    Text = "Les émotions humaines sont aussi fragiles et précieuses que des fleurs..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Idle Talk : À propos de Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Touché, reste, Blackjack !"
  },
  Voice_6764_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_6765_AwakerVoiceContent = {
    Text = "Touché, reste, Blackjack !"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "Ne résiste pas, ne pleure pas, ne vis pas !"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Ne résiste pas, ne pleure pas, ne vis pas !"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Porte, ouvre-toi !"
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Oh."},
  Voice_79297_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_79298_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_79298_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_80092_AwakerVoiceContent = {
    Text = "L'hydrothérapie, la thérapie électroconvulsive, la thérapie de contention, ce ne sont pas des traitements mais de la torture. Par conséquent, pendant ma période de pro bono, je traiterai les patients de l'hôpital psychiatrique à ma manière, et à la fin, ils atteindront tous la guérison et trouveront la véritable liberté."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_80092_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Pauvre White, parce que l'asile à proximité est plein, il a été gardé dans une porcherie par sa famille. Je l'ai traité gratuitement, et après cela, il a finalement réalisé qu'il était une personne, pas du bétail, et a retrouvé sa dignité humaine."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_80093_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Tisseurs, avocats, barons... Je ne tournerai jamais les patients vers le bas à cause des frais ; pour moi, ce ne sont que des patients ayant besoin de guérison."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_80094_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "J'admets que je t'ai effectivement sous-estimé ; ton existence est la douleur elle-même. Cette fois, pas besoin de visites de suivi, je veux rester à tes côtés et voir le résultat de mes propres yeux."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_80095_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Ces patients m'ont donné de beaux souvenirs. Ensuite, c'est votre tour, Gardien, j'ai déjà choisi la fin pour vous. Ce sera la consultation la plus exquise de ma carrière."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_80096_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Refuser l'aide du médecin ne vous profite pas. Peut-être que la prochaine fois, nous devrons essayer l'hypnose profonde."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "Dans une pièce sombre, tout seul, avec les innombrables chuchotements douloureux résonnant constamment dans mon esprit, c'est la meilleure façon de profiter du temps."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Bien que cela puisse paraître impoli à dire, parler à cet enfant ne me divertit que— vous ne pouvez voir qu'une seule expression, et c'est un sourire."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Chat · À propos d'Aurita"
  },
  Voice_81140_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Aurita »"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Pardonnez-moi de m'introduire, j'ai juste ressenti votre faible énergie psychologique et je suis venu vérifier votre état. Maintenant, Gardien, souhaitez-vous entreprendre un voyage mental ?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_81143_AwakerVoiceContent = {
    Text = "Le médecin psychiatre soigne les patients en perçant leur crâne avec une technique de trépanation — détends-toi, c'était il y a longtemps, maintenant nous avons de nombreuses façons de mesurer et d'approfondir l'esprit du patient."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_81143_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Pour se comprendre, il faut ouvrir son cœur — touche ici, et mon cœur en argent s'ouvrira pour toi."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Si tu veux entendre mes pensées sur quelque chose, tu pourrais être déçu. Plutôt que de me défouler, je suis meilleur à écouter."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "Ah, j'ai entendu sa voix, ces murmures, chaque syllabe remplie de la plus grande agonie !"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Je vais me souvenir de la douleur de ce moment dans mon cœur, le rappelant et le savourant à plusieurs reprises..."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "En tant que fragment de cette existence, vous portez son souffle, ce souffle rempli de douleur, rendant tous vos souvenirs d'un goût incroyablement délicieux."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Souviens-toi de ces peurs, détaille tes sentiments de douleur ; l'essence de la thérapie d'impact émotionnel est de faire face à la douleur directement et de la conquérir. Viens, essuie tes larmes et raconte-moi lentement ces souvenirs en détail..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_81149_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Félicitations, tu es guéri—oui, les hallucinations et illusions sont des phénomènes normaux ; ils sont la preuve de ta guérison."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_81150_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Votre esprit est sûrement rempli d'images étranges et bizarres, ce qui est normal. Sortez-les, et votre subconscient et vos instincts révéleront tout pour vous."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_81151_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Ensuite, il s'agit de la thérapie morale de Philippe Pinel. Tu dois exprimer tes désirs et craintes les plus profonds, ce qui est une procédure nécessaire pour libérer l'esprit et restaurer l'humanité endormie."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_81152_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Gardien, peux-tu m'aider avec un petit test ? C'est juste le test de tache d'encre de Rorschach. En le réussissant, je pourrai voir les profondeurs de ton moi intérieur qui restent inconnues des autres, devenant le seul Réveilleur à dévoiler les secrets du cœur du Gardien."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de l'analyse psychologique"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "D'abord, écoutons un morceau de musique. Entends-tu cette musique apaisante et douce ? Maintenant, laisse ton corps et ton esprit résonner avec la musique, entrant dans un état de relaxation spirituelle..."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_81154_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Regardant le pendule, vos yeux suivant son mouvement..."
  },
  Voice_81155_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_81156_AwakerVoiceContent = {
    Text = "Chut—Silencieux, puis avance vers la fin que je te guide."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Une âme engourdie ne m'intéresse absolument pas. Leurs âmes sont déjà mortes, et peu importe combien on les agite, il n'y aura pas de vague."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Je t'écoute, s'il te plaît continue."
  },
  Voice_81159_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_81160_AwakerVoiceContent = {
    Text = "Veuillez rester silencieux."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Fais-moi un peu plus confiance."
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "Exposez plus de douleur !"
  },
  Voice_81163_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_81164_AwakerVoiceContent = {
    Text = "Pas besoin de cacher, pas besoin d'avoir honte, je suis votre auditeur le plus fiable et le seul. Viens, déverse ta douleur la plus profonde sur moi..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis a l'air beaucoup plus lumineuse maintenant. Bien sûr, si ma petite invitée a besoin d'aide, je suis heureux de l'offrir. Je veux dire, une aide sincère."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Chat · À propos d'Aigis"
  },
  Voice_81165_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Aigis »"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Montre-moi ton moi le plus vrai."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Je savourerai cette douce douleur."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "Pas besoin de cacher, pas besoin d'avoir honte, je suis votre auditeur le plus fiable et le seul. Viens, déverse ta douleur la plus profonde sur moi..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "La maladie mentale n'est pas exclusive à cette époque ; elle transcende le temps et l'espace, et la dissolution est la même. Les deux transcendent les limites de la cognition humaine, n'est-ce pas ?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Chut—Silencieux, puis avance vers la fin que je te guide."
  },
  Voice_81171_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_81172_AwakerVoiceContent = {
    Text = "Cet endroit est rempli de traces d'histoire, et dans une certaine mesure, l'histoire représente des souvenirs—des souvenirs douloureux des disparus."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Profondément respiration..."
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Douleur, désespoir, mort... ces souvenirs goûtent comme un dessert après un repas."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Pas besoin d'être aussi nerveux, ce n'est qu'une simple consultation psychologique."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Écoutez mes conseils."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "Un incident inattendu s'est produit pendant le rituel. Je vous demande pardon d'avoir frappé votre bras avec le drapeau, je dois vous garder conscient."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_84185_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Ici, je peux observer différents modèles de navires et me familiariser avec des équipements de navigation plus avancés, ce que j'apprécie beaucoup. Mais surtout, je crois que ce « navire » suit la bonne trajectoire de l'histoire humaine."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "Le rituel s'est déroulé avec succès, merci pour votre coopération. La prochaine fois, je créerai des signaux de drapeau spécifiques pour nous aider à accomplir le rituel en toute sécurité et plus facilement."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_84187_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Je ne comprends pas pourquoi il existe, mais une chose est claire : je dois réussir ma mission de guidage et ramener sains et saufs tous les marins et passagers qui ont pris la mer."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "N'ayez crainte, j'utiliserai cette force pour guider la sécurité de la navigation du navire et ne l'utiliserai certainement pas de manière abusive."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Arrêtez de résister."
  },
  Voice_84190_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_84191_AwakerVoiceContent = {
    Text = "Je n'ai que du respect pour vous et je mourrai s'il le faut pour accomplir tous les ordres que vous donnerez."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Désolé, je ne comprends pas les humains, je ne comprends que les bateaux. Veuillez excuser cette comparaison : votre quille n'est ni en bois ni en fer, mais en acier, solide et déterminée, digne d'admiration."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_84192_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_84193_AwakerVoiceContent = {Text = "Reddition."},
  Voice_84193_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "Plutôt que « aimer », je préfère le terme « se convertir ». Lorsque je fixe du regard le dieu indicible, mon esprit perd la raison et bascule dans l'extase. Oui, je devrais Le craindre, mais je ne peux pas me contrôler."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Je ne serai pas renversé par la tempête."
  },
  Voice_84195_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_84196_AwakerVoiceContent = {
    Text = "Sans ordre, que reste-t-il à ce monde ? Rien d'autre que le chaos et la confusion."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "La prochaine fois que nous appareillerons, j'aimerais monter à bord non pas en tant que navigateur, mais dans un autre rôle. Euh... ce que je veux dire, c'est que je suis prêt à agir sous votre direction. Vous méritez pleinement ma confiance."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_84197_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Je remplis simplement mon devoir en tant que navigateur, il n'est pas nécessaire de me féliciter."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "Le système de phare peut considérablement réduire le stress du navigateur, et sa lumière est particulièrement éclatante. Je suis ravi de partir en mer avec Faros."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Chat · À propos de Faros"
  },
  Voice_84199_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Faros »"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Matelots, suivez mes indications, nous arriverons certainement en lieu sûr au port."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Lien spirituel établi, j'ai perçu votre conscience... C'est la première fois que je prends la navigation dans le vide, si jamais il y a une déviation, veuillez me corriger à temps."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_84201_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Observation de cirrus et chute continue du mercure dans le baromètre. Attention à tous : le navire va rencontrer une tempête."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Cette pagaille est entièrement de ma faute, j'ai mal planifié la trajectoire, et je suis prêt à accepter la punition conformément aux règles."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Mesurer l'angle d'élévation d'un astre."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Cette sensation de vertige est proche de celle du mal de mer. Ferme les yeux, saisis ma main et appuie-toi sur moi, ça ira un peu mieux."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_84205_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Rabattre la voile d'avant tribord, virer à bâbord pour affronter les vagues, le timonier doit ajuster la trajectoire selon mes calculs."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Ces expériences sont précieuses, je vais les enregistrer en détail dans le journal de bord, pour les transmettre aux marins futurs."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "Le rituel visant à renforcer le lien comporte des risques et des résultats incertains, mais rassurez-vous, je vous guiderai pour qu'il se déroule sans encombre."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_84208_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Réajuster le centre de gravité."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Faites attention à protéger le navire."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Certains sont comme des bateaux à vapeur, lents à réagir mais capables de fonctionner à grande vitesse, d'autres sont comme des bateaux diesel, démarrant rapidement mais avec une puissance limitée. Et vous, Gardien du Secret ?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_84211_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Je crois fermement à la règle fondamentale selon laquelle les efforts fournis seront récompensés. Je travaillerai encore plus dur à l'avenir."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "Au cours de plusieurs missions, vous avez déjà fait la preuve de vos compétences. Je pense que vous êtes un navigateur aussi bon que moi, non, peut-être même bien meilleur."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_84213_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Dès que vous avez besoin, Kepsante est toujours prêt."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_84215_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Membres de l'équipage, suivez mes indications, nous arriverons certainement en sécurité au port."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "Navigateur Kepsante, présent ! Le drapeau est prêt, mon état personnel est bon. Gardien, veuillez donner l'ordre de départ."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_84219_AwakerVoiceContent = {
    Text = "Je guiderai le navire vers la bonne direction."
  },
  Voice_84219_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_84220_AwakerVoiceContent = {
    Text = "Est-ce que mon chapeau est de travers ? Désolé, je ne comprends pas vraiment votre intention, donnez-moi des instructions claires."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "Le pavillon est la langue du timonier, ainsi que son épitaphe. Lorsque le navire sombre, les récupérateurs décrypteront parmi les débris du pavillon le dernier message que j'ai laissé."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Bavardage · À propos des drapeaux"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Détection du point d'équilibre du navire."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Rabattre la voile d'avant, virer à bâbord pour contrer les vagues, le timonier doit ajuster la trajectoire selon mes calculs."
  },
  Voice_84223_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_84224_AwakerVoiceContent = {
    Text = "Drapeau E pour transmettre les commandes."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "À des moments nécessaires, un navigateur ayant appris la coopération en salle des machines peut également agir comme timonier, mais pour assurer la sécurité du navire, j'espère tout de même pouvoir confier cette tâche à quelqu'un de plus compétent."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Discussion·À propos de Céleste"
  },
  Voice_84225_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Céleste »"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Une sensation de perte de poids survient, suivie d'une secousse violente comme celle d'un bateau secoué. Sens ton centre de gravité en synchronisant avec mes mouvements et maintiens ton équilibre."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_84226_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Commencer la correction de la carte marine."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Trois"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "Le Drapeau C répond à la commande."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Trois"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Tu ne me dépasseras pas."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "Comment devraient se comporter des amis l'un envers l'autre ? Pollux aime me donner des ordres et me demander de faire beaucoup de choses, même s'il est tout à fait capable de les faire lui-même. Et moi aussi, je suis prêt à faire ces choses pour lui, c'est notre façon d'échanger. Si tu le souhaites, je peux aussi faire quelque chose pour toi."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_90334_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Par ce corps immortel, je résiste à toutes les calamités !"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Même avant d'avoir lu ce livre, nous n'étions pas insensibles à la curiosité envers le monde extérieur, ni indifférents à l'apparence de l'île solitaire au milieu du lac et des paysages au-delà des murs sombres et rouges. Pourtant, même lorsque Pollux était torturé, je n'ai jamais envisagé de résister. Comparé à lui, j'étais vraiment bien plus lâche et bien plus maladroit."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_90336_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Ai-je l'air d'un idiot ? Je vous demande pardon, s'il vous plaît, excusez mon ignorance. En dehors des connaissances divines transmises par l'Église de la Lanterne, je connais très peu de choses du reste. J'apprendrai rapidement, dites-moi tout ce que vous aimez et détestez, je m'efforcerai de m'en souvenir soigneusement."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_90337_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Soyez témoin de cette volonté qui poursuit la liberté."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Un magasin capable de satisfaire n'importe quel souhait, des marchandises de tout genre, vraiment quelque chose qui inspire le respect... Non, je ne mets pas en doute le pouvoir de cette dame, mais « vouloir posséder quelque chose implique d'en payer le prix correspondant » est une leçon que Castor et moi avons trop souvent vécue."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Petites Discussions · À propos des Jonquilles"
  },
  Voice_90339_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jonquille\""
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Ces ailes maudites peuvent-elles également s'envoler jusqu'aux cieux ?"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Vous ne pouvez pas me détruire !"
  },
  Voice_90341_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_90342_AwakerVoiceContent = {
    Text = "Voulez-vous toucher ces plumes ? Faites donc, dois-je ouvrir mes ailes un peu plus ?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Quand je reçois de l'aide, je me demande souvent si ces attentions particulières, ces précieux manuscrits et ces magnifiques cristaux météoritiques que vous m'avez offerts n'ont pas un prix caché en réalité. Pardonnez-moi, je ne devrais pas douter de vous ainsi."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_90343_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "L'oiseau finira par s'envoler haut dans les airs."
  },
  Voice_90344_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_90345_AwakerVoiceContent = {
    Text = "Des maîtres en cuisine... Il est effectivement très important de posséder des connaissances sur la préparation des repas. Même si mes exigences en matière de nourriture ne sont pas très élevées, Pollux est vraiment trop difficile. Il faudrait sans doute trouver un moment pour aller demander sérieusement des conseils... Tu ne veux pas y aller ? Pourquoi ? Pourtant, les plats préparés par cet homme semblent tous très délicieux ?"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Dulséine"
  },
  Voice_90345_UnlockDesc = {
    Text = "Débloqué après avoir obtenu Éveillé « Dulsain »"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "En y repensant maintenant, les servantes que nous croisions autrefois avec la lanterne ne sont finalement pas si différentes que ça de Pollux et moi. Nous vivons tous en portant des chaînes, et elles font preuve d'obéissance et de patience face à cette réalité. Cependant, la servante verte semble un peu différente. Elle… déborde d'énergie, comme si elle aimait naturellement ce qu'elle fait. Peut-être possède-t-elle déjà la liberté la plus précieuse."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Chat·À propos de Karen"
  },
  Voice_90346_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Karen »"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Vous ne pouvez pas me détruire !"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Toujours pas réussi... à s'échapper..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Disparais avec le vent !"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Deux"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Bonjour, enchanté, je suis Castor... Est-ce que je dois dire autre chose ? Désolé, je ne suis pas très bavard. Si vous avez quelque chose à me faire savoir, n'hésitez pas à m'appeler."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Rien de plus…"
  },
  Voice_90352_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_90353_AwakerVoiceContent = {Text = "Tombe !"},
  Voice_90353_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_90354_AwakerVoiceContent = {
    Text = "J'ai beaucoup de choses que je n'ai jamais vues, des choses que je n'ai jamais faites, et ces eaux lacustres verdâtres et désolées, ces brouillards persistants ne nous retiendront plus. Océan, grandes villes, champs et pâturages, tous ces endroits mentionnés dans ce manuscrit, j'aimerais les voir, avec Pollux et vous."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_90354_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Tu sais que je suis à tes côtés quand tu entends les feuilles des arbres bruire au vent."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_90355_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Ces plumes sombres sont devenues plus profondes."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "En fait, ce que je jalouse le plus, c'est votre relation avec vos compagnons, cette absence totale de soupçon et cette confiance mutuelle. Le sentiment d'être oublié, trahi... est vraiment trop douloureux."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "La voleuse m'a dit qu'elle pouvait m'apprendre les meilleures techniques de survie en milieu urbain, il suffisait de la payer cinq cents réoupes... J'ai été berné ? Non, je pense que c'est une connaissance très utile à acquérir, exactement ce dont Castor et moi avons besoin... C'est une question d'argent ? Je comprends, alors je vais aller la voir pour négocier, que dirais-tu de quatre cent cinquante réoupes ?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Rumeurs · À propos de Jenki"
  },
  Voice_90358_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Jenkin\""
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Je peux encore tenir..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Quand j'étais petit, la gestion des lanternes n'était pas aussi stricte qu'aujourd'hui. Parfois, sans savoir ce que Pollux avait dit, il réussissait miraculeusement à obtenir un paquet de bonbons. Le goût de ces bonbons... était comme maintenant."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_90360_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Avec ce corps immortel, je résiste à toutes les calamités !"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Pourriez-vous m'enseigner les bases des échanges avec les autres ? Comment échanger des objets, comment gérer l'argent obtenu… C'est vraiment une science complexe. Être libre n'est que le début ; pour vivre de manière indépendante, Pollux et moi avons encore beaucoup à apprendre. Je compte sur vous pour m'aider à l'avenir."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Disparais avec le vent !"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Compétence spéciale · Un"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Vent, souffle-les dans la gueule de la mort !"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Pollux... bien qu'il ait été imprégné de nombreuses mauvaises idées par la Lanterne, son fond n'est pas mauvais. Il souhaite simplement ardemment obtenir la reconnaissance de la Lanterne et celle des fidèles, au point d'accorder une trop grande importance à leurs besoins. Plutôt que de dire qu'il est trop égocentrique, il serait plus juste de dire qu'il a constamment peur de perdre cet « ego » qu'il possède."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Bavardage · sur Pollux"
  },
  Voice_90365_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Pollux »"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Désolé, je ne voulais pas me laisser distraire... Vous me demandiez si cette plume était belle ? C'est... la chose la plus importante pour lui, et aussi la chose la plus importante pour moi. Elle est belle, non ?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "À cette époque, nous devions étudier la théologie tous les jours sous la direction d'Albino ou des Gardiens de la lumière. Mon plus grand souhait était alors qu'un jour les textes sacrés soient enfin révisés pour devenir plus courts et moins nombreux, afin que je n'aie plus à les réciter jusqu'à en avoir le tournis et me faire critiquer par les sévères Gardiens de la lumière."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_90367_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Merci de m'avoir donné la clé qui me permet de maîtriser la liberté."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Ces ailes ont enfin atteint leur pleine forme, si robustes, si puissantes. Désormais, je peux emporter à la fois toi et Pollux. Quand tu voudras t'envoler vers le ciel, appelle-moi fort."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_90369_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Cache-toi derrière mes ailes !"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Enfin... j'ai vu le ciel étoilé mentionné dans le livre."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Autrefois, notre Maîtresse... Juliette avait souvent des moments de tendresse envers nous. Elle ne manquait jamais de nous offrir son sourire chaleureux, faisant naître en nous la crainte de décevoir ses attentes. Quand elle souriait en te caressant la tête, il devenait impossible de prononcer un mot de résistance. Hmm, ce n’est plus le cas maintenant, vous pouvez me caresser la tête autant que vous le souhaitez."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_90372_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "J'ai été immergé très, très longtemps dans cette boue noire, si longtemps que j'en ai oublié le temps lui-même, si longtemps que... même Pollux m'a abandonné. Ce n'est pas une souffrance physique qu'elle provoque, mais une terreur spirituelle, celle de voir son âme disparaître sous ses yeux."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Depuis notre enfance, on ne nous a jamais permis d'avoir beaucoup d'échanges avec les autres. Le mot « ami » est quelque chose que j'ai découvert bien plus tard. Pollux et moi n'avions personne d'autre que l'autre. Frères, amis, prisonniers de la même cellule, tout cela nous concernait, rien que nous. Maintenant, il est temps de se faire de nouveaux amis."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_90374_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_90375_AwakerVoiceContent = {Text = "Reculez !"},
  Voice_90375_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "Une école où chacun peut librement échanger et se faire des amis ? Tu dis qu'ici on n'étudie pas la théologie et qu'on peut choisir parmi des cours variés... et même sécher les cours ? Hum, c'est vraiment un endroit merveilleux."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "Écartez-vous !"
  },
  Voice_90378_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "Impie... le châtiment viendra..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Mon cœur brille de lumière !"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "Objet impur."
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Un croyant trop fervent n'est peut-être qu'un fou incompréhensible aux yeux du monde. Bien qu'elle ait connu des errements, sa détermination à tout sacrifier pour les dieux est une résolution que la plupart des gens ordinaires sont incapables d'atteindre. Quant à elle… je ne ressens qu'une certaine tristesse à voir un être semblable à moi."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Bavardage · sur Miryam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Miryam »"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Je vais apporter le guidage et le jugement, le Glimmer de la nuit blanche dissipera vos péchés !"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Ha... Après tout ce temps, il n’a pas changé d’un iota. Moi, enfant, n’aurais jamais imaginé pouvoir blesser et décevoir mon frère à ce point, jusqu’à en être honteux, même si ce destin tragique échappait à notre contrôle à tous deux. Nous avons connu tant de séparations, mais puisque je suis revenu, désormais, rien ne pourra plus nous séparer, pas même la mort."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Bavardage : sur Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur \"Castor\""
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Autrefois, je détestais beaucoup de choses : les domestiques impolis, les serviteurs irrespectueux, les hérétiques qui blasphémaient contre les dieux... Mais aujourd'hui, la Lampe, uniquement la Lampe ! Juliette et son culte ont causé à mon frère et à moi-même des souffrances irréparables. Je le jure au nom du Saint-Enfant, je ne permettrai plus que de telles souffrances s'abattent sur d'autres personnes !"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Je suivrai la voie de la lumière jusqu'à la fin de mes jours."
  },
  Voice_95057_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_95058_AwakerVoiceContent = {
    Text = "La lumière du Porteur de Lampe dissipera enfin la longue nuit !"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Vous êtes toujours si généreux et bienveillant, je ressentirai profondément la chaleur de cette lumière."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "L'apôtre du Porteur de Lampe, celui né de la nuit blanche, le dissipateur des ténèbres, le saint fils au cœur sacré, moi, Pollux, je viens à votre appel pour vous offrir ma force obscure et mon âme lumineuse."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_95061_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "Lave ton péché !"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Autrefois, tout le monde me disait que cette noirceur abyssale était ma foi, la bénédiction que j'apporterais à mes fidèles. Aujourd'hui, cette ténèbre a déjà envahi mon être, fusionnant avec moi... Pourtant, dans ce corps pécheur, mon cœur battant restera à jamais hors de sa portée. N'ayez crainte, j'utiliserai sans faillir les capacités que cette noirceur m'a données pour offrir aux humains le véritable bienfait !"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Je propagerai votre grand nom, et toutes les choses impures et souillées seront finalement purifiées par la lumière."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Les péchés du passé ont été commis, il ne faut plus les fuir. Je dois aussi corriger les erreurs de la Lampe et guider ceux qui se sont égarés vers le bon chemin. Laissez-moi porter mes péchés. Ensuite, je répondrai à cette lumière, à votre appel, et j'emprunterai le véritable chemin du Saint Enfant."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_95065_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Quel cœur compatissant vous avez, pour vouloir pardonner à une personne couverte de péchés comme moi ! Je peux sentir cette lumière pure dans votre âme, plus brillante encore que la flamme d'une lampe. Peut-être pourrez-vous guider mon cœur égaré…"
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_95066_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Cette obscurité, celle qui s'est répandue à travers les incantations de Juliette, a toujours enveloppé mon esprit... Mais maintenant, une lumière est apparue au sein même de cette obscurité ! Ce faible point lumineux, veut-il me dire quelque chose ?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_95067_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "On m’a dit qu’elle avait été une sainte autrefois, mais avec une telle attitude grossière et des paroles arrogantes... Quoi ? Elle ne sait même pas réciter une prière ? Elle semble si peu dévouée, c’en est presque embarrassant pour ses dieux."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Débloquez après avoir obtenu l'Éveillé \"Murphy\""
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Celui qui peut guider les gens hors du brouillard est véritablement le porteur de lumière au corps d'argent pur. La terre sans péché mentionnée par Yriet est en réalité construite sur les ossements accumulés des fidèles. En tant que Fils Saint, je répandreai la nouvelle bonne nouvelle auprès de tous les croyants dignes d'être sauvés."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Meneur et porteur de lumière, autrefois j'étais aveuglé par un sens fallacieux, mais maintenant, sous votre guidance, j'ai retrouvé ma véritable mission : corriger les croyants ignorants et déformés, et apporter une lumière éternelle au monde. Je connais votre altruisme, vous n'avez pas besoin de ma dévotion ni de mes offrandes, alors permettez-moi simplement de rester à vos côtés, pour noter chacune de vos paroles saintes et chacun de vos actes sacrés, afin qu'ils puissent m'éclairer sur le chemin de la nuit obscure."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_95070_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Avec des chaînes, baignant dans l'obscurité, marchant inébranlablement vers cette lueur… Voilà ce que vous vouliez me dire ?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_95071_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Un serviteur de la lumière a perdu la lampe entre ses mains, cette douleur aveugle me tourmente vraiment. Je vous implore sincèrement de sauver cette âme égarée. Veuillez saisir ma main, approchez-vous de ce cœur sacré, et veuillez m'accorder à moi, la guidance vers la lumière…"
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_95072_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Pauvre enfant, mais puisqu'elle a choisi de suivre votre cause, elle trouvera certainement le salut final. Mais pourquoi son ami, ce singe, a-t-il également reçu votre grâce ? Cet enfant maléfique a même volé le récipient de mes prières ! Son âme doit certainement cacher un déluge de péchés. Quelle impudence ! Quelle impudence !"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Discutons · À propos d'Aigis et de Jenkins"
  },
  Voice_95073_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Aigis » et le réveilleur « Jenkin »"
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "Partez vite."
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "La lumière du Porteur de Lumière illuminera enfin la longue nuit !"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah... j'ai vu, la puissance immense, la vérité du monde... J'ai compris mes erreurs passées, vous êtes le véritable Porteur de Lampe ! Permettez-moi de devenir votre fidèle apôtre, ce cœur né pour le Porteur de Lampe, à partir de maintenant battra et tremblera en votre honeur..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_95076_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "Ce prêtre agit avec une rédemption aveugle, ce qui est une folie inacceptable. L'Évangile de Dieu doit naturellement être réservé aux justes pieux. Si même les apôtres de Dieu ne possèdent pas un œil perspicace pour distinguer ceux qui ne se repentent pas et qui sont couverts de péchés, leur permettant d'obtenir des récompenses et de souiller le royaume pur de Dieu, cela ne constitue-t-il pas une véritable Traîtrise envers Dieu et tous les justes ?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Débloqué après l'acquisition de Réveiller \"Salvador\""
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Mon cœur brille de lumière !"
  },
  Voice_95078_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_95079_AwakerVoiceContent = {Text = "Ha !"},
  Voice_95079_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_95080_AwakerVoiceContent = {
    Text = "Quand j'étais enfant, je voulais à tout prix m'échapper de cette cage. À l'époque, je pensais que cet endroit, qui n'apportait que de la souffrance, ne méritait aucun regret. Mais après avoir vécu deux vies, je comprends aujourd'hui que la liberté n'est pas la seule chose à laquelle j'aspirais. Voir les fidèles découvrir qu'ils seront sauvés, voir leurs visages emplis de foi, d'espoir et de gratitude, voilà la véritable signification du titre de Fils Saint."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Durant la période où je suivais Juliette, j'ai commis de nombreuses erreurs et ne méritais plus une telle confiance. Pourtant, vous avez continué à me choisir… Soyez sans crainte, je retrouverai ma propre foi. Le Saint Enfant ne décevra plus son peuple, ni vous."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_95081_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Je ferai bon usage de ce que vous m'avez confié, avec toute ma gratitude."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "Impolitesse !"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_95084_AwakerVoiceContent = {Text = "Merde."},
  Voice_95084_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_95085_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "Au nom de moi !"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "Je l'ai vu ! Ce rayon de lumière, cette lumière qui brille au plus profond de la conscience, elle devient de plus en plus brillante ! Elle m'appelle..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_95087_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "Durant notre enfance, Castor et moi étions tous deux des Saints Enfants. À l'époque, je pensais qu'il était trop lent et maladroit, et qu'il avait besoin que je lui montre la direction à suivre. Aujourd'hui, en comprenant le chemin que vous avez parcouru, je réalise que les fondations du monde sont construites par des personnes intègres et déterminées comme vous et lui."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_95088_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Ma lumière, depuis que j'ai reçu votre guidance, je crois que j'ai enfin emprunté le chemin totalement correct. Cependant, votre fidèle et humble serviteur a encore une énigme à résoudre : ce sanctuaire immaculé mentionné dans les légendes, est-il également sous votre autorité ? Il n'existe pas une telle chose ? Voulez-vous dire par là… que le sanctuaire immaculé se trouve en ce monde, au sein même des cœurs purs des justes ?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Ce cœur qui perçoit la volonté divine se rapproche davantage de vous."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "Vous... Vous avez un message à me transmettre ? Votre disciple est prêt à écouter vos enseignements à tout moment."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Éclairez-moi, guide égaré ! Grâce à votre lumière, j’ai vu tout ce que je devais voir… Avec ce corps maudit, je purifierai tout le passé et plongerai tout le futur sous cette lumière !"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_95092_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Cœur sacré en guise de mèche, la lumière brille éternellement !"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Poursuivre le salut dans un monde cruel ? Allez-y, petit plein d'espoir."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_95391_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Tiens, amuse-toi avec ça. On m'a dit que c'étaient des objets Tabou découverts dans des ruines. Je n'ai aucun intérêt pour ces choses imprégnées de leur odeur. J'avais l'intention de les brûler directement, mais comme ça pourrait peut-être t'être utile, je te les ai apportés. \nTu me demandes comment je les ai obtenus ? Évidemment, certaines personnes me les ont « volontairement » donnés. Ne t'inquiète pas, la provenance est « propre »."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_95392_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Chasse terminée, la récompense sera le sourire du petit."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "Sais-tu, petit, que les balles tirées par ces deux pistolets ne sont pas des balles ordinaires, mais l'incarnation du Désir et de la Malveillance ?\nCe Chaos désordonné forme des flammes semblables à de la chair, et lors de la septième détonation de l'autre côté, il entraînera tout dans les enfers pour les consumer."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Bavardage · À propos des armes à feu"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Ne vous forcez pas trop, mon Gardien du Secret. Bien que je sache qu'il s'agit d'un chemin tortueux où chaque instant compte, et qu'une erreur pourrait entraîner des conséquences irréversibles, si vous continuez ainsi, un jour viendra où vous tomberez, épuisé. Si nécessaire, venez me parler, en tant que membre de la famille."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_95395_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Brûler, détruire, hurler !"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "Disparaître."
  },
  Voice_95397_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_95398_AwakerVoiceContent = {
    Text = "Ma vision est devenue plus claire, j'ai vu ce qui se cache sous l'abîme... Pour vous, je dois obtenir une force encore plus grande..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_95398_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Viens, Gardien du Secret, assieds-toi plus près. Tu es trop distant maintenant. \nSais-tu que la première fois que je t'ai vu, je n'aurais jamais imaginé qu'un jour, je pourrais retirer devant toi cette carapace qu'on dit cruelle et froide. C'est un peu ridicule, n'est-ce pas ? Le redoutable Maître de l'Explosion qui aspire finalement à avoir un proche à qui confier son cœur. \nPromets-moi que si un jour tu ne tiens plus... tu prononceras mon nom en pensée, et je t'emporterai avec moi, vers mon royaume. Bien que cela ne retarde que l'inévitable, du moins, à la toute fin, pourras-tu enfin te reposer en paix dans mes bras."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_95399_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Accueillez la fin."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_95402_AwakerVoiceContent = {
    Text = "Dans l'éclat éblouissant des milliards de désirs et de malices, brûle !"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "Un banquet de célébration est toujours nécessaire après une chasse réussie. Allez, viens, goûte ma viande de chameau rôtie et mon agave fraîchement obtenue. Attends, petit, tu ne peux pas boire d'alcool... Alors bois plutôt mon jus spécial !"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_95403_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "Qu'y a-t-il, petit ? Veux-tu un câlin ? Allez, viens, mon torse brûlant t'attend… Haha, ne sois pas timide, il est tout à fait normal qu'une grande sœur s'intéresse aux plus jeunes, non ?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_95406_AwakerVoiceContent = {Text = "Mort."},
  Voice_95406_AwakerVoiceTitle = {
    Text = "Frappe · II"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "<Yellow:Souffle de la mort>"
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Retraite d'abord, je couvre nos arrières... Ne t'inquiète pas, je reviendrai vivant."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Venez, réduisons tout en cendres !"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Feu explosif, rallume-toi ici !"
  },
  Voice_95410_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_95411_AwakerVoiceContent = {
    Text = "Les flammes deviennent de plus en plus brûlantes. Le petit veut-il voir un magnifique feu d'artifice ?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Ces individus qui bafouent l'humanité, se cachent dans l'ombre et utilisent @1 comme matière première pour leurs sacrifices et recherches impurs... un jour, je les tuerai tous."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Boum !"},
  Voice_95413_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "Je le trouverai, peu importe où il se cache dans l'univers, je finirai par le trouver. Je veux que ce sale rat paie de tout ce qu'il possède. Le jour où je le trouverai, toute joie et tout plaisir dans ce monde seront brûlés dans les flammes de l'enfer. Ne t'inquiète pas, lors de ses funérailles, je te réserverai un siège de première classe, pour que nous puissions ensemble savourer son dernier cri d'agonie."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Écoute ce cri de détresse, celui de la fonte des étoiles."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_95415_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Accueille la fin."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Tu es certainement la famille dont je suis fier, sois confiant, mon Gardien du Secret ! Quoi qu'il arrive, je serai toujours ton soutien le plus solide."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Les entités indicibles qui rongent ce monde seront inévitablement tes ennemies. Mais cela n'a pas d'importance, car je serai derrière toi."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_95418_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Brûlez, détruisez, hurlez !"
  },
  Voice_95420_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_95421_AwakerVoiceContent = {
    Text = "Rester calme."
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_95422_AwakerVoiceContent = {Text = "Recule."},
  Voice_95422_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "Tu me demandes ce que je pense de la Corruption ? C'est comme demander à un petit rat qui rôde dans les égouts ce qu'il pense du seigneur hautain perché sur son trône. Ma réponse est simple : une répulsion instinctive du corps. Si possible, je voudrais savourer tranquillement un délicieux vin de lait de chameau tout en écoutant leurs cris perçants lorsqu'ils tombent sous mes balles."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Veux-tu que les flammes soient encore plus brûlantes ?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_95424_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Je ne viens ici que lorsque j'accepte une mission. Si le petit veut me trouver, qu'il utilise donc ce sortilège. Alors, répète après moi : ……………… Ia ! KathiguRa !"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Autrefois, nous survivions encore dans ce vieux village délabré, en nous débrouillant avec férocité et ruse. Même devenus une « grande force » reconnue, nous devions rester extrêmement vigilants face aux maîtres, aux gardes armés et aux « nobles chevaliers » qui refusaient de quitter la scène historique. Mais aujourd'hui, tout est différent : vous êtes désormais mes « compagnons », et n'avez plus besoin de plier devant les caprices des autres. Bon, il y a encore un petit qui erre quelque part dehors, mais je suis sûr qu'il se débrouillera bien. Après tout, chaque fois que j'étais occupé ailleurs, c'était justement lui qui s'occupait des autres."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Bavardage · À propos de la famille"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "C'est donc l'ennemi du petit ? Alors... la chasse commence."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Je suis le Maître de l'Explosion que l'on n'oubliera jamais ! Proclamez ! Toutes choses périront !"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Sur-exaltation Aliemus Burst·II"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "La combustion et la destruction sont tout pour moi, je suis passionné par la mort apportée par la chasse... Tu penses que je dirais ça ? \nHa ha, c'était une blague. Pour moi, ce qui compte le plus sont évidemment tous ceux qui sont autour de moi. Rien n'est plus important que ça, même... moi-même."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses aimées"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "Le petit a des ennuis ? Alors réponds à l'appel, Katigura arrivera avec la destruction. Que tous les ennuis s'évanouissent en un clin d'œil."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Réveiller"},
  Voice_95431_AwakerVoiceContent = {
    Text = "La saveur de la force, veux-tu chercher quelques malchanceux pour t'exercer sur eux ?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Illuminer · Réflexion"
  },
  Voice_95431_UnlockDesc = {
    Text = "Niveau d'illumination atteint 3 déverrouillé"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Je suis le Maître de l'Explosion que rien ne peut oublier ! Proclamation ! Toutes choses périront !"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "La reine légendaire d'Aran, le grand corps de désir Tifreyesod, je l'ai aperçue une fois lors de la traque de N. Bien que je ne valide pas ses actions, je dois reconnaître honnêtement que si cette voie était la seule permettant à tous de survivre au « Son » regard… j'aurais fait le même choix. De ce point de vue, il n'y a pas grande différence entre elle et moi."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Bavardage : À propos de Thaisis"
  },
  Voice_95433_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Thais »"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Très bonne prise en main, l'arme est bien entretenue."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Gagnez un Boost · I"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Je suis le feu, la flamme, le chaos qui brûle éternellement... Je vous ramènerai tous... chez vous..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_95435_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "La tour gothique dégage ici une odeur classique, et les éveillés qui s'y trouvent dégagent une senteur que je n'ai jamais perçue auparavant — à la fois un parfum de mort et une légère odeur vivante et animée. C'est vraiment... tentant d'y goûter."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de Missaga"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Celui qui cherche la mort, je réaliserai ton souhait."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Exalt · Deux"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Je n'ai plus la patience d'attendre le début."
  },
  Voice_96363_AwakerVoiceTitle = {Text = "Éveiller"},
  Voice_96364_AwakerVoiceContent = {
    Text = "Vous sentez votre cœur battre, n'est-ce pas ? Venez, mon cher invité, devenez mon hôte d'honneur et partagez ce festin avec moi. Laissez-moi vous guider pour savourer ensemble l'âme délicate de chaque esprit défunt."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Illuminer · Épanouissement"
  },
  Voice_96364_UnlockDesc = {
    Text = "Niveau d'illumination atteint 15 déverrouillé"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Chut, ne parle pas, écoutons ensemble les voix des morts."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Affinité · Un"
  },
  Voice_96365_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 2"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "La beauté éternelle est notre foi. Appliquer lentement la dissolution sur les êtres vivants, effacer toute trace d'existence... Pour la vie, c'est une torture pure et cruelle."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Bavardage · sur la crise"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Tout comme moi, Pickman recherche également l'art éternel, nous aurions dû devenir de meilleurs amis. Mais il considère que manger est un acte destructeur de l'éternité, une vision artistique vraiment trop étroite."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Bavardage · à propos de Pickman"
  },
  Voice_96367_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Pickman »"
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ha !"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "Frappez·Un"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "Aucun adjectif ne saurait décrire l'arôme enivrant qui émane de toi, mêlant à la fois l'arrière-goût acide et généreux du vin de Bordeaux et la richesse onctueuse et parfumée d'un gâteau à la crème. Ah... Attendre le jour de ta mort deviendra peut-être la chose la plus importante de ma vie."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du gardien des secrets"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "J'ai déjà vu une scène de crime : un homme découpait peu à peu la peau, les ongles, les mains et les pieds d'une jeune fille, tout en la soignant constamment. Il ne voulait pas qu'elle meure, ni qu'elle survive. Je ne pouvais évidemment pas lui accorder une mort paisible, je l'ai donc fait vivre continuellement la même expérience qu'elle, cela fait plusieurs années maintenant... Pour celui qui profane la mort, c'est très équitable, n'est-ce pas ?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Bavardage·À propos des choses détestées"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Je suis le dieu qui préside sur la mort, mais ne vous y trompez pas, je ne crée jamais la mort. Je ne fais que suivre ses traces et cueillir le fruit abondant et mûr."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Illuminer · Vue lointaine"
  },
  Voice_96371_UnlockDesc = {
    Text = "Niveau d'illumination atteint 1 déverrouillé"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Avez-vous aussi soif de mon parfum, Excellence le Gardien du Secret ?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Bavardage·À propos du toucher"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Aujourd'hui, qui devrions-nous servir à table ?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Début de l'enquête"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Je vous accorderai l'honneur de participer au dîner d'aujourd'hui."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Succès de l'enquête"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Vraiment pas élégant."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Frappe·III"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Je vais apporter un repos purifié."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Compétence·Un"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Avant chaque repas, je communique avec les esprits des défunts. Pour eux, être consommés et savourés avec attention représente une prolongation de leur existence et leur ultime moment de gloire. Tout comme nous les désirons, eux aussi aspirent à nous."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Affinité · Trois"
  },
  Voice_96377_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 6"
  },
  Voice_96378_AwakerVoiceContent = {Text = "Silence."},
  Voice_96378_AwakerVoiceTitle = {
    Text = "Coup·Quatre"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "Disparais dans l'ombre !"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Compétence·II"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "Il vaut mieux qu'on garde nos distances."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "Défense · I"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "Disparais dans l'ombre !"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Carte de compétence·Quatre"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Pourquoi es-tu si méfiant envers moi ? Tu ne devrais pas avoir peur, mordre un vivant va à l'encontre de mon esthétique."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Bavardage·À propos de la nourriture"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Celui qui cherche la mort, je réaliserai ton souhait."
  },
  Voice_96383_AwakerVoiceTitle = {Text = "Exaltation"},
  Voice_96384_AwakerVoiceContent = {
    Text = "Vraiment pas élégant."
  },
  Voice_96384_AwakerVoiceTitle = {Text = "Frappe·1"},
  Voice_96385_AwakerVoiceContent = {
    Text = "Faites attention."
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "Défense·II"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "Bien que l'enthousiasme de cette demoiselle soit vraiment touchant, son odeur dégage une senteur humide qui a trop fermenté. Même si elle me supplie sans cesse d'y goûter, cela ne correspond vraiment pas à mes goûts, c'est vraiment embarrassant."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Chat·À propos de Leigh"
  },
  Voice_96386_UnlockDesc = {
    Text = "Débloqué après avoir obtenu le réveilleur « Leigh »"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "Saviez-vous que toutes les vies laissent un long écho lorsqu'elles s'éteignent ? Leurs tonalités, hautes ou basses, varient selon les êtres. Cet écho s'étire progressivement à partir du moment où la mort advient, jusqu'à se dissiper lentement entre le ciel et la terre, comme un cri mêlé à un soupir."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Affinité · Deux"
  },
  Voice_96387_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 4"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "Soyez sans crainte, Votre Excellence le Gardien du Secret, je resterai toujours à vos côtés jusqu'au jour inévitable où votre vie parviendra à son terme. Ce jour-là, je vous dévorerai entièrement, corps après corps, selon le rituel le plus solennel qui soit. Je garderai votre âme éternellement en moi."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Affinité · Cinq"
  },
  Voice_96388_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 10"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Tu ne peux pas sentir ton propre parfum ? C'est vraiment dommage, tu rates l'odeur la plus douce et la plus... Oh, pourquoi recules-tu ?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Affinité · Quatre"
  },
  Voice_96389_UnlockDesc = {
    Text = "Débloqué en atteignant le niveau d'affinité de 8"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Je peux déjà voir davantage de morts, le paysage de l'autre rive devient de plus en plus clair..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Gagnez un Boost·Trois"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Confie-moi ton corps, laisse-moi te savourer en détail, chaque goutte de sang, chaque morceau de chair, chaque os."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Surexaltation"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Des ingrédients différents nécessitent des traitements différents. Les abats doivent être marinés, les tendons des pattes sont meilleurs mijotés, les parties riches en graisse conviennent parfaitement à la fermentation et au vieillissement, les morceaux à la texture particulière peuvent être frits, grillés, voire transformés en aspic de viande à la forme élégante. Tout cela exige des choix minutieux. Bien entendu, préserver et mettre en valeur le goût naturel des ingrédients est une marque de respect indispensable."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Illuminer : Perspicacité"
  },
  Voice_96392_UnlockDesc = {
    Text = "Niveau d'illumination atteint 7 déverrouillé"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Ça risque d'être un peu froid."
  },
  Voice_96393_AwakerVoiceTitle = {
    Text = "Frappez·II"
  },
  Voice_96394_AwakerVoiceContent = {
    Text = "La combinaison des plats est également d'une grande subtilité : l'acidité et la douceur, le croquant et le tendre, la fraîcheur et la richesse, la texture fine et celle rugueuse, s'associent et se heurtent en superposant des saveurs progressives et des sensations contrastées. Ce n'est qu'en offrant des expériences différentes à l'entrée en bouche, à la mastication et en bouche finale, qu'un plat peut véritablement être considéré comme une nourriture délicieuse et captivante."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Illuminer · Construction"
  },
  Voice_96394_UnlockDesc = {
    Text = "Niveau d'illumination atteint 11 déverrouillé"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Je vous remercie chaleureusement, je me sens très honoré."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Mise à niveau·II"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Des plats délicieux méritent toujours d'être attendus davantage."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Enquête arrêtée"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Je ne suis certainement pas un monstre mangeant de la viande crue et buvant du sang frais. Le processus de dégustation de la mort doit être digne et élégant. Tu dois communiquer et comprendre chaque ingrédient avec respect, car chaque saveur est unique."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Illuminer : Reflechir"
  },
  Voice_96397_UnlockDesc = {
    Text = "Niveau d'illumination atteint 2 déverrouillé"
  },
  Voice_96398_AwakerVoiceContent = {
